```jac
"""Weather sweep: walk linked stations, log each reading, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has locations: list[str] = [];
    has temps: list[float] = [];

    can start with Root entry {
        print("Starting weather sweep...");
        visit [-->] else { disengage; };
    }

    can read_station with WeatherStation entry {
        print(f"{here.location}: {here.celsius}°C");
        self.locations.append(here.location);
        self.temps.append(here.celsius);
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Hillside", celsius=26.3)
        ++> WeatherStation(location="Airport", celsius=20.1);

    sweep = WeatherSweep();
    root spawn sweep;

    print("--- Full readings ---");
    for (i, loc) in enumerate(sweep.locations) {
        print(f"  {loc}: {sweep.temps[i]}°C");
    }
    low = min(sweep.temps);
    high = max(sweep.temps);
    print(f"Min: {low}°C, Max: {high}°C");
}
