```jac
"""Rental shop media shelf audit.

Books and DVDs each have their own audit ability; anything else on
the shelf that is neither (e.g. an old archive reel) falls through to
a default handling ability. A single union trigger covers the two
classified media types so the default path only fires for the rest.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has year: int = 0;
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

# An unclassified shelf item (e.g. an old archive reel) - exercises
# the default handling path.
node ArchiveReel {
    has label: str = "";
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Book | DVD entry {
        self.total += 1;
        status = "IN" if here.available else "OUT";
        if isinstance(here, Book) {
            print(f"[BOOK][{status}] {here.title} by {here.author} ({here.year})");
        } else {
            print(f"[DVD][{status}] {here.title} ({here.runtime} min)");
        }
        visit [-->];
    }

    can fallback with ArchiveReel entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"[DEFAULT] unclassified item: {here.label}");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", author="Frank Herbert", year=1965)
        ++> DVD(title="Blade Runner", runtime=117)
        ++> ArchiveReel(label="Reel #42 - unmarked")
        ++> Book(title="Neuromancer", author="William Gibson", year=1984, available=False)
        ++> DVD(title="Arrival", runtime=116);

    auditor = Auditor();
    root spawn auditor;
    print(f"Audited {auditor.total} items; {auditor.defaulted} fell through to default handling");
}
