```jac
"""Tiny dungeon crawler: a hunter walker traverses chained rooms and
bails out the moment it spots the treasure vault."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_inspected += 1;
        print(f"Hunter enters '{here.name}' (#{self.rooms_inspected})");
        if here.has_treasure {
            print(f"Treasure found in '{here.name}'! Search ends.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", has_treasure=True);
    secret = Room(name="Secret Chamber");
    crypt = Room(name="Crypt");

    root ++> entrance ++> hallway ++> armory ++> vault ++> secret ++> crypt;

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter inspected {hunter.rooms_inspected} rooms total.");
}
```

```jac
"""Quiz app grader: walk quiz nodes, collect strictly typed integer scores, and compute the class average."""

node Quiz {
    has student_name: str = "";
    has score: int = 0;
}

walker Grader {
    has reports: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        report here.score;
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=88)
        ++> Quiz(student_name="Dave", score=76)
        ++> Quiz(student_name="Eve", score=95);

    grader = root spawn Grader();
    collected = grader.reports;

    print(f"Collected scores: {collected}");

    total = 0;
    for s in collected {
        total += s;
    }
    count = len(collected);
    class_avg = total / count if count > 0 else 0.0;
    print(f"Class average: {class_avg}");
}
```

