"""Road-trip playlist: tracks chained inline off root, played in order by a walker."""

node Track {
    has title: str = "";
    has runtime_min: int = 0;
    has available: bool = True;
}

walker Player {
    has total_min: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can play with Track entry {
        status = "PLAY" if here.available else "SKIP";
        self.total_min = self.total_min + here.runtime_min;
        print(f"[{status}] {here.title} ({here.runtime_min} min) - total {self.total_min} min");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Track(title="Highway Sun", runtime_min=4)
        ++> Track(title="Desert Wind", runtime_min=5)
        ++> Track(title="Coastline Cruise", runtime_min=6);
    root spawn Player();
}
