```jac
"""Continuation tokens bound to repository root, snapshot, scope, normalized request,
ordering, and resume position. A continuation reused after any binding change must
be rejected with a typed outcome; a valid continuation resumes deterministically.
"""

# --- Edge archetypes -------------------------------------------------------

edge OwnsSnapshot {
    has snapshot_id: str = "";
}

edge HoldsScope {
    has scope: str = "";
}

edge HoldsRequest {
    has normalized_query: str = "";
}

edge HoldsOrdering {
    has ordering: str = "";
}

# --- Node archetypes -------------------------------------------------------

node RepositoryRoot {
    has root_id: str = "";
}

node Snapshot {
    has snapshot_id: str = "";
}

node QueryScope {
    has scope: str = "";
}

node NormalizedRequest {
    has normalized_query: str = "";
}

node Ordering {
    has ordering: str = "";
}

node ContinuationToken {
    # The opaque public surface: a single-use resume handle.
    has token_id: str = "";
    has resume_position: int = 0;
    # Whether this token has already been consumed.
    has consumed: bool = False;
    # Whether this token has been declared stale.
    has stale: bool = False;
}

# --- Walker: validates and resumes a continuation --------------------------

walker ContinuationAudit {
    # The bindings the caller claims for this resume attempt.
    has claim_root_id: str = "";
    has claim_snapshot_id: str = "";
    has claim_scope: str = "";
    has claim_query: str = "";
    has claim_ordering: str = "";
    has claim_resume_position: int = -1;

    # Result captured during the walk.
    has outcome: str = "";
    has rows_resumed: int = 0;

    can start with Root entry {
        # Walk into the repository root via the owning typed edge.
        visit [->:OwnsSnapshot:->];
    }

    can bind_root with RepositoryRoot entry {
        if here.root_id != self.claim_root_id {
            self.outcome = "REJECTED_ROOT";
            disengage;
        }
        visit [->:OwnsSnapshot:->];
    }

    can bind_snapshot with Snapshot entry {
        if here.snapshot_id != self.claim_snapshot_id {
            self.outcome = "REJECTED_SNAPSHOT";
            disengage;
        }
        visit [->:HoldsScope:->];
    }

    can bind_scope with QueryScope entry {
        if here.scope != self.claim_scope {
            self.outcome = "REJECTED_SCOPE";
            disengage;
        }
        visit [->:HoldsRequest:->];
    }

    can bind_request with NormalizedRequest entry {
        if here.normalized_query != self.claim_query {
            self.outcome = "REJECTED_QUERY";
            disengage;
        }
        visit [->:HoldsOrdering:->];
    }

    can bind_ordering with Ordering entry {
        if here.ordering != self.claim_ordering {
            self.outcome = "REJECTED_ORDERING";
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can bind_token with ContinuationToken entry {
        # A consumed or stale token cannot be reused.
        if here.consumed {
            self.outcome = "REJECTED_CONSUMED";
            disengage;
        }
        if here.stale {
            self.outcome = "REJECTED_STALE";
            disengage;
        }
        if here.resume_position != self.claim_resume_position {
            self.outcome = "REJECTED_POSITION";
            disengage;
        }
        # Mark the token consumed on a successful resume.
        here.consumed = True;
        self.rows_resumed = here.resume_position;
        self.outcome = "RESUMED";
        disengage;
    }
}

# --- Walker: simulates a truncation result and surfaces its non-terminality -

walker TruncationProbe {
    has page_size: int = 0;
    has total_known: int = 0;
    has terminal_appearance: bool = False;

    can start with Root entry {
        # Truncation must never be reported as a terminal completeness signal.
        if self.page_size < self.total_known {
            self.terminal_appearance = False;
        } else {
            self.terminal_appearance = True;
        }
        visit [-->] else { disengage; };
    }
}

# --- Demonstration graph ---------------------------------------------------

with entry {
    # A repository owns a snapshot, which holds a scope, request, and ordering,
    # and finally the continuation token that resumes a paginated traversal.
    repo = RepositoryRoot(root_id="repo-7");
    snap = Snapshot(snapshot_id="snap-2024-11-01");
    scope = QueryScope(scope="public_symbols");
    req = NormalizedRequest(normalized_query="name:continuation AND kind:edge");
    order = Ordering(ordering="alpha:asc");
    tok = ContinuationToken(token_id="ct-1", resume_position=40);

    repo +>:OwnsSnapshot(snapshot_id="snap-2024-11-01"):+> snap;
    snap +>:HoldsScope(scope="public_symbols"):+> scope;
    scope +>:HoldsRequest(normalized_query="name:continuation AND kind:edge"):+> req;
    req +>:HoldsOrdering(ordering="alpha:asc"):+> order;
    order +>:HoldsOrdering:+> tok;

    # 1. Valid resume: every binding matches and the token is fresh.
    audit = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn audit;
    print(f"valid resume -> {audit.outcome}, rows={audit.rows_resumed}");

    # 2. Reused after snapshot change -> typed rejection.
    bad = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-02",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad;
    print(f"changed snapshot -> {bad.outcome}");

    # 3. Reused after query normalization -> typed rejection.
    bad_q = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad_q;
    print(f"changed query -> {bad_q.outcome}");

    # 4. Reused after resume position drift -> typed rejection.
    bad_p = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=80
    );
    repo spawn bad_p;
    print(f"drifted position -> {bad_p.outcome}");

    # 5. Truncation is non-terminal by construction.
    probe = TruncationProbe(page_size=50, total_known=137);
    root spawn probe;
    flag_label = "TERMINAL" if probe.terminal_appearance else "TRUNCATED";
    print(f"truncation flag -> {flag_label}");
}
```

```jac
"""Wildlife park feeding rounds: kiosk greets all visitors, zookeepers feed animals by species, school groups just watch."""

node Animal {
    has species: str = "";
    has name: str = "";
    has fed: bool = False;
}

node Lion {
    has species: str = "lion";
    has name: str = "";
    has fed: bool = False;
}

node Parrot {
    has species: str = "parrot";
    has name: str = "";
    has fed: bool = False;
}

walker Kiosk {
    can start with Root entry {
        print("[Kiosk] Welcome to the wildlife park!");
        visit [-->];
    }

    can greet with Lion | Parrot | Animal entry {
        print(f"[Kiosk] Enjoy your visit, and say hello to {here.name} the {here.species}!");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        print("[Zookeeper] Beginning feeding rounds...");
        visit [-->];
    }

    can feed_lion with Lion entry {
        meal = "meat";
        here.fed = True;
        print(f"[Zookeeper] Feeding {here.name} the lion a portion of {meal}.");
        visit [-->];
    }

    can feed_parrot with Parrot entry {
        meal = "seed";
        here.fed = True;
        print(f"[Zookeeper] Feeding {here.name} the parrot a handful of {meal}.");
        visit [-->];
    }

    can feed_generic with Animal entry {
        meal = "standard feed";
        here.fed = True;
        print(f"[Zookeeper] Feeding {here.name} the {here.species} some {meal}.");
        visit [-->];
    }
}

walker SchoolGroup {
    can start with Root entry {
        print("[SchoolGroup] The children look around excitedly...");
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        print(f"[SchoolGroup] The children watch {here.name} the {here.species} in awe.");
        visit [-->];
    }
}

with entry {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    goldie = Animal(species="goldfish", name="Goldie");
    root ++> simba ++> polly ++> goldie;

    root spawn Kiosk();
    print("");
    root spawn Zookeeper();
    print("");
    root spawn SchoolGroup();
}
