```jac
"""Layered adjacency graph: model a column_graph with per-layer offsets/value
sources and a walker that audits all layers top-to-bottom, certifying
monotonic offsets, uniform row counts, and emptiness encoding.

The hand-rolled machinery this replaces: a list-of-layers where each
layer was a list of (offset, value) rows walked by index with manual
recursion to validate row count, monotonicity, and empty-layer encoding.
Here the layers are typed nodes linked by ``Adjacency`` edges and the
audit is a walker that traverses the graph natively.
"""

node Layer {
    has layer_index: int = 0;
    has row_count: int = 0;
    has offsets: list[int] = [];
    has values: list[int] = [];
    has checksum_ok: bool = True;
}

node Graph {
    has name: str = "";
    has layer_count: int = 0;
}

edge Adjacency {
    has label: str = "";
}

walker Auditor {
    has bad_layers: list[str] = [];
    has graph_name: str = "";
    has declared_layers: int = 0;
    has seen_layers: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can descend with Graph entry {
        self.graph_name = here.name;
        self.declared_layers = here.layer_count;
        self.seen_layers = 0;
        print(f"auditing graph '{here.name}' (declared layers={here.layer_count})");
        visit [->:Adjacency:->];
    }

    can audit with Layer entry {
        self.seen_layers = self.seen_layers + 1;

        # Row count vs offsets length: equal offsets means an empty layer
        # (a single [0] in offsets represents zero rows).
        offsets_len = len(here.offsets);
        empty_layer = offsets_len == 1 and here.offsets[0] == 0
            and here.row_count == 0;
        valid_rows = here.row_count == max(0, offsets_len - 1);

        # Monotonic non-decreasing offsets.
        monotonic = True;
        prev = 0;
        for off in here.offsets {
            if off < prev {
                monotonic = False;
            }
            prev = off;
        }

        # Values length must equal last offset.
        last_off = here.offsets[-1] if here.offsets else 0;
        values_match = len(here.values) == last_off;

        ok = (valid_rows or empty_layer) and monotonic and values_match and here.checksum_ok;

        status = "OK" if ok else "BAD";
        print(
            f"[{status}] layer={here.layer_index} "
            f"rows={here.row_count} offsets={here.offsets} "
            f"values={here.values} checksum={here.checksum_ok}"
        );

        if not ok {
            self.bad_layers.append(
                f"layer {here.layer_index}: rows={here.row_count} "
                f"offsets={here.offsets} values={here.values} "
                f"monotonic={monotonic} values_match={values_match}"
            );
        }

        visit [-->];
    }
}

walker Cascade {
    has dropped: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can drop_graph with Graph entry {
        print(f"cascade: invalidating graph {here.name}");
        visit [->:Adjacency:->];
    }

    can drop_layer with Layer entry {
        self.dropped = self.dropped + 1;
        print(f"cascade: dropping layer {here.layer_index}");
        del here;
        # No further visit: here is gone.
    }
}

with entry {
    g = Graph(name="column_graph", layer_count=3);

    # Layer 0: real data, monotonic offsets, values match.
    l0 = Layer(
        layer_index=0,
        row_count=3,
        offsets=[0, 1, 2, 3],
        values=[10, 20, 30],
    );

    # Layer 1: empty layer — equal offsets (a single 0).
    l1 = Layer(
        layer_index=1,
        row_count=0,
        offsets=[0],
        values=[],
    );

    # Layer 2: intentional corruption (non-monotonic, bad values length).
    l2_bad = Layer(
        layer_index=2,
        row_count=2,
        offsets=[0, 2, 1],
        values=[7, 7],
        checksum_ok=False,
    );

    g +>:Adjacency(label="layer_0"):+> l0;
    g +>:Adjacency(label="layer_1"):+> l1;
    g +>:Adjacency(label="layer_2"):+> l2_bad;

    root ++> g;

    print("=== first audit pass ===");
    auditor = Auditor();
    root spawn auditor;
    print(
        f"summary: graph='{auditor.graph_name}' "
        f"declared={auditor.declared_layers} seen={auditor.seen_layers} "
        f"bad={len(auditor.bad_layers)}"
    );
    for b in auditor.bad_layers {
        print(f"  bad layer -> {b}");
    }

    print("=== cascade delete pass ===");
    cascade = Cascade();
    root spawn cascade;
    print(f"cascade dropped {cascade.dropped} layer(s)");
}
