    g02 = CompletionGroup(code="G02", description="SCORE_AND_CONTEXT_CONTINUITY");
    g03 = CompletionGroup(code="G03", description="DAILY_MEMORY_ONLY_DREAM");
    g04 = CompletionGroup(code="G04", description="EVALUATED_RHYTHM_LEARNING");
    g05 = CompletionGroup(code="G05", description="SCHEDULED_DAILY_AUTONOMY_AND_BOUNDED_SYNC");

    g01 +>:GroupContains:+> blueprint;
    g01 +>:GroupContains:+> intent;
    g01 +>:GroupContains:+> scheduler;
    g01 +>:GroupContains:+> recovery;
    g02 +>:GroupContains:+> continuity;
    g03 +>:GroupContains:+> concern;
    g03 +>:GroupContains:+> admission;
    g03 +>:GroupContains:+> dream;
    g04 +>:GroupContains:+> rhythm;
    g05 +>:GroupContains:+> autonomy;

    windows_scope = Scope(
        name="root-vex-operations.windows-vexlife.g01",
        completion_state="DETERMINISTIC_FOUNDATION_ACCEPTED_LIVED_COMPANION_LOOP_NOT_STARTED",
        target="VEX_CAN_DREAM_CONSOLIDATE_LEARN_AND_REAWAKEN_AUTONOMOUSLY_EACH_DAY_UNDER_STANDING_CONSENT_AND_BOUNDED_POLICY"
    );

