```jac
"""Weather station sweep: visit each station, report temperatures live, then summarize readings."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[str] = [];
    has min_c: float = 0.0;
    has max_c: float = 0.0;
    has count: int = 0;

    def record_reading(loc: str, temp: float) {
        line = f"{loc}: {temp}C";
        self.readings.append(line);
        if self.count == 0 {
            self.min_c = temp;
            self.max_c = temp;
        } else {
            if temp < self.min_c {
                self.min_c = temp;
            }
            if temp > self.max_c {
                self.max_c = temp;
            }
        }
        self.count += 1;
    }

    def print_summary() {
        print("--- Sweep complete ---");
        print(f"Readings: {self.readings}");
        if self.count > 0 {
            print(f"Min: {self.min_c}C");
            print(f"Max: {self.max_c}C");
        } else {
            print("No readings collected.");
        }
    }

    can start with Root entry {
        visit [-->] else {
            self.print_summary();
            disengage;
        }
    }

    can scan with WeatherStation entry {
        print(f"[{here.location}] {here.celsius}C");
        self.record_reading(here.location, here.celsius);
        visit [-->] else {
            self.print_summary();
            disengage;
        }
    }
}

with entry {
    root ++> WeatherStation(location="Seattle", celsius=12.5)
        ++> WeatherStation(location="Phoenix", celsius=38.2)
        ++> WeatherStation(location="Denver", celsius=22.0)
        ++> WeatherStation(location="Miami", celsius=31.7);
    root spawn WeatherSweep();
}
