```jac
"""Moderation sweep over game accounts.

Three archetypes coexist:
- ``Member``: standard accounts get a normal audit.
- ``Admin``: privileged accounts get their reputation boosted by 5.
- ``WelcomeDesk``: a node ability that fires for ANY walker passing through.

A single ``Moderator`` walker audits the trail. A second ``Bot`` walker
proves the welcome-desk ability fires for every walker type, because the
ability is declared on the welcome desk itself with a plain ``entry``
trigger (fires for every walker, regardless of type).
"""

node Account {
    has handle: str = "";
    has reputation: int = 0;
}

node Member(Account) {
}

node Admin(Account) {
}

node WelcomeDesk {
    has desk_name: str = "Front Desk";

    # Fires for ANY walker entering this node (no walker-type filter).
    can greet with entry {
        print(f"[{self.desk_name}] Welcome to the lobby!");
    }
}

walker Moderator {
    can start with Root entry {
        print("Moderator beginning sweep...");
        visit [-->];
    }

    can audit with Member | Admin entry {
        if here.reputation >= 80 and here.handle == "overLord" {
            here.reputation = here.reputation + 5;
            print(f"[AUDIT] admin {here.handle} (rep boosted to {here.reputation})");
        } else {
            print(f"[AUDIT] member {here.handle} (rep={here.reputation}) -- OK");
        }
        visit [-->];
    }

    can pass_through with WelcomeDesk entry {
        visit [-->];
    }
}

# A second walker type to prove the welcome desk greets EVERY walker.
walker Bot {
    has serial: str = "";

    can start with Root entry {
        print(f"Bot {self.serial} entering the facility");
        visit [-->];
    }

    can roam with Member | Admin entry {
        visit [-->];
    }

    can pass_through with WelcomeDesk entry {
        visit [-->];
    }
}

with entry {
    desk = WelcomeDesk(desk_name="Front Desk");
    desk2 = WelcomeDesk(desk_name="VIP Lobby");

    moderator_alley = Member(handle="shadowFox", reputation=42);
    admin_alley = Admin(handle="overLord", reputation=88);
    newbie = Member(handle="rookieOne", reputation=0);
    chief = Admin(handle="sysOp", reputation=120);

    root ++> desk
        ++> moderator_alley
        ++> admin_alley
        ++> desk2
        ++> newbie
        ++> chief;

    print("--- Moderator sweep ---");
    root spawn Moderator();

    print("--- Bot passes through (desk greets any walker) ---");
    root spawn Bot(serial="B-7");
}
```

```jac
"""Rental shop media shelf audit.

Books and DVDs each have a dedicated entry ability on the Audit walker;
anything else (unclassified archive reels, etc.) falls through to a
default entry ability. The walker counts total items audited and how
many needed the default path.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

node Reel {
    has title: str = "";
    has medium: str = "";
    has available: bool = True;
}

walker Auditor {
    has total: int = 0;
    has default_count: int = 0;
    has path: list = [];

    can start with Root entry {
        print("Beginning shelf audit...");
        visit [-->] else { disengage; }
    }

    can audit_book with Book entry {
        self.total += 1;
        self.path = self.path + ["book"];
        status = "IN" if here.available else "OUT";
        print(f"  [BOOK/{status}] {here.title} by {here.author}");
        visit [-->] else { disengage; }
    }

    can audit_dvd with DVD entry {
        self.total += 1;
        self.path = self.path + ["dvd"];
        status = "IN" if here.available else "OUT";
        print(f"  [DVD/{status}] {here.title} ({here.runtime} min)");
        visit [-->] else { disengage; }
    }

    # Default handler: fires for any node type that doesn't match Book or DVD.
    can audit_default with Reel entry {
        self.total += 1;
        self.default_count += 1;
        self.path = self.path + ["default"];
        status = "IN" if here.available else "OUT";
        print(f"  [REEL/{status}] unclassified item: {here.title} ({here.medium})");
        visit [-->] else { disengage; }
    }
}

with entry {
    shelf1 = Book(title="The Hobbit", author="Tolkien");
    shelf2 = DVD(title="Blade Runner", runtime=117);
    shelf3 = Reel(title="Newsreel 1942", medium="film");
    shelf4 = Book(title="Dune", author="Herbert", available=False);
    shelf5 = DVD(title="Spirited Away", runtime=125, available=False);
    shelf6 = Reel(title="Promo Reel", medium="magnetic");

    root ++> shelf1
        ++> shelf2
        ++> shelf3
        ++> shelf4
        ++> shelf5
        ++> shelf6;

    auditor = Auditor();
    root spawn auditor;

    print("");
    print(f"Audit complete: {auditor.total} items audited, {auditor.default_count} took the default path");
    print(f"Path taken: {auditor.path}");
}
