```jac
"""Warehouse packing line: stations announce robots served; robots announce each station stop.

Models a three-station packing line where each station tracks which robot it has
served (boxes packed) and each robot tracks the stations it stopped at. A walker
walks the line, dispatching robots to stations and tallying stops/packs.
"""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
    has last_robot: str = "";

    def serve(robot_name: str) -> None {
        self.boxes_packed += 1;
        self.last_robot = robot_name;
        print(f"Station {self.name} announces: serving robot {robot_name} "
              f"(total packed: {self.boxes_packed})");
    }
}

node Robot {
    has name: str = "";
    has stops: int = 0;
    has stations_visited: list[str] = [];

    def stop_at(station: Station) -> None {
        self.stops += 1;
        self.stations_visited.append(station.name);
        print(f"Robot {self.name} announces: stopped at station {station.name} "
              f"(total stops: {self.stops})");
        station.serve(self.name);
    }
}

walker Dispatcher {
    has robot: Robot = Robot();

    can start with Root entry {
        print(f"Dispatcher dispatching robot {self.robot.name} onto the line");
        visit [-->];
    }

    can dispatch with Station entry {
        self.robot.stop_at(here);
        if here.name == "C" {
            visit [-->] else { disengage; }
        } else {
            visit [-->];
        }
    }
}

with entry {
    a = Station(name="A");
    b = Station(name="B");
    c = Station(name="C");
    root ++> a ++> b ++> c;

    r2 = Robot(name="R2");
    root spawn Dispatcher(robot=r2);
}
```

