"""Order audit: skip invalid orders but halt the whole walk on fraud."""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"HALT fraud flagged order {here.order_id} amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"SKIP invalid order {here.order_id} amount={here.amount}");
            } else {
                print(f"OK audited order {here.order_id} amount={here.amount}");
            }
            visit [-->];
        }
    }
}

with entry {
