        ++> Order(order_id="O-101", amount=10.00, valid=False)
        ++> Order(order_id="O-102", amount=75.00)
        ++> Order(order_id="O-103", amount=999.99, fraud=True)
        ++> Order(order_id="O-104", amount=15.00);
