```jac
"""Order auditor demonstrating both flavors of early return.

`skip` (per-order invalidity) lets the walker sidestep a single order and
keep auditing the rest of the chain, while `disengage` (fraud detection)
halts the whole walk on the spot. A line is printed per order showing
which action fired.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has flagged_fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning chain audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.flagged_fraud {
            print(f"FRAUD HALT -> {here.title} (${here.amount}) flagged, walking stopped");
            disengage;
        }
        if not here.valid {
            print(f"SKIP       -> {here.title} (${here.amount}) invalid, continuing");
            visit [-->];
        }
        print(f"AUDIT      -> {here.title} (${here.amount}) ok");
        visit [-->];
    }
}

with entry {
    o1 = Order(title="Order-001", amount=120.50, valid=True);
    o2 = Order(title="Order-002", amount=45.00, valid=False);
    o3 = Order(title="Order-003", amount=899.99, valid=True, flagged_fraud=True);
    o4 = Order(title="Order-004", amount=210.00, valid=True);
    root ++> o1 ++> o2 ++> o3 ++> o4;

    root spawn OrderAuditor();
}
