```jac
"""Deletion collector: models the cascade hazard of mutating a work list mid-traversal.

Demonstrates the idiomatic fix: snapshot the work list before iterating, walk via a
typed cascade edge, and guard against revisiting already-collected nodes.
"""

node Model {
    has name: str = "";
    has collected: bool = False;
    has visit_count: int = 0;

    def mark() -> None {
        self.collected = True;
        self.visit_count += 1;
    }
}

edge CascadesTo { }

walker DeletionCollector {
    has pending: list = [];
    has processed: list = [];

    can start with Root entry {
        # Snapshot the initial work list before iterating — mirrors the suggested fix
        # of calling collect(collector.objects) before the loop. Subsequent cascade
        # discoveries are appended to self.pending and drained in deterministic order,
        # so insertion during traversal is explicit, not incidental.
        for child in [-->] {
            self.pending.append(child);
        }
        visit [->:CascadesTo:->];
    }

    can drain with Model entry {
        if here.collected {
            # Already processed — guarded by the visited flag, closing the
            # double-visit half of the original hazard.
            visit [->:CascadesTo:->];
        } else {
            here.mark();
            self.processed.append(here.name);
            visit [->:CascadesTo:->];
        }
    }
}

walker CascadeDriver {
    has processed: list = [];

    can start with Root entry {
        # Seed the cascade by visiting every direct cascade target of the root.
        visit [->:CascadesTo:->];
    }

    can cascade with Model entry {
        if here.collected {
            visit [->:CascadesTo:->];
        } else {
            here.mark();
            self.processed.append(here.name);
            # Visit every cascade target — the typed edge replaces the manual
            # adjacency walk that the original Julia code hand-rolled.
            visit [->:CascadesTo:->];
        }
    }
}

with entry {
    # Build the five-model cascade fixture referenced in the issue
    # (Dmp_root -> Dmp_a, Dmp_b, Dmp_c -> Dmp_k topology), with extra
    # fan-out to force mid-traversal discovery semantics.
    dmp_root = Model(name="dmp_root");
    dmp_a = Model(name="dmp_a");
    dmp_b = Model(name="dmp_b");
    dmp_c = Model(name="dmp_c");
    dmp_k1 = Model(name="dmp_k_1");
    dmp_k2 = Model(name="dmp_k_2");

    # Wire cascades with typed edges so the relationship carries meaning.
    root +>:CascadesTo:+> dmp_root;
    dmp_root +>:CascadesTo:+> dmp_a;
    dmp_root +>:CascadesTo:+> dmp_b;
    dmp_root +>:CascadesTo:+> dmp_c;
    dmp_a +>:CascadesTo:+> dmp_k1;
    dmp_b +>:CascadesTo:+> dmp_k2;
    # A cross-link that the original code might visit twice without a guard.
    dmp_c +>:CascadesTo:+> dmp_k1;

    # Spawn a DeletionCollector walker — the walker that simulates the
    # process_collector! fix where the work list is snapshotted first.
    collector = DeletionCollector();
    root spawn collector;
    print(f"[DeletionCollector] processed: {collector.processed}");

    # Spawn a CascadeDriver walker to show explicit walk over typed edges.
    driver = CascadeDriver();
    root spawn driver;
    print(f"[CascadeDriver] processed: {driver.processed}");
}
