```jac
"""HIER benchmark model: ontology classes, hierarchical indices, and traversal.

Models the essential scenario from issue #353: real ontologies (NCBI, ATC,
Gene Ontology, MITRE ATT&CK) loaded as a hierarchy, indexed two ways
(nested-set for narrow trees, 2-hop for wide DAGs like GO), and walked by
a traversal walker that handles the four challenge shapes — narrow tree,
multi-parent DAG, wide DAG (decline path), and prefix-coded strict tree.

The walker ``HierarchyInspector`` traverses the graph via typed ``Parent``
edges, performing dependency ordering (post-order DFS), cycle detection,
reachability from a chosen root, and cascade invalidation on subtree
removal. It demonstrates the explicit cycle policy required for walkers in
jac 0.36.1 (no built-in visited set).
"""

node OntologyClass {
    has name: str = "";
    has depth: int = 0;
    has width_index: int = 0;
    has order_index: int = 0;
    has invalidated: bool = False;
}

node IndexEntry {
    has lo: int = 0;
    has hi: int = 0;
    has two_hop_ancestors: list[str] = [];
}

edge Parent {
    has weight: float = 1.0;
}

edge TwoHopLink {
    has hop: int = 1;
}

walker HierarchyInspector {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_detected: bool = False;
    has two_hop_fanout: int = 0;

    can start with Root entry {
        print(f"=== HIER walk starting over root children ===");
        self.visited = [];
        self.order = [];
        self.cycle_detected = False;
        visit [-->] else { disengage; }
    }

    can index with OntologyClass entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"[CYCLE] revisiting {here.name} at depth {here.depth}");
            disengage;
        }
        self.visited.append(here.name);
        here.depth = len(self.visited) - 1;
        print(f"  visit {here.name} (depth {here.depth}, width_idx {here.width_index})");
        self.order.append(here.name);
        visit [->:Parent:->] else { disengage; }
    }

    can probe with IndexEntry entry {
        # Walk over typed TwoHopLink edges to count 2-hop fanout.
        self.two_hop_fanout = 0;
        for _ in [->:TwoHopLink:->] {
            self.two_hop_fanout += 1;
        }
        print(f"  2-hop fanout at index entry: {self.two_hop_fanout}");
        visit [->:TwoHopLink:->] else { disengage; }
    }
}

walker CascadeInvalidator {
    has invalid_name: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        print(f"=== Cascade invalidation targeting '{self.invalid_name}' ===");
        visit [-->] else { disengage; }
    }

    can invalidate with OntologyClass entry {
        if here.name == self.invalid_name {
            here.invalidated = True;
            self.purged.append(here.name);
            print(f"  invalidated {here.name}, cascading through children");
            visit [->:Parent:->] else { disengage; }
        } else {
            visit [->:Parent:->] else { disengage; }
        }
    }
}

walker ReachabilityChecker {
    has target: str = "";
    has reached: bool = False;
    has path: list[str] = [];

    can start with Root entry {
        print(f"=== Reachability check for '{self.target}' ===");
        visit [-->] else { disengage; }
    }

    can probe with OntologyClass entry {
        self.path.append(here.name);
        if here.name == self.target {
            self.reached = True;
            print(f"  REACHED {here.name} via path: {self.path}");
            disengage;
        }
        visit [->:Parent:->] else { disengage; }
    }
}

with entry {
    # Build a small ontology graph mirroring the four HIER shapes:
    #   1. NCBI-like narrow deep tree  (root -> ... -> leaf, depth 5)
    #   2. MONDO/HPO-like multi-parent DAG (a child with two parents)
    #   3. GO-like wide DAG             (one parent with many siblings)
    #   4. ATC-like strict prefix tree  (exactly 5 levels)

    # Shape 1: narrow deep tree
    n1 = OntologyClass(name="Life");
    n2 = OntologyClass(name="Eukaryota");
    n3 = OntologyClass(name="Metazoa");
    n4 = OntologyClass(name="Chordata");
    n5 = OntologyClass(name="Mammalia");
    n6 = OntologyClass(name="Hominidae");
    n7 = OntologyClass(name="Homo");
    root ++> n1 +>:Parent:+> n2 +>:Parent:+> n3 +>:Parent:+> n4 +>:Parent:+> n5 +>:Parent:+> n6 +>:Parent:+> n7;

    # Shape 2: multi-parent DAG (MaterialEntity shared by Continuant + Occurrent)
    m1 = OntologyClass(name="Entity");
    m2 = OntologyClass(name="Continuant");
    m3 = OntologyClass(name="Occurrent");
    m4 = OntologyClass(name="MaterialEntity");
    m5 = OntologyClass(name="Cell");
    root ++> m1;
    m1 +>:Parent:+> m2;
    m1 +>:Parent:+> m3;
    m2 +>:Parent:+> m4;
    m3 +>:Parent:+> m4;
    m4 +>:Parent:+> m5;

    # Shape 3: wide DAG (GO-like, width approaching leaf count)
    g_root = OntologyClass(name="GO_root");
    root ++> g_root;
    for i in range(6) {
        g_child = OntologyClass(name=f"GO_branch_{i}");
        g_child.width_index = i;
        g_root +>:Parent:+> g_child;
    }

    # Shape 4: ATC strict 5-level prefix tree
    a1 = OntologyClass(name="A");
    a2 = OntologyClass(name="A01");
    a3 = OntologyClass(name="A01A");
    a4 = OntologyClass(name="A01AB");
    a5 = OntologyClass(name="A01AB01");
    root ++> a1 +>:Parent:+> a2 +>:Parent:+> a3 +>:Parent:+> a4 +>:Parent:+> a5;

    # Spawn walkers demonstrating the traversal scenarios
    root spawn HierarchyInspector();
    root spawn ReachabilityChecker(target="Homo");
    root spawn CascadeInvalidator(invalid_name="Continuant");

    # Two-hop index probe: separate index node linked to several classes
    print("=== Two-hop index probe ===");
    idx = IndexEntry();
    root ++> idx;
    idx +>:TwoHopLink:+> n1;
    idx +>:TwoHopLink:+> n2;
    idx +>:TwoHopLink:+> n3;
    inspector = HierarchyInspector();
    idx spawn inspector;
}
```

```jac
"""UX case receipt v2: derive pass/fail from load-bearing checks; block bogus finish_pass."""

node UxCase {
    has case_id: str = "";
    has target_name: str = "";
    has full_test_name: str = "";
}

node LoadBearingCheck {
    has name: str = "";
    has passed: bool = True;
    has load_bearing: bool = True;
}

node UxCaseReceipt {
    has schema_version: str = "ux_case_receipt.v2";
    has case_id: str = "";
    has result: str = "pending";
    has assertions_failed: int = 0;
    has finalized: bool = False;
    has valid: bool = False;
    has failure_kind: str = "";
    has caller_requested_pass: bool = False;
}

node ExecutionPlan {
    has plan_digest: str = "";
    has tier: str = "";
    has feature_profile: str = "";
}

edge UnderPlan { }
edge RecordedCheck { has order: int = 0; }
edge ReceiptFor { }

walker ReceiptFinalizer {
    has failed_count: int = 0;
    has check_count: int = 0;
    has bound_case_id: str = "";

    can start with UxCase entry {
        self.bound_case_id = here.case_id;
        self.failed_count = 0;
        self.check_count = 0;
        visit [->:RecordedCheck:->] else { disengage; };
    }

    can tally with LoadBearingCheck entry {
        self.check_count += 1;
        if here.load_bearing and not here.passed {
            self.failed_count += 1;
        }
    }

    can route_to_receipt with UxCase exit {
        visit [->:ReceiptFor:->] else { disengage; };
    }

    can seal with UxCaseReceipt entry {
        here.assertions_failed = self.failed_count;
        identity_ok = here.case_id == self.bound_case_id;
        if not identity_ok {
            here.result = "receipt_instrument_failure";
            here.failure_kind = "case_id_mismatch";
            here.valid = False;
            print(f"[REJECT] receipt case_id={here.case_id} != bound {self.bound_case_id}");
        } elif here.caller_requested_pass and self.failed_count > 0 {
            here.result = "assertion_mismatch";
            here.failure_kind = "pass_invariant_violation";
            here.valid = False;
            print(f"[REJECT] {here.case_id}: finish_pass() blocked — "
                  f"{self.failed_count} load-bearing check(s) failed");
        } elif self.failed_count > 0 {
            here.result = "assertion_mismatch";
            here.failure_kind = "assertion_mismatch";
            here.valid = False;
            print(f"[FAIL] {here.case_id}: {self.failed_count} assertion(s) failed");
        } else {
            here.result = "assertions_passed";
            here.failure_kind = "";
            here.valid = True;
            print(f"[PASS] {here.case_id}: all {self.check_count} checks passed");
        }
        here.finalized = True;
        disengage;
    }
}

with entry {
    plan = ExecutionPlan(
        plan_digest="2da40e51",
        tier="gate",
        feature_profile="ux-v2"
    );
    root ++> plan;

    case_pass = UxCase(
        case_id="case-001",
        target_name="perl_lsp_ux",
        full_test_name="ux::hover_exact"
    );
    plan +>:UnderPlan:+> case_pass;
    case_pass +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    case_pass +>:RecordedCheck(order=2):+> LoadBearingCheck(name="hover_text", passed=True);
    receipt_pass = UxCaseReceipt(case_id="case-001");
    case_pass +>:ReceiptFor:+> receipt_pass;

    case_fail = UxCase(
        case_id="case-002",
        target_name="perl_lsp_ux",
        full_test_name="ux::completion_exact"
    );
    plan +>:UnderPlan:+> case_fail;
    case_fail +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    case_fail +>:RecordedCheck(order=2):+>
        LoadBearingCheck(name="completion_items", passed=False);
    receipt_fail = UxCaseReceipt(case_id="case-002", caller_requested_pass=True);
    case_fail +>:ReceiptFor:+> receipt_fail;

    case_pass spawn ReceiptFinalizer();
    case_fail spawn ReceiptFinalizer();
}
```

