```jac
"""Mutual friendships in a small neighborhood.

Houses are modeled as nodes; buddy edges are bidirectional, created in
a single statement. Two greeter walkers are spawned, one at each of the
two houses, and each uses forward traversal only to reach the other,
proving the link really points both ways. A guard set prevents bouncing
back and forth forever.
"""

node House {
    has name: str = "";
    has available: bool = True;
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has greeting: str = "hello";
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can greet with House entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            print(f"{self.greeting} from {here.name}, visiting {self.visited}");
        }
        # Forward-only traversal; the visited list keeps us from bouncing
        # forever between two mutually-linked houses.
        next_houses = [h for h in [-->] if h.name not in self.visited];
        visit next_houses else {
            disengage;
        }
    }
}

with entry {
    # Two houses in the neighborhood.
    alice_house = House(name="Alice");
    bob_house = House(name="Bob");

    # Anchor them under root.
    root ++> alice_house ++> bob_house;

    # Bidirectional buddy edges in a single statement: Alice <-> Bob.
    alice_house +>:Buddy(since="childhood"):+> bob_house;
    bob_house +>:Buddy(since="childhood"):+> alice_house;

    # Spawn a greeter at Alice's house; it should reach Bob forward-only.
    alice_greeter = Greeter(greeting="Alice says hi");
    alice_house spawn alice_greeter;

    # Spawn a greeter at Bob's house; it should reach Alice forward-only.
    bob_greeter = Greeter(greeting="Bob says hi");
    bob_house spawn bob_greeter;
}
