```jac
"""Order auditor: demonstrates skip-and-continue vs. halt-and-disengage.

Orders carry an amount, a validity flag, and a fraud flag. Invalid orders
are skipped (the walk continues onward), but a flagged-fraud order halts
the entire audit on the spot. Each order prints which action fired.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker Auditor {
    can start with Root entry {
        print("Beginning order audit...");
        visit [-->];
    }

    can audit with Order entry {
        # Skip invalid orders but keep walking.
        if not here.valid {
            print(f"[SKIP]   {here.label}: invalid, continuing");
            visit [-->];
        }

        # Halt the whole walk on fraud.
        if here.fraud {
            print(f"[HALT]   {here.label}: fraud flagged, disengaging");
            disengage;
        }

        # Otherwise it's a clean audit.
        print(f"[AUDIT]  {here.label}: amount=${here.amount:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-001", amount=120.50, valid=True)
        ++> Order(label="ORD-002", amount=45.00, valid=False)
        ++> Order(label="ORD-003", amount=999.99, valid=True)
        ++> Order(label="ORD-004", amount=250.00, valid=True, fraud=True)
        ++> Order(label="ORD-005", amount=75.00, valid=True);

    root spawn Auditor();
}
```

