```jac
"""First Release Readiness audit walker.

Models the UAT / audit sign-off / Go-No-Go slice from issue #103.
Personas run their scenarios through Checkpoints; a ReleaseGate walker
audits every checkpoint for completeness, sign-offs, blockers, and
dependency readiness, then issues a single Go/No-Go decision.
"""

# ---------- Entity archetypes ----------

node Persona {
    has name: str = "";
    has role: str = "";
    has scenarios_signed: int = 0;
    has scenarios_total: int = 0;
}

node Checkpoint {
    has label: str = "";
    has kind: str = "";
    has status: str = "pending";   # pending | passed | failed | blocked
    has owner: str = "";
    has evidence_current: bool = False;
}

node SignOff {
    has reviewer: str = "";
    has scope: str = "";
    has severity: str = "";        # "" | P1 | P2 | P3
    has resolved: bool = False;
}

node ReleaseGate {
    has label: str = "";
    has blocked_by_id: int = 0;
    has authorizes_id: int = 0;
    has decision: str = "PENDING";
    has decision_owner: str = "";
    has p1_count: int = 0;
    has p2_count: int = 0;
}

# ---------- Relationships (typed edges) ----------

edge Owns {
    has weight: int = 1;
}

edge Reviews {
    has severity: str = "";
}

edge DependsOn {
    has link_id: int = 0;
}

edge Unblocks {
    has link_id: int = 0;
}

# ---------- Walker: audits release readiness ----------

walker ReadinessAuditor {
    has missing_evidence: list[str] = [];
    has blocked_names: list[str] = [];
    has unfinished_personas: list[str] = [];
    has p1_total: int = 0;
    has p2_total: int = 0;
    has current_gate: ReleaseGate | None = None;

    can start with Root entry {
        visit [-->];
    }

    # A persona node reports scenario completion.
    can check_persona with Persona entry {
        if here.scenarios_total == 0 {
            visit [-->];
            return;
        }
        if here.scenarios_signed < here.scenarios_total {
            label = here.name + " (" + here.role + ")";
            self.unfinished_personas.append(label);
        }
        visit [-->];
    }

    # Checkpoints collect evidence + ownership state.
    can check_checkpoint with Checkpoint entry {
        if not here.evidence_current {
            self.missing_evidence.append(here.label);
        }
        if here.status == "blocked" {
            self.blocked_names.append(here.label);
        }
        visit [-->];
    }

    # SignOffs tally unresolved P1/P2 defects.
    can tally_signoff with SignOff entry {
        if not here.resolved {
            if here.severity == "P1" {
                self.p1_total += 1;
            } elif here.severity == "P2" {
                self.p2_total += 1;
            }
        }
        visit [-->];
    }

    # At a ReleaseGate: aggregate counts and decide.
    can decide with ReleaseGate entry {
        self.current_gate = here;
        here.p1_count = self.p1_total;
        here.p2_count = self.p2_total;

        blocking = self.p1_total > 0 or self.p2_total > 0
                or len(self.blocked_names) > 0
                or len(self.missing_evidence) > 0
                or len(self.unfinished_personas) > 0;

        verdict = "NO-GO" if blocking else "GO";
        here.decision = verdict;
        here.decision_owner = "Release Manager";

        print(f"Gate '{here.label}' decision: {verdict}");
        if blocking {
            reasons = [];
            if self.p1_total > 0 { reasons.append(f"{self.p1_total} P1"); }
            if self.p2_total > 0 { reasons.append(f"{self.p2_total} P2"); }
            if len(self.blocked_names) > 0 {
                reasons.append(f"blocked: {', '.join(self.blocked_names)}");
            }
            if len(self.missing_evidence) > 0 {
                reasons.append(f"stale evidence: {', '.join(self.missing_evidence)}");
            }
            if len(self.unfinished_personas) > 0 {
                reasons.append(f"unfinished: {', '.join(self.unfinished_personas)}");
            }
            print("  reasons: " + " | ".join(reasons));
        } else {
            print("  all persona scenarios signed; evidence current; "
                  + "no unresolved P1/P2; blocked dependencies cleared.");
        }

        visit [-->];
    }
}

# ---------- Demo wiring ----------

with entry {
    # Personas
    pm      = Persona(name="Alice",   role="PM",      scenarios_signed=4, scenarios_total=4);
    qa      = Persona(name="Bob",     role="QA",      scenarios_signed=5, scenarios_total=5);
    ops     = Persona(name="Carol",   role="Ops",     scenarios_signed=2, scenarios_total=3);
    sec     = Persona(name="Dan",     role="Sec",     scenarios_signed=3, scenarios_total=3);

    # Checkpoints
    cp_uat  = Checkpoint(label="UAT",          kind="uat",     status="passed", owner="QA",  evidence_current=True);
    cp_sec  = Checkpoint(label="Security",     kind="audit",   status="passed", owner="Sec", evidence_current=True);
    cp_perf = Checkpoint(label="Performance",  kind="audit",   status="passed", owner="Ops", evidence_current=False);
    cp_mig  = Checkpoint(label="Migration",    kind="ops",     status="blocked", owner="Ops", evidence_current=True);

    # Sign-offs (one unresolved P1 → NO-GO)
    so_uat  = SignOff(reviewer="QA Lead", scope="UAT",  severity="",    resolved=True);
    so_sec  = SignOff(reviewer="Sec",     scope="Sec",  severity="P3",  resolved=False);
    so_perf = SignOff(reviewer="Perf",    scope="Perf", severity="P1",  resolved=False);

    # Release gate: blocked by #102, authorizes #115
    gate    = ReleaseGate(label="First Release Gate",
                          blocked_by_id=102,
                          authorizes_id=115);

    # Graph: root → personas → checkpoints → sign-offs → gate
    root ++> pm ++> qa ++> ops ++> sec;
    root ++> cp_uat ++> cp_sec ++> cp_perf ++> cp_mig;
    root ++> so_uat ++> so_sec ++> so_perf;

    # Gate hangs off root and is reached via typed Unblocks edge
    # representing that #115 is authorized only after this gate passes.
    root +>:DependsOn(link_id=102):+> gate;
    gate  +>:Unblocks(link_id=115):+> (next := ReleaseGate(label="Activation Slice", blocked_by_id=115));

    # Ownership / review relationships
    qa  +>:Owns(weight=2):+> cp_uat;
    sec +>:Owns(weight=1):+> cp_sec;
    ops +>:Owns(weight=1):+> cp_perf;
    ops +>:Owns(weight=1):+> cp_mig;
    qa  +>:Reviews(severity="OK"):+> so_uat;
    sec +>:Reviews(severity="P3"):+> so_sec;
    ops +>:Reviews(severity="P1"):+> so_perf;

    # Walk the readiness audit
    auditor = ReadinessAuditor();
    root spawn auditor;

    print(f"\nFinal state: gate.decision={gate.decision}, "
          + f"P1={auditor.p1_total}, P2={auditor.p2_total}, "
          + f"unfinished_personas={auditor.unfinished_personas}, "
          + f"stale_evidence={auditor.missing_evidence}, "
          + f"blocked={auditor.blocked_names}");
}
```

```jac
"""V9 benchmark gate: render the same latent state through multiple
independent renderers, detect cycle-shaped query programs, and cascade-
invalidate per-run ontology changes across dataset nodes.

Models the issue's two core pains as a graph: a ``LatentState`` has many
``RenderRecord`` children, an ``OntologyDef`` declares per-run types,
and a ``QueryProgram`` walker recursively descends programs to detect
cycles and emit per-program audit reports.
"""

node OntologyDef {
    has name: str = "";
    has entity_types: str = "user,device,session";
    has depth: int = 2;
}

node LatentState {
    has world_id: str = "";
    has description: str = "";
}

edge RenderedAs {
    has renderer: str = "";
}

node RenderRecord {
    has text: str = "";
    has renderer_kind: str = "";
    has is_critical: bool = False;
}

node QueryProgram {
    has operations: str = "join,time,aggregate";
    has depth: int = 1;
    has parent_op: str = "";
}

edge Decomposes {
    has label: str = "";
}

edge HasOntology {
    has version: str = "v9";
}

walker AuditSweep {
    has visited_programs: list[str] = [];
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can see_state with LatentState entry {
        print(f"[latent] {here.world_id}: {here.description}");
        visit [-->];
    }

    can see_ontology with OntologyDef entry {
        print(f"[ontology] {here.name} types={here.entity_types} depth={here.depth}");
        visit [-->];
    }

    can see_record with RenderRecord entry {
        marker = "CRIT" if here.is_critical else "info";
        print(f"  [{marker}] renderer={here.renderer_kind} text={here.text}");
        visit [-->];
    }

    can descend with QueryProgram entry {
        prog_id = f"{here.operations}@{here.depth}";
        if prog_id in self.visited_programs {
            self.cycle_detected = True;
            print(f"[cycle] revisits {prog_id}");
            disengage;
        }
        self.visited_programs.append(prog_id);
        print(f"[query] {prog_id} parent={here.parent_op}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    bench = LatentState(
        world_id="run-7",
        description="user-13 owns device-A; joined with session-42"
    );

    onto = OntologyDef(
        name="telecom-ontology",
        entity_types="user,device,session,plan",
        depth=3
    );

    conv = RenderRecord(text="hey i switched plans", renderer_kind="chat", is_critical=True);
    doc = RenderRecord(text="account ledger row 7", renderer_kind="ledger", is_critical=False);
    email = RenderRecord(text="from support: confirm device swap", renderer_kind="email", is_critical=True);

    bench +>:RenderedAs(renderer="chat"):+> conv;
    bench +>:RenderedAs(renderer="ledger"):+> doc;
    bench +>:RenderedAs(renderer="email"):+> email;
    bench +>:HasOntology(version="v9"):+> onto;

    q1 = QueryProgram(operations="join", depth=1, parent_op="root");
    q2 = QueryProgram(operations="time", depth=2, parent_op="join");
    q3 = QueryProgram(operations="aggregate", depth=3, parent_op="time");
    q4 = QueryProgram(operations="join", depth=4, parent_op="aggregate");

    q1 +>:Decomposes(label="then"):+> q2;
    q2 +>:Decomposes(label="then"):+> q3;
    q3 +>:Decomposes(label="then"):+> q4;

    root ++> bench;
    root ++> q1;

    root spawn AuditSweep();
}
