    max_c = sweep.readings[0];
    for t in sweep.readings {
        if t < min_c {
            min_c = t;
        }
        if t > max_c {
            max_c = t;
        }
    }

    print(f"Readings: {sweep.readings}");
    print(f"Min: {min_c}°C, Max: {max_c}°C");
}
