```jac
"""Recursive type dependency demo.

Models the TypeScript issue about a type alias that "circularly references
itself" through variadic/mapped-type inference.  We use it as a teaching
example for graph traversal in Jac: a ``TypeDef`` node can depend on other
``TypeDef`` nodes via ``DependsOn`` edges, and a walker explores the
dependency closure while enforcing a recursion guard so that real cycles
do not hang the runtime (Jac 0.36.1 walkers have no built-in once-per-node
visitation -- see OSP_IDIOMIZE_SOL_REVIEW §2).
"""

node TypeDef {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
}

edge DependsOn {
    has via: str = "";
}

walker DependencyInspector {
    has order: list[str] = [];
    has guard: set[str] = set();
    has max_depth: int = 8;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can inspect with TypeDef entry {
        if here.name in self.guard {
            self.cycle_found = True;
            print(f"[cycle] re-entry on {here.name}");
            disengage;
        }
        if here.depth > self.max_depth {
            print(f"[depth-cap] stopping at {here.name}");
            disengage;
        }
        self.guard.add(here.name);
        self.order.append(here.name);
        print(f"[enter] {here.kind} {here.name} (depth={here.depth})");
        visit [->:DependsOn:->];
    }
}

with entry {
    A = TypeDef(name="A", kind="alias", depth=0);
    B = TypeDef(name="B", kind="alias", depth=1);
    C = TypeDef(name="C", kind="alias", depth=2);
    D = TypeDef(name="D", kind="alias", depth=3);

    root +>:DependsOn(via="Row"):+> A;
    A +>:DependsOn(via="Rows"):+> B;
    B +>:DependsOn(via="Component"):+> C;
    C +>:DependsOn(via="AArgument"):+> D;
    D +>:DependsOn(via="ARow"):+> A;

    inspector = DependencyInspector();
    root spawn inspector;

    print("");
    print(f"order      = {inspector.order}");
    print(f"guard      = {sorted(inspector.guard)}");
    print(f"cycle_found = {inspector.cycle_found}");
}
```

```jac
"""Jolt aspect-pack gate audit: fork-fixed issues require portable regressions or extraction debt."""

node CorrectnessPack {
    has pack_name: str = "";
    has baseline_fork_fixed: int = 0;
}

node FailureClass {
    has name: str = "";
    has rank: int = 0;
    has leverage: str = "";
}

node Issue {
    has issue_id: int = 0;
    has title: str = "";
    has status: str = "open";
}

node PortableRegression {
    has script: str = "";
    has bad_sha: str = "";
    has fixed_sha: str = "";
}

node ExtractionDebt {
    has reason: str = "";
    has issue_tag: str = "";
}

node PhaseStep {
    has phase: str = "";
    has label: str = "";
    has observation_valid: bool = True;
}

edge PackTracks { }

edge Classifies { }

edge CoveredBy { }

edge OwedDebt { }

edge NextPhase { }

walker GateAuditor {
    has current_issue: int = 0;
    has regressions_found: int = 0;
    has debt_found: int = 0;
    has gaps: int = 0;

    can start with Root entry {
        print("=== Gate non-vacuity audit (fork-fixed issues) ===");
        visit [-->];
    }

    can audit_pack with CorrectnessPack entry {
        print(f"Pack: {here.pack_name} (baseline fork-fixed={here.baseline_fork_fixed})");
        visit [->:PackTracks:->] else { disengage; };
    }

    can audit_class with FailureClass entry {
        priority = "PRIORITY" if here.rank == 0 else "ranked";
        print(f"  [{priority}] class #{here.rank}: {here.name} ({here.leverage})");
        visit [->:Classifies:->] else { disengage; };
    }

    can audit_issue with Issue entry {
        if here.status != "fork-fixed" {
            disengage;
        }
        self.current_issue = here.issue_id;
        print(f"    Issue #{here.issue_id}: {here.title}");
        visit [->:CoveredBy:->] else {
            visit [->:OwedDebt:->] else {
                print("      [VIOLATION] no portable regression or extraction debt row");
                self.gaps += 1;
            };
        };
    }

    can confirm_regression with PortableRegression entry {
        print(f"      [OK] script={here.script} shas={here.bad_sha}..{here.fixed_sha}");
        self.regressions_found += 1;
        disengage;
    }

    can confirm_debt with ExtractionDebt entry {
        print(f"      [DEBT] {here.issue_tag}: {here.reason}");
        self.debt_found += 1;
        disengage;
    }
}

walker PhaseAuditor {
    has observation: str = "";
    has reserve_seen: bool = False;
    has lost_update: bool = False;

    can start with Root entry {
        print("=== Phase join audit (reserve / register / commit) ===");
        visit [-->];
    }

    can walk_phase with PhaseStep entry {
        if here.phase == "reserve" {
            self.observation = here.label;
            self.reserve_seen = True;
            print(f"  [reserve] observed pending={here.label}");
        } elif here.phase == "commit" {
            if not self.reserve_seen {
                self.lost_update = True;
                print("  [commit] LOST UPDATE: commit without prior reserve");
            } elif not here.observation_valid {
                self.lost_update = True;
                print(f"  [commit] LOST UPDATE: stale observation '{self.observation}'");
            } else {
                print(f"  [commit] published pending={self.observation}");
            }
        } else {
            print(f"  [{here.phase}] staged {here.label}");
        }
        visit [->:NextPhase:->] else { disengage; };
    }
}

with entry {
    pack = CorrectnessPack(pack_name="jolt-aspect-packs/main", baseline_fork_fixed=20);
    gate_class = FailureClass(
        name="gate-non-vacuity",
        rank=0,
        leverage="high/low-medium"
    );
    split_class = FailureClass(
        name="split-reserve-register-commit",
        rank=1,
        leverage="very-high/medium"
    );

    issue53 = Issue(
        issue_id=53,
        title="meta: recurring failure classes into correctness packs",
        status="fork-fixed"
    );
    issue47 = Issue(
        issue_id=47,
        title="poller pending-registration lost update",
        status="fork-fixed"
    );
    issue99 = Issue(
        issue_id=99,
        title="socket EOF errno read after yield",
        status="fork-fixed"
    );
    issue8 = Issue(
        issue_id=8,
        title="vacuous gate suppresses failing subcommand",
        status="fork-fixed"
    );

    poller_reg = PortableRegression(
        script="test/regressions/poller_atomic.jac",
        bad_sha="99e19320",
        fixed_sha="6f562e55"
    );
    errno_debt = ExtractionDebt(
        reason="portable matrix row not yet extracted",
        issue_tag="#99"
    );
    meta_debt = ExtractionDebt(
        reason="meta-issue portable extraction in flight",
        issue_tag="#53"
    );

    poll_reserve = PhaseStep(phase="reserve", label="fd-7");
    poll_register = PhaseStep(phase="register", label="fd-7");
    poll_commit = PhaseStep(
        phase="commit",
        label="fd-7",
        observation_valid=False
    );

    root ++> pack;
    pack +>:PackTracks:+> gate_class;
    pack +>:PackTracks:+> split_class;

    gate_class +>:Classifies:+> issue53;
    gate_class +>:Classifies:+> issue8;
    split_class +>:Classifies:+> issue47;
    split_class +>:Classifies:+> issue99;

    issue47 +>:CoveredBy:+> poller_reg;
    issue99 +>:OwedDebt:+> errno_debt;
    issue53 +>:OwedDebt:+> meta_debt;

    poll_reserve +>:NextPhase:+> poll_register;
    poll_register +>:NextPhase:+> poll_commit;
    root ++> poll_reserve;

    gate_auditor = GateAuditor();
    phase_auditor = PhaseAuditor();
    root spawn gate_auditor;
    root spawn phase_auditor;

    print(
        f"Gate summary: {gate_auditor.regressions_found} regressions, "
        f"{gate_auditor.debt_found} debt rows, {gate_auditor.gaps} vacuous gaps"
    );
    verdict = "FAIL" if gate_auditor.gaps > 0 else "PASS";
    print(f"Gate verdict: {verdict}");
    phase_verdict = "FAIL" if phase_auditor.lost_update else "PASS";
    print(f"Phase verdict: {phase_verdict}");
}
```

