```jac
"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordDef {
    has name: str = "";
}

edge NestedField { }
edge DependsOn { }

walker FieldChainResolve {
    has depth: int = 0;
    has leaf_a: int = 0;
    has ok: bool = False;

    can resolve with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else { disengage; };
    }

    can at_inner with Inner entry {
        self.depth = 2;
        self.leaf_a = here.a;
        self.ok = True;
        print(f"field chain: o.inner.a={self.leaf_a} depth={self.depth}");
        disengage;
    }
}

walker V1LetBind {
    has copied_a: int = 0;
    has ok: bool = False;

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can whole_read with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        print(f"v1: let d : Inner = o.inner -> d.a={self.copied_a} PASSED");
        disengage;
    }
}

walker TbirLetBind {
    has ok: bool = False;
    has reason: str = "";

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can reject_bind with Inner entry {
        self.ok = False;
        self.reason = "TB-IR rejects let d : Inner = o.inner";
        print(f"tbir: let d : Inner = o.inner -> REJECTED ({self.reason})");
        disengage;
    }
}

walker FieldCopyRead {
    has captured_a: int = 0;

    can from_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can take with Inner entry {
        self.captured_a = here.a;
        print(f"field read: o.inner.a={self.captured_a}");
        disengage;
    }
}

walker FieldCopyWrite {
    has source_a: int = 0;
    has done: bool = False;

    can into_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can paste with Inner entry {
        here.a = self.source_a;
        self.done = True;
        print(f"field write: p.inner = o.inner -> p.inner.a={here.a}");
        disengage;
    }
}

walker EmitOrder {
    has ordered: bool = False;

    can walk with RecordDef entry {
        if here.name == "Outer" {
            visit [->:DependsOn:->] else { disengage; };
        } elif here.name == "Inner" {
            self.ordered = True;
            print(f"emit order: Inner before Outer -> ordered={self.ordered}");
            disengage;
        } else {
            disengage;
        }
    }
}

with entry {
    inner_def = RecordDef(name="Inner");
    outer_def = RecordDef(name="Outer");
    root ++> inner_def;
    root ++> outer_def;
    outer_def +>:DependsOn:+> inner_def;

    src_inner = Inner(a=5);
    o = Outer(r=7);
    root ++> o;
    o +>:NestedField:+> src_inner;

    dst_inner = Inner(a=0);
    p = Outer(r=0);
    root ++> p;
    p +>:NestedField:+> dst_inner;

    chain = FieldChainResolve();
    o spawn chain;

    v1 = V1LetBind();
    o spawn v1;

    tbir = TbirLetBind();
    o spawn tbir;

    reader = FieldCopyRead();
    o spawn reader;
    writer = FieldCopyWrite(source_a=reader.captured_a);
    p spawn writer;

    emit = EmitOrder();
    outer_def spawn emit;

    parity_gap = v1.ok and not tbir.ok;
    print(f"parity gap v1 ok={v1.ok} tbir ok={tbir.ok} gap={parity_gap}");
    print(f"field-copy path works dst_a={dst_inner.a} writer done={writer.done}");
}
```

```jac
"""Task dependency graph with memoization-style short-circuit traversal.

Models the pyinvoke/invoke #461 "advanced task dependencies / caching" use case:
a tree of tasks (some heavy, some cheap) connected by typed `Requires` edges.
A walker descends the dependency graph, but each task remembers whether its
result has already been "produced" — re-entering an already-completed task
short-circuits instead of re-running its body. This is the make-like behavior
the issue asks for: tasks declare what they need, run only as many times as
required, and skip work that has already been done.
"""

node Task {
    has title: str = "";
    has heavy: bool = False;
    has done: bool = False;
    has runs: int = 0;
}

edge Requires {
    has via: str = "pre";
}

walker Executor {
    can start with Root entry {
        visit [->:Requires:->];
    }

    can run_task with Task entry {
        if here.done {
            print(f"  [skip ] {here.title} (already done, runs={here.runs})");
            visit [->:Requires:->];
            return;
        }
        if here.heavy {
            print(f"  [heavy] {here.title} -- doing real work");
            here.runs = here.runs + 1;
        } else {
            print(f"  [light] {here.title} -- quick step");
            here.runs = here.runs + 1;
        }
        here.done = True;
        visit [->:Requires:->];
    }
}

with entry {
    # Build a small dependency tree. `deploy` requires `build_artifact`
    # requires `compile` and `fetch_secrets`. `compile` itself requires
    # `fetch_secrets` (shared subtree).
    fetch_secrets = Task(title="fetch_secrets", heavy=True);
    compile_t = Task(title="compile", heavy=True);
    build_artifact = Task(title="build_artifact", heavy=True);
    provision_db = Task(title="provision_db", heavy=True);
    deploy = Task(title="deploy", heavy=True);

    root +>:Requires(via="pre"):+> deploy;
    deploy +>:Requires:+> build_artifact;
    deploy +>:Requires:+> provision_db;
    build_artifact +>:Requires:+> compile_t;
    build_artifact +>:Requires:+> fetch_secrets;
    compile_t +>:Requires:+> fetch_secrets;
    provision_db +>:Requires:+> fetch_secrets;

    print("=== first execution pass ===");
    Executor() spawn deploy;

    print("=== second execution pass (everything should be skipped) ===");
    Executor() spawn deploy;

    print(f"final runs: "
          f"fetch_secrets={fetch_secrets.runs}, "
          f"compile={compile_t.runs}, "
          f"build_artifact={build_artifact.runs}, "
          f"provision_db={provision_db.runs}, "
          f"deploy={deploy.runs}");
}
```

```jac
"""Recursive CTE-style subquery: model a tree where the recursive CTE
result feeds into a downstream query, exactly the scenario from issue
#1237. A walker descends the tree collecting IDs (the CTE), then another
walker uses that collected set as a subquery filter against a separate
collection of Foo nodes (the consumer query).
"""

node TreeNode {
    has id: int = 0;
    has name: str = "";
}

node Foo {
    has id: int = 0;
    has label: str = "";
}

edge ParentOf { }

walker CollectSubtree {
    has collected_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with TreeNode entry {
        self.collected_ids.append(here.id);
        visit [->:ParentOf:->];
    }
}

walker QueryWithSubquery {
    has allowed_ids: list[int] = [];
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can filter with Foo entry {
        if here.id in self.allowed_ids {
            self.matches.append(here.label);
        }
        visit [-->];
    }
}

with entry {
    # Build the tree (the source the recursive CTE walks).
    r = TreeNode(id=0, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    d = TreeNode(id=4, name="d");
    r +>:ParentOf:+> a;
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> d;
    root ++> r;

    # Step 1: recursive CTE walk to gather ids.
    cte = CollectSubtree();
    r spawn cte;
    print(f"CTE collected ids: {cte.collected_ids}");

    # Step 2: consumer query filtered by the subquery result.
    f1 = Foo(id=1, label="foo-A");
    f2 = Foo(id=2, label="foo-B");
    f3 = Foo(id=3, label="foo-C");
    f4 = Foo(id=5, label="foo-E");
    f5 = Foo(id=99, label="foo-OTHER");
    root ++> f1 ++> f2 ++> f3 ++> f4 ++> f5;

    consumer = QueryWithSubquery(allowed_ids=cte.collected_ids);
    root spawn consumer;
    print(f"Subquery-filtered foos: {consumer.matches}");
}
```

