"""Rental shop shelf audit.

Books and DVDs each have a typed ability that fires for their kind.
Anything else (e.g. an unclassified archive reel) falls through to a
default union ability and is counted separately.
"""

# Base node so a single union ability can touch the common payload.
node Media {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def media_title() -> str {
        return self.title;
    }

    def media_year() -> int {
        return self.year;
    }
}

node Book(Media) {
    has author: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

node DVD(Media) {
    has runtime: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

node ArchiveReel(Media) {
    has label: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can shelf_book with Book entry {
        self.total += 1;
        print(f"Book: '{here.title}' by {here.author} ({here.year})");
        visit [-->];
    }

    can shelf_dvd with DVD entry {
        self.total += 1;
        print(f"DVD: '{here.title}', {here.runtime} min ({here.year})");
        visit [-->];
    }

    # Default path: anything not matched as Book or DVD lands here.
    can shelve_other with ArchiveReel entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"[default] '{here.title}' ({here.year}) — unclassified");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="The Hobbit", author="Tolkien", year=1937, available=False)
        ++> Book(title="Dune", author="Herbert", year=1965)
        ++> DVD(title="Blade Runner", runtime=117, year=1982, available=False)
        ++> DVD(title="Spirited Away", runtime=125, year=2001)
        ++> ArchiveReel(label="Reel-7", title="Unknown Reel", year=1972);
    auditor = Auditor();
    root spawn auditor;
    print(f"Total items audited: {auditor.total}");
    print(f"Items via default path: {auditor.defaulted}");
}
