```jac
"""Order auditor: skip invalid orders but halt on fraud-flagged ones.

Orders carry an amount, a validity flag, and a fraud flag. The auditor
walker visits each order in sequence: invalid orders are skipped (the
walk continues), but a fraud-flagged order halts the entire walk
immediately. Every visited order prints which action fired.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flagged: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted: int = 0;

    can start with Root entry {
        print("OrderAuditor beginning walk...");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        self.audited += 1;
        action = "";
        if here.fraud_flagged {
            action = "HALT";
        } elif not here.valid {
            action = "SKIP";
        } else {
            action = "OK";
        }
        print(f"Order ${here.amount:.2f} -> {action}");
        if here.fraud_flagged {
            self.halted += 1;
            print("Fraud detected: halting walk immediately.");
            disengage;
        }
        if not here.valid {
            self.skipped += 1;
            visit [-->] else { disengage; };
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Order(amount=120.50, valid=True)
        ++> Order(amount=45.00, valid=False)
        ++> Order(amount=300.00, valid=True, fraud_flagged=True)
        ++> Order(amount=75.25, valid=True)
        ++> Order(amount=999.99, valid=False);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"audited={auditor.audited} skipped={auditor.skipped} "
          f"halted={auditor.halted}");
}
