```jac
"""Resource limits: reject pathological dependency closure, provenance cycles, and archive abuse before execution."""

node SemanticModel {
    has name: str = "";
    has assertion_count: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveBundle {
    has label: str = "";
    has max_entries: int = 100;
    has max_entry_bytes: int = 1048576;
    has max_total_bytes: int = 10485760;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveEntry {
    has entry_path: str = "";
    has byte_size: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }
edge ContainsEntry { has ordinal: int = 0; }
edge ProvenanceLink { has step: int = 0; }
edge Stop { }

walker DependencyAuditor {
    has target: str = "";
    has engaged: bool = False;
    has max_depth: int = 4;
    has max_closure: int = 8;
    has depth: int = 0;
    has _seen: list[str] = [];
    has count: int = 0;
    has rejected: bool = False;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with SemanticModel entry {
        if not self.engaged {
            if self.target != "" and here.name != self.target {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
        }
        if self.rejected {
            disengage;
        }
        if here.name in self._seen {
            self.rejected = True;
            self.reason = f"dependency cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self._seen.append(here.name);
        self.count += 1;
        if self.count > self.max_closure {
            self.rejected = True;
            self.reason = f"closure exceeds {self.max_closure} models";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"dependency depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        print(f"  ok model {here.name} depth={self.depth} assertions={here.assertion_count}");
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:DependsOn:->] else {
            if not self.rejected {
                print(f"ACCEPT: dependency closure {self.count} models within depth {self.max_depth}");
            }
        };
        parent_depth = self.depth - 1;
        self.depth = parent_depth;
        visit [->:Stop:->] else { };
    }
}

walker ProvenanceAuditor {
    has target: str = "";
    has engaged: bool = False;
    has max_depth: int = 5;
    has depth: int = 0;
    has _seen: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can trace with SemanticModel entry {
        if not self.engaged {
            if self.target != "" and here.name != self.target {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
        }
        if self.rejected {
            disengage;
        }
        if here.name in self._seen {
            self.rejected = True;
            self.reason = f"provenance cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"provenance depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self._seen.append(here.name);
        print(f"  ok provenance step={self.depth} artifact={here.name}");
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:ProvenanceLink:->] else {
            if not self.rejected {
                print(f"ACCEPT: provenance chain depth {self.depth} within limit {self.max_depth}");
            }
        };
        parent_depth = self.depth - 1;
        self.depth = parent_depth;
        visit [->:Stop:->] else { };
    }
}

walker ArchiveVerifier {
    has target_label: str = "";
    has engaged: bool = False;
    has max_entries: int = 5;
    has max_entry_bytes: int = 1000;
    has max_total_bytes: int = 5000;
    has entries_seen: int = 0;
    has bytes_total: int = 0;
    has normalized_paths: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";
    has bundle_label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect with ArchiveBundle entry {
        if not self.engaged {
            if self.target_label != "" and here.label != self.target_label {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
            self.bundle_label = here.label;
            self.max_entries = here.max_entries;
            self.max_entry_bytes = here.max_entry_bytes;
            self.max_total_bytes = here.max_total_bytes;
            print(f"=== archive audit: {self.bundle_label} ===");
        }
        visit [->:ContainsEntry:->] else {
            if not self.rejected {
                print(f"ACCEPT: archive {self.bundle_label} ({self.entries_seen} entries, {self.bytes_total} bytes)");
            }
        };
        visit [->:Stop:->] else { };
    }

    can scan with ArchiveEntry entry {
        if self.rejected {
            disengage;
        }
        path = here.entry_path;
        if path.startswith("/") {
            self.rejected = True;
            self.reason = "absolute archive path rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        if "../" in path or path == ".." {
            self.rejected = True;
            self.reason = "path traversal rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        norm = path.lower();
        if norm in self.normalized_paths {
            self.rejected = True;
            self.reason = f"duplicate normalized path ({norm})";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if here.byte_size > self.max_entry_bytes {
            self.rejected = True;
            self.reason = f"entry exceeds {self.max_entry_bytes} bytes";
            print(f"REJECT: {self.reason} ({here.byte_size})");
            disengage;
        }
        next_count = self.entries_seen + 1;
        if next_count > self.max_entries {
            self.rejected = True;
            self.reason = f"entry count exceeds {self.max_entries}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        next_total = self.bytes_total + here.byte_size;
        if next_total > self.max_total_bytes {
            self.rejected = True;
            self.reason = f"total uncompressed exceeds {self.max_total_bytes}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self.normalized_paths.append(norm);
        self.entries_seen = next_count;
        self.bytes_total = next_total;
        print(f"  ok entry {path} ({here.byte_size} bytes)");
        visit [->:Stop:->] else { };
    }
}

with entry {
    core = SemanticModel(name="core", assertion_count=12, title="Core", year=2026);
    util = SemanticModel(name="util", assertion_count=8, title="Util", year=2026);
    schema = SemanticModel(name="schema", assertion_count=20, title="Schema", year=2026);
    deep1 = SemanticModel(name="deep1", title="Deep1", year=2026);
    deep2 = SemanticModel(name="deep2", title="Deep2", year=2026);
    deep3 = SemanticModel(name="deep3", title="Deep3", year=2026);
    deep4 = SemanticModel(name="deep4", title="Deep4", year=2026);
    deep5 = SemanticModel(name="deep5", title="Deep5", year=2026);
    core +>:DependsOn:+> util;
    core +>:DependsOn:+> schema;
    util +>:DependsOn:+> deep1;
    deep1 +>:DependsOn:+> deep2;
    deep2 +>:DependsOn:+> deep3;
    deep3 +>:DependsOn:+> deep4;
    deep4 +>:DependsOn:+> deep5;
    root ++> core;

    cycle_a = SemanticModel(name="cycle_a", title="CycleA", year=2026);
    cycle_b = SemanticModel(name="cycle_b", title="CycleB", year=2026);
    cycle_a +>:DependsOn:+> cycle_b;
    cycle_b +>:DependsOn:+> cycle_a;
    root ++> cycle_a;

    prov_v3 = SemanticModel(name="artifact_v3", title="ArtifactV3", year=2026);
    prov_v2 = SemanticModel(name="artifact_v2", title="ArtifactV2", year=2025);
    prov_v1 = SemanticModel(name="artifact_v1", title="ArtifactV1", year=2024);
    prov_v3 +>:ProvenanceLink(step=1):+> prov_v2;
    prov_v2 +>:ProvenanceLink(step=2):+> prov_v1;
    root ++> prov_v3;

    hostile = ArchiveBundle(
        label="hostile_pkg",
        max_entries=3,
        max_entry_bytes=500,
        max_total_bytes=800,
        title="Hostile",
        year=2026
    );
    hostile +>:ContainsEntry(ordinal=1):+> ArchiveEntry(
        entry_path="manifest.json",
        byte_size=120,
        title="Manifest",
        year=2026
    );
    hostile +>:ContainsEntry(ordinal=2):+> ArchiveEntry(
        entry_path="models/core.jac",
        byte_size=240,
        title="CoreJac",
        year=2026
    );
    hostile +>:ContainsEntry(ordinal=3):+> ArchiveEntry(
        entry_path="../etc/passwd",
        byte_size=10,
        title="Traversal",
        year=2026
    );
    root ++> hostile;

    zip_bomb = ArchiveBundle(
        label="zip_bomb",
        max_entries=2,
        max_entry_bytes=100,
        max_total_bytes=150,
        title="ZipBomb",
        year=2026
    );
    zip_bomb +>:ContainsEntry(ordinal=1):+> ArchiveEntry(
        entry_path="payload.bin",
        byte_size=200,
        title="Payload",
        year=2026
    );
    root ++> zip_bomb;

    clean = ArchiveBundle(
        label="clean_pkg",
        max_entries=5,
        max_entry_bytes=1000,
        max_total_bytes=5000,
        title="Clean",
        year=2026
    );
    clean +>:ContainsEntry(ordinal=1):+> ArchiveEntry(
        entry_path="readme.txt",
        byte_size=64,
        title="Readme",
        year=2026
    );
    clean +>:ContainsEntry(ordinal=2):+> ArchiveEntry(
        entry_path="data/table.csv",
        byte_size=128,
        title="Table",
        year=2026
    );
    root ++> clean;

    print("--- dependency depth limit ---");
    root spawn DependencyAuditor(target="core", max_depth=3, max_closure=10);

    print("--- dependency cycle detection ---");
    root spawn DependencyAuditor(target="cycle_a", max_depth=10, max_closure=10);

    print("--- provenance chain (cycle-safe) ---");
    root spawn ProvenanceAuditor(target="artifact_v3", max_depth=5);

    print("--- archive path traversal ---");
    root spawn ArchiveVerifier(target_label="hostile_pkg");

    print("--- archive zip-bomb bounds ---");
    root spawn ArchiveVerifier(target_label="zip_bomb");

    print("--- archive within profile ---");
    root spawn ArchiveVerifier(target_label="clean_pkg");
}
