```jac
"""Observability graph: model metrics and trace callbacks as nodes, walked by an auditor.

This demo mirrors the GAP-20 scenario from tikv-php: a `MetricsInterface`-style
recorder holds six hooks (rpc, retry, cache hits/misses, region invalidation),
plus newer dimensions (backoff, per-store outcome, lock resolution, 2PC
phases). A tracing callback interface lets adopters bridge to OpenTelemetry
themselves. The `ObservabilityAuditor` walker traverses the graph and reports
which signals are wired and which hooks are still no-ops — i.e. the same
"every adopter writes the same adapter" gap the issue describes.
"""

# Shared base so a union ability can touch a common field without referencing
# attributes that some variants in the union don't have.
node Signal {
    has label: str = "";
    has category: str = "";
    has wired: bool = False;
}

node Metric(Signal) {
    has name: str = "";
    has kind: str = "counter";
    has observed: float = 0.0;
}

node RpcHook(Signal) { }

node RetryHook(Signal) { }

node CacheHook(Signal) {
    has hit: bool = False;
}

node RegionInvalidationHook(Signal) { }

node TraceCallback(Signal) {
    has span_name: str = "";
}

node Recorder {
    has name: str = "";
}

# Typed edges: the relationship carries meaning between recorder and its hooks.
edge Hooked {
    has since: str = "";
}

walker ObservabilityAuditor {
    has missing: list[str] = [];

    can start with Root entry {
        print("Observability audit starting");
        visit [-->];
    }

    can audit with Recorder entry {
        print(f"Recorder: {here.name}");
        visit [->:Hooked:->] else { disengage; }
    }

    can inspect with Metric | RpcHook | RetryHook | CacheHook | RegionInvalidationHook | TraceCallback entry {
        status = "WIRED" if here.wired else "GAP";
        suffix = f" [{here.category}]" if here.category != "" else "";
        print(f"  [{status}] {here.label}{suffix} (wired={here.wired})");
        if not here.wired {
            self.missing.append(here.label);
        }
    }
}

with entry {
    default_rec = Recorder(name="NoOpMetrics");

    # The six original MetricsInterface hooks: some wired, some not (the gap).
    default_rec +>:Hooked(since="v1"):+> RpcHook(label="rpcStarted", wired=True);
    default_rec +>:Hooked(since="v1"):+> RpcHook(label="rpcCompleted", wired=True);
    default_rec +>:Hooked(since="v1"):+> RetryHook(label="retryAttempted", wired=True);
    default_rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheHit", wired=False);
    default_rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheMiss", wired=False);
    default_rec +>:Hooked(since="v1"):+> RegionInvalidationHook(label="regionInvalidated", wired=False);

    # Newer dimensions called for by the issue: backoff, per-store, lock, 2PC.
    default_rec +>:Hooked(since="v2"):+> Metric(label="backoff_duration", name="backoff_duration", kind="histogram", wired=False);
    default_rec +>:Hooked(since="v2"):+> Metric(label="per_store_outcome", name="per_store_outcome", kind="counter", wired=False);
    default_rec +>:Hooked(since="v2"):+> Metric(label="lock_resolution_count", name="lock_resolution_count", kind="counter", wired=False);
    default_rec +>:Hooked(since="v2"):+> Metric(label="2pc_prewrite_ms", name="2pc_prewrite_ms", kind="histogram", wired=False);
    default_rec +>:Hooked(since="v2"):+> Metric(label="2pc_commit_ms", name="2pc_commit_ms", kind="histogram", wired=False);

    # Tracing callback interface — the bridge to OpenTelemetry.
    default_rec +>:Hooked(since="v2"):+> TraceCallback(label="txn_2pc", span_name="txn_2pc", category="CategoryTxn2PC", wired=False);
    default_rec +>:Hooked(since="v2"):+> TraceCallback(label="kv_request", span_name="kv_request", category="CategoryKVRequest", wired=True);

    root ++> default_rec;

    auditor = ObservabilityAuditor();
    root spawn auditor;

    print(f"Audit complete. {len(auditor.missing)} hooks still missing: {auditor.missing}");
}
```

