```jac
"""Order auditor: demonstrate skip-continue vs halt-disengage side by side.

Each Order node carries an amount, a validity flag, and a fraud flag.
The OrderAuditor walker visits orders via typed `Next` edges. Invalid
orders are skipped (the audit continues forward); flagged-fraud orders
halt the entire walk immediately.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

edge Next {
    has seq: int = 0;
}

walker OrderAuditor {
    has audited: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("OrderAuditor: beginning walk");
        visit [-->];
    }

    can audit with Order entry {
        self.audited += 1;

        # Fraud flag -> HALT the whole walk on the spot.
        if here.fraud {
            self.halted = True;
            print(f"[HALT]   {here.label} (amount={here.amount}) flagged as fraud -> disengaging");
            disengage;
        }

        # Invalid order -> SKIP this one, keep walking forward.
        if not here.valid {
            print(f"[SKIP]   {here.label} (amount={here.amount}) invalid -> continuing");
            visit [-->];
            return;
        }

        # Normal order -> record it and move on.
        print(f"[AUDIT]  {here.label} (amount={here.amount}) ok");
        visit [-->];
    }
}

with entry {
    # Build a chain of orders connected by typed `Next` edges.
    a = Order(label="ORD-001", amount=120.50, valid=True);
    b = Order(label="ORD-002", amount=80.00, valid=False);
    c = Order(label="ORD-003", amount=250.75, valid=True);
    d = Order(label="ORD-004", amount=999.99, valid=True);
    e = Order(label="ORD-005", amount=45.00, fraud=True);

    root +>:Next(seq=1):+> a
         +>:Next(seq=2):+> b
         +>:Next(seq=3):+> c
         +>:Next(seq=4):+> d
         +>:Next(seq=5):+> e;

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"");
    print(f"audited={auditor.audited} halted={auditor.halted}");
}
