```jac
"""Data center clearance enforcement.

Each ServerRoom node declares the clearance level it requires.
Technician walkers carry their own clearance level and are granted or
denied per room. A denial disengages the walker immediately so deeper
rooms are never visited. The walker's report counts how many rooms
each technician successfully reached.
"""

node ServerRoom {
    has name: str = "";
    has required_level: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_visited: int = 0;
    has denied_room: str = "";

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) begins walkthrough");
        visit [-->] else { disengage; }
    }

    can enter with ServerRoom entry {
        if self.clearance >= here.required_level {
            self.rooms_visited += 1;
            print(f"  GRANTED: {self.name} entered {here.name} (requires {here.required_level})");
        } else {
            self.denied_room = here.name;
            print(f"  DENIED: {self.name} blocked at {here.name} (requires {here.required_level})");
            disengage;
        }
    }

    can leave with ServerRoom exit {
        visit [-->] else { disengage; }
    }
}

with entry {
    # Build a corridor of rooms with increasing clearance requirements.
    root ++> ServerRoom(name="Lobby", required_level=1)
        ++> ServerRoom(name="Storage", required_level=2)
        ++> ServerRoom(name="Ops Floor", required_level=3)
        ++> ServerRoom(name="Crypto Vault", required_level=5)
        ++> ServerRoom(name="Quantum Lab", required_level=7);

    # Junior tech: cleared for the first two rooms, stopped at Ops Floor.
    junior = Technician(name="Alice", clearance=2);
    root spawn junior;

    # Senior tech: clears every room in the corridor.
    senior = Technician(name="Bob", clearance=10);
    root spawn senior;

    # Contractor: denied at the very first door.
    contractor = Technician(name="Eve", clearance=0);
    root spawn contractor;

    print(f"\n--- Walkthrough Summary ---");
    print(f"Alice reached {junior.rooms_visited} rooms, denied at {junior.denied_room}");
    print(f"Bob reached {senior.rooms_visited} rooms, denied at {senior.denied_room}");
    print(f"Eve reached {contractor.rooms_visited} rooms, denied at {contractor.denied_room}");
}
