```jac
"""Online store checkout: dispatch on product kind and print an itemized receipt."""

# --- Product archetypes -----------------------------------------------------

node Product {
    has name: str = "";
    has price: float = 0.0;

    # Subclasses override these two hooks to express their own rules.
    def shipping_cost() -> float {
        return 0.0;
    }
    def handling_label() -> str {
        return "standard";
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;
    override def shipping_cost() -> float {
        return 2.0 + 0.5 * self.weight_lb;
    }
    override def handling_label() -> str {
        return "boxed & shipped";
    }
}

node DigitalBook(Product) {
    override def shipping_cost() -> float {
        return 0.0;
    }
    override def handling_label() -> str {
        return "instant download";
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;
    override def shipping_cost() -> float {
        return 8.0;
    }
    override def handling_label() -> str {
        return f"insured, {self.warranty_months}-mo warranty";
    }
}

node Clothing(Product) {
    has size: str = "M";
    override def shipping_cost() -> float {
        return 4.0;
    }
    override def handling_label() -> str {
        return f"apparel, size {self.size}";
    }
}

# --- Walker: walks the cart, itemizes, then tallies -------------------------

walker Checkout {
    has lines: list = [];
    has subtotal: float = 0.0;
    has shipping: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    # One union ability handles every concrete product kind. Each branch
    # calls the override hooks on the current node, so the rules live on
    # the archetype, not in the walker.
    can ring with PaperBook | DigitalBook | Electronics | Clothing entry {
        line_total = here.price + here.shipping_cost();
        self.lines.append(
            f"  {here.name:<22} ${here.price:>6.2f}  "
            f"({here.handling_label()})  +ship ${here.shipping_cost():>4.2f}  "
            f"= ${line_total:>6.2f}"
        );
        self.subtotal += here.price;
        self.shipping += here.shipping_cost();
        visit [-->];
    }
}

# --- Demo -------------------------------------------------------------------

with entry {
    cart = [
        PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4),
        DigitalBook(name="Refactoring, 2e (ePub)", price=24.00),
        Electronics(name="USB-C Hub", price=59.99, warranty_months=24),
        Clothing(name="Hoodie", price=45.00, size="L"),
        Electronics(name="Wireless Mouse", price=34.50, warranty_months=12),
    ];

    root ++> PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4)
        ++> DigitalBook(name="Refactoring, 2e (ePub)", price=24.00)
        ++> Electronics(name="USB-C Hub", price=59.99, warranty_months=24)
        ++> Clothing(name="Hoodie", price=45.00, size="L")
        ++> Electronics(name="Wireless Mouse", price=34.50, warranty_months=12);

    cashier = Checkout();
    root spawn cashier;

    total = cashier.subtotal + cashier.shipping;

    print("--- RECEIPT ---");
    for line in cashier.lines {
        print(line);
    }
    print("--- TOTALS ---");
    print(f"  Subtotal: ${cashier.subtotal:.2f}");
    print(f"  Shipping: ${cashier.shipping:.2f}");
    print(f"  TOTAL:    ${total:.2f}");
}
