```jac
"""Build dependency audit: traverse a diamond-shaped task graph, summing
build minutes while auditing each task exactly once even when traversal
reaches it via multiple paths."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has task_count: int = 0;
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        # Cycle / multi-path guard: audit each task exactly once.
        already_seen = False;
        for prior in self.seen {
            if prior == here.title {
                already_seen = True;
                break;
            }
        }
        if already_seen {
            visit [-->];
        } else {
            self.seen.append(here.title);
            here.audited = True;
            self.total_minutes += here.minutes;
            self.task_count += 1;
            print(f"[AUDIT] {here.title} (+{here.minutes} min)");
            visit [-->];
        }
    }
}

with entry {
    # Diamond: both "ui_module" and "report_module" depend on "core_lib",
    # so naive traversal would reach core_lib twice. The auditor's seen
    # list ensures it is counted exactly once.
    ui = Task(title="ui_module", minutes=25);
    rep = Task(title="report_module", minutes=15);
    cl = Task(title="core_lib", minutes=10);

    root ++> ui;
    root ++> rep;
    ui ++> cl;
    rep ++> cl;

    auditor = BuildAuditor();
    root spawn auditor;
    print(f"Total build minutes: {auditor.total_minutes} across {auditor.task_count} unique tasks");
}
```

```jac
"""Workspace index builder that prevents symlink cycles during traversal.

Models the essential scenario from cadis issue #259: a search index is built
by iteratively walking a workspace graph, following parent/child directory
relationships. Without a visited set the walker spins forever on a symlink
cycle (e.g. a directory that links back to its ancestor). The fix is a
canonicalized-visited guard on a typed ``Contains`` edge walk, plus a depth
cap, mirroring the original issue's proposed remediation.
"""

node Dir {
    has name: str = "";
    # canonical identity -- if two nodes share the same canonical path they
    # are the same real directory, regardless of how the walker reached them
    has canonical: str = "";
    has depth: int = 0;
}

edge Contains { }

walker IndexBuilder {
    has max_depth: int = 32;
    has visited: list[str] = [];
    has indexed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Dir entry {
        canon = here.canonical;
        if canon in self.visited {
            print(f"[skip cycle] {here.name} (already visited as {canon})");
            disengage;
        }
        if here.depth > self.max_depth {
            print(f"[depth cap] {here.name} at depth {here.depth}");
            disengage;
        }
        self.visited = self.visited + [canon];
        self.indexed = self.indexed + [here.name];
        print(f"[index] {here.name} (depth={here.depth})");
        visit [-->];
    }
}

with entry {
    # a small workspace: root contains two siblings, one of which has a
    # back-edge to its grandparent that, without the visited guard, would
    # re-push the grandparent forever
    root_dir = Dir(name="/workspace", canonical="/workspace", depth=0);
    src = Dir(name="src", canonical="/workspace/src", depth=1);
    docs = Dir(name="docs", canonical="/workspace/docs", depth=1);
    loop = Dir(name="loop", canonical="/workspace/src/loop", depth=2);
    # the symlink target: a back-edge from `loop` up to `root_dir`
    root ++> root_dir;
    root_dir ++> src;
    root_dir ++> docs;
    src ++> loop;
    # symlink: loop -> /workspace (the canonical ancestor, already visited)
    loop ++> root_dir;

    builder = IndexBuilder();
    root spawn builder;

    print(f"\nindexed {len(builder.indexed)} dirs:");
    for n in builder.indexed {
        print(f"  - {n}");
    }
    print(f"visited guard saw {len(builder.visited)} canonical paths");
}
```

