```jac
"""Roadmap demo: memory layer traversal with native walkers.

Models the issue's scenario — a maintainer walks a versioned roadmap graph
where milestones (Completed/Open/Future) connect to features via typed
edges (DependsOn, Blocks, MigratesTo). A walker performs cascade
invalidation: when a feature is marked deprecated, dependent and blocking
features downstream are recursively invalidated through typed edges, with
an explicit cycle guard (no built-in dedupe in jac 0.36.1).
"""

node Feature {
    has title: str = "";
    has version: str = "";
    has status: str = "open";
    has deprecated: bool = False;
    has notes: str = "";
}

edge DependsOn {
    has strength: str = "hard";
}

edge Blocks {
    has reason: str = "";
}

edge MigratesTo {
    has threshold: str = "";
}

walker RoadmapAuditor {
    has deprecation_target: str = "Neo4j Backend";
    has guard: list[str] = [];
    has invalidations: list[str] = [];

    can start with Root entry {
        print(f"Auditor targeting deprecation: {self.deprecation_target}");
        visit [-->];
    }

    can fan_out with Feature entry {
        # Cycle guard: explicit (jac walkers do not dedupe by default).
        if here.title in self.guard {
            print(f"  cycle skip: {here.title}");
            visit [-->] else { disengage; }
            return;
        }
        self.guard.append(here.title);

        # Check if THIS feature is the deprecation target.
        if here.title == self.deprecation_target and not here.deprecated {
            here.deprecated = True;
            print(f"DEPRECATED: {here.title} ({here.version}) — {here.notes}");
        } else {
            print(f"[{here.status.upper():>9}] {here.version:>8}  {here.title}");
        }

        # Cascade: walk downstream dependents + blockers + migrations.
        visit [->:DependsOn:->];
        visit [->:Blocks:->];
        visit [->:MigratesTo:->];
    }
}

walker DependencySweeper {
    has seen: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        print("\nDependency order (Features only, typed-edge traversal):");
        visit [-->];
    }

    can rank with Feature entry {
        if here.title in self.seen {
            visit [-->] else { disengage; }
            return;
        }
        self.seen.append(here.title);
        self.order.append(here.title);
        visit [->:DependsOn:->];
        visit [->:Blocks:->];
        visit [->:MigratesTo:->];
    }

    can finalize with Root exit {
        for (i, name) in enumerate(self.order) {
            print(f"  {i + 1}. {name}");
        }
    }
}

with entry {
    # ---- Build the roadmap graph ------------------------------------------
    cost_routing = Feature(
        title="Cost-Aware Routing",
        version="v0.8.0",
        status="completed",
        notes="tier-based embedding provider selection",
    );
    kg_layer = Feature(
        title="Knowledge Graph Layer",
        version="v0.7.0",
        status="completed",
        notes="entity extraction, typed relationships, graph traversal",
    );
    session_pipe = Feature(
        title="Session->Memory Pipeline",
        version="v0.6.0",
        status="completed",
        notes="native fact extraction in on_session_end",
    );
    supersession = Feature(
        title="Auto-Supersession",
        version="v0.5.1",
        status="completed",
        notes="similarity > 0.90",
    );
    guardrails = Feature(
        title="Active Guardrails",
        version="v0.5.0",
        status="completed",
        notes="memory-driven prevention of destructive actions",
    );
    sica = Feature(
        title="SICA Self-Improvement",
        version="v0.9.0",
        status="open",
        notes="LLM-assisted memory consolidation",
    );
    neo4j = Feature(
        title="Neo4j Backend",
        version="v1.0.0",
        status="future",
        notes="migrate graph layer at ~100K entities",
    );

    # Completed layer — linear historical chain.
    root ++> cost_routing
        ++> kg_layer
        ++> session_pipe
        ++> supersession
        ++> guardrails;

    # Open + Future attached from root.
    root ++> sica;
    root ++> neo4j;

    # Typed relationships — SICA depends on KG Layer; KG Layer blocks Neo4j
    # migration (must wait for deprecation); Neo4j migrates to replace the
    # Qdrant graph layer.
    sica +>:DependsOn(strength="hard"):+> kg_layer;
    sica +>:DependsOn(strength="hard"):+> guardrails;
    kg_layer +>:Blocks(reason="Qdrant under threshold"):+> neo4j;
    sica +>:Blocks(reason="uses current graph API"):+> neo4j;
    neo4j +>:MigratesTo(threshold="100K entities"):+> kg_layer;

    # ---- Demo 1: cascade invalidation ------------------------------------
    print("=== Cascade Invalidation Demo ===");
    auditor = RoadmapAuditor(deprecation_target="Neo4j Backend");
    root spawn auditor;
    print(f"\nInvalidations recorded: {auditor.invalidations}");
    print(f"Neo4j deprecated? {neo4j.deprecated}");

    # ---- Demo 2: dependency ordering via typed-edge walker ---------------
    sweeper = DependencySweeper();
    root spawn sweeper;
}
```

