"""Factory patrol: one monitoring routine handles both temperature and smoke sensors, printing readings and summarizing alerts."""

node Sensor {
    has label: str = "";
    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;
    def is_alert() -> bool;
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;
    def is_alert() -> bool;
}

node Zone {
    has zone_name: str = "";
}

walker Patrol {
    has alert_count: int = 0;

    can start with Root entry {
        print("=== Beginning factory patrol ===");
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"--- Sweeping zone: {here.zone_name} ---");
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            print(f"[ALERT] {here.label}: reading exceeds threshold");
            self.alert_count += 1;
        } else {
            print(f"nominal: {here.label} reading within range");
        }
    }
}

impl Sensor.is_alert() -> bool {
    return False;
}

impl TempSensor.is_alert() -> bool {
    return self.celsius > 75.0;
}

impl SmokeSensor.is_alert() -> bool {
    return self.ppm > 50.0;
}

with entry {
    zone_a = Zone(zone_name="Assembly");
    zone_b = Zone(zone_name="Packaging");
    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Temp-A1", celsius=82.3);
    zone_a ++> SmokeSensor(label="Smoke-A1", ppm=22.0);
    zone_b ++> TempSensor(label="Temp-B1", celsius=68.5);
