```jac
"""Bug tracker: file tickets off a project and grab the freshly-connected node in one expression.

Demonstrates the grouped ``root ++> (t := Ticket(...));`` form that lets the
caller capture the node returned by the connection itself, then immediately
read its ``title`` and ``priority`` without a separate lookup.
"""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has available: bool = True;
}

walker Auditor {
    can start with Root entry {
        print(f"--- Project walk ---");
        visit [-->];
    }

    can review with Project entry {
        print(f"Project: {here.name}");
        visit [-->];
    }

    can audit with Ticket entry {
        status = "OPEN" if here.available else "CLOSED";
        print(f"  [{status}] {here.title} (priority={here.priority})");
        visit [-->];
    }
}

with entry {
    # Connect AND grab the fresh ticket in one expression. The grouped
    # form `p ++> (t := Ticket(...));` returns the connected node so
    # we never need a follow-up lookup query.
    root ++> (p := Project(name="BugBot"));

    p ++> (t1 := Ticket(title="Login crashes on Safari", priority="high"));
    print(f"Just filed: {t1.title} [{t1.priority}]");

    p ++> (t2 := Ticket(title="Typo in footer", priority="low"));
    print(f"Just filed: {t2.title} [{t2.priority}]");

    p ++> (t3 := Ticket(title="Race condition in queue", priority="critical", available=False));
    print(f"Just filed: {t3.title} [{t3.priority}]");

    # Now walk the graph and audit every ticket under the project.
    print("");
    root spawn Auditor();
}
