```jac
"""LilySdkError serialization demo.

Models the error hierarchy described in issue #60: an SLDError base node with
typed ``code``, ``statusCode``, ``details``, and a ``cause`` edge to nested
errors. A walker traverses the chain of causes to serialize the full tree
without circular-reference explosions, mimicking the proposed ``toJSON()``.
"""

node SLDError {
    has name: str = "SLDError";
    has message: str = "";
    has code: str = "";
    has status_code: int = 0;
    has details: dict = {};
}

node SLDNetworkError(SLDError) {
    has name: str = "SLDNetworkError";
}

node SLDApiError(SLDError) {
    has name: str = "SLDApiError";
}

edge CausedBy {
    has label: str = "cause";
}

walker ErrorSerializer {
    has out: list = [];
    has depth: int = 0;
    has max_depth: int = 8;
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can serialize with SLDError entry {
        # Cycle guard: the same node should never appear twice in one chain.
        if here in self.seen {
            disengage;
        }
        self.seen.append(here);

        # Depth guard: runaway chains still terminate.
        if self.depth >= self.max_depth {
            disengage;
        }

        # Build the JSON-shaped record (matches the proposed toJSON()).
        record: dict = {
            "name": here.name,
            "message": here.message,
            "code": here.code,
            "statusCode": here.status_code,
            "details": here.details,
            "cause": None,
        };
        self.out.append((self.depth, record));

        # Move to the next cause edge, if any.
        self.depth += 1;
        visit [->:CausedBy:->] else {
            disengage;
        }
    }
}

walker ErrorPrinter {
    can start with Root entry {
        print("=== SLDError toString() simulation ===");
        visit [-->];
    }

    can describe with SLDError entry {
        # Mimic the proposed toString(): base + code + statusCode if set.
        suffix: str = "";
        if here.code != "" {
            suffix = suffix + f" [code={here.code}]";
        }
        if here.status_code != 0 {
            suffix = suffix + f" [status={here.status_code}]";
        }
        print(f"{here.name}: {here.message}{suffix} :: {here.details}");

        # Follow the cause edge to print nested causes too.
        visit [->:CausedBy:->] else {
            disengage;
        }
    }
}

with entry {
    # Build a small error graph: an API error caused by a network error,
    # which is itself caused by a low-level connection error.
    low_level = SLDNetworkError(
        name="SLDNetworkError",
        message="connection refused",
        code="NET_CONN_REFUSED",
        status_code=0,
        details={"host": "api.example.com", "port": 443},
    );
    mid_level = SLDApiError(
        name="SLDApiError",
        message="upstream timeout",
        code="API_TIMEOUT",
        status_code=504,
        details={"endpoint": "/v1/orders", "timeout_ms": 30000},
    );
    top_level = SLDApiError(
        name="SLDApiError",
        message="failed to place order",
        code="ORDER_REJECTED",
        status_code=422,
        details={"order_id": "ord_42", "reason": "inventory"},
    );

    # Typed edges express the cause chain; a back-edge would test the cycle
    # guard below, but here we keep it linear for the demo.
    top_level +>:CausedBy:+> mid_level;
    mid_level +>:CausedBy:+> low_level;

    # Demo 1: toString()-style flat walk.
    root ++> top_level;
    root spawn ErrorPrinter();

    # Demo 2: toJSON()-style depth-aware walk, then print the records.
    ser = ErrorSerializer();
    root spawn ser;
    print("\n=== SLDError toJSON() simulation ===");
    for (level, rec) in ser.out {
        indent: str = "  " * level;
        cause_marker: str = "" if rec["cause"] is None else f" -> cause[{level}]";
        print(f"{indent}{rec['name']}({rec['code']}/{rec['statusCode']}): "
              f"{rec['message']} details={rec['details']}{cause_marker}");
    }

    # Demo 3: cycle guard. Add a back-edge to prove the walker doesn't loop.
    low_level +>:CausedBy:+> top_level;
    cyc = ErrorSerializer();
    root spawn cyc;
    print(f"\n=== Cycle guard ===");
    print(f"Chain depth after back-edge walk: {cyc.depth} "
          f"(records collected: {len(cyc.out)}) -- no infinite loop");
}
