```jac
"""Stacked merge-request dependency dispatch: blockers, review gates, and branch-base selection."""

node WorkflowConfig {
    has stacked_branches_enabled: bool = False;
    has default_branch: str = "main";
}

node Issue {
    has title: str = "";
    has status: str = "Todo";
    has branch: str = "";
    has head_sha: str = "";
    has has_open_pr: bool = False;
    has pr_draft: bool = False;
    has pr_merged: bool = False;
}

node DependentIssue(Issue) { }

node BlockerIssue(Issue) { }

edge BlockedBy { }

edge StackedFrom {
    has parent_sha: str = "";
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with DependentIssue entry {
        self.stack.append(here.title);
        visit [->:BlockedBy:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }

    can walk with BlockerIssue entry {
        if here.title in self.stack {
            self.cycle_detected = True;
            disengage;
        }
        self.stack.append(here.title);
        visit [->:BlockedBy:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker StackedDispatchAuditor {
    has stacked_enabled: bool = False;
    has default_branch: str = "main";
    has unmerged: int = 0;
    has review_eligible: int = 0;
    has parent_branch: str = "";
    has parent_title: str = "";
    has parent_sha: str = "";
    has decision: str = "hold";
    has base_branch: str = "";
    has wait_reason: str = "";

    def apply_policy() {
        if self.unmerged == 0 {
            self.decision = "dispatch";
            self.base_branch = self.default_branch;
            self.wait_reason = "all_blockers_merged";
        } else {
            if self.stacked_enabled == False {
                self.decision = "hold";
                self.wait_reason = "stacked_disabled_pending_blockers";
            } else {
                if self.unmerged >= 2 {
                    self.decision = "hold";
                    self.wait_reason = "multiple_unmerged_blockers";
                } else {
                    if self.review_eligible >= 2 {
                        self.decision = "hold";
                        self.wait_reason = "multiple_human_review_parents";
                    } else {
                        if self.unmerged == 1 {
                            if self.review_eligible == 1 {
                                self.decision = "dispatch_stacked";
                                self.base_branch = self.parent_branch;
                                self.wait_reason = "stacked_from_human_review_parent";
                            } else {
                                self.decision = "hold";
                                self.wait_reason = "blocker_not_eligible_for_stack";
                            }
                        } else {
                            self.decision = "hold";
                            self.wait_reason = "blocker_not_eligible_for_stack";
                        }
                    }
                }
            }
        }
    }

    can audit_enter with DependentIssue entry {
        visit [->:BlockedBy:->];
    }

    can audit_leave with DependentIssue exit {
        self.apply_policy();
    }

    can inspect with BlockerIssue entry {
        merged = False;
        if here.status == "Merged" {
            merged = True;
        }
        if here.pr_merged == True {
            merged = True;
        }
        if merged == False {
            self.unmerged += 1;
            review_ready = False;
            if here.status == "Human Review" {
                if here.has_open_pr == True {
                    if here.pr_draft == False {
                        if here.pr_merged == False {
                            if here.branch != "" {
                                review_ready = True;
                            }
                        }
                    }
                }
            }
            if review_ready == True {
                self.review_eligible += 1;
                self.parent_branch = here.branch;
                self.parent_title = here.title;
                self.parent_sha = here.head_sha;
            }
        }
    }
}

walker ReanchorAuditor {
    has default_branch: str = "main";
    has action: str = "waiting";
    has old_base: str = "";
    has new_base: str = "";

    can start with DependentIssue entry {
        visit [->:BlockedBy:->] else {
            disengage;
        };
    }

    can on_parent with BlockerIssue entry {
        parent_merged = False;
        if here.status == "Merged" {
            parent_merged = True;
        }
        if here.pr_merged == True {
            parent_merged = True;
        }
        if parent_merged == True {
            self.action = "retarget_pr_to_main";
            self.old_base = here.branch;
            self.new_base = self.default_branch;
        } else {
            self.action = "pause_until_parent_merges";
            self.old_base = here.branch;
            self.new_base = here.branch;
        }
    }
}

with entry {
    cfg = WorkflowConfig(stacked_branches_enabled=True, default_branch="main");
    root ++> cfg;

    merged_blocker = BlockerIssue(
        title="auth-hardening",
        status="Merged",
        branch="feat/auth-hardening",
        head_sha="aaa111",
        has_open_pr=True,
        pr_merged=True
    );
    review_parent = BlockerIssue(
        title="api-contract",
        status="Human Review",
        branch="feat/api-contract",
        head_sha="bbb222",
        has_open_pr=True
    );
    stacked_child = DependentIssue(title="stacked-ui", status="Todo");
    clean_child = DependentIssue(title="docs-only", status="Todo");
    cyclic_a = BlockerIssue(title="cycle-a", status="In Progress", branch="feat/cycle-a");
    cyclic_b = BlockerIssue(title="cycle-b", status="In Progress", branch="feat/cycle-b");
    cyclic_child = DependentIssue(title="cycle-child", status="Todo");

    clean_child +>:BlockedBy:+> merged_blocker;
    stacked_child +>:BlockedBy:+> review_parent;
    cyclic_child +>:BlockedBy:+> cyclic_a;
    cyclic_b +>:BlockedBy:+> cyclic_a;
    cyclic_a +>:BlockedBy:+> cyclic_b;

    root ++> merged_blocker ++> review_parent ++> stacked_child;
    root ++> clean_child;
    root ++> cyclic_child;

    cycle_guard = CycleGuard();
    cyclic_child spawn cycle_guard;

    stacked_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    stacked_child spawn stacked_audit;
    if stacked_audit.decision == "dispatch_stacked" {
        review_parent +>:StackedFrom(parent_sha=stacked_audit.parent_sha):+> stacked_child;
    }

    clean_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    clean_child spawn clean_audit;

    reanchor = ReanchorAuditor(default_branch=cfg.default_branch);
    clean_child spawn reanchor;

    print(f"[cycle] cyclic_child cycle_detected={cycle_guard.cycle_detected}");
    print(
        f"[stacked] {stacked_child.title} decision={stacked_audit.decision} "
        f"base={stacked_audit.base_branch} reason={stacked_audit.wait_reason} "
        f"parent={stacked_audit.parent_title}@{stacked_audit.parent_sha}"
    );
    print(
        f"[merged] {clean_child.title} decision={clean_audit.decision} "
        f"base={clean_audit.base_branch} reason={clean_audit.wait_reason}"
    );
    print(
        f"[reanchor] parent merged -> action={reanchor.action} "
        f"old_base={reanchor.old_base} new_base={reanchor.new_base}"
    );
}
