```jac
"""Health-inspect a restaurant kitchen line.

Two inspections run at every station (grill, fryer, cold prep):
  * Temperature check: any station above 40 C is a violation.
  * Visit log: every station visit is recorded.
Both checks fire at every station because they are separate union
abilities on the same set of station node types.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;

    def label() -> str {
        return self.name;
    }
}
node Grill(Station) {
    override def label() -> str {
        return f"{self.name} (grill)";
    }
}
node Fryer(Station) {
    override def label() -> str {
        return f"{self.name} (fryer)";
    }
}
node ColdPrep(Station) {
    override def label() -> str {
        return f"{self.name} (cold prep)";
    }
}

walker HealthInspector {
    has violations: int = 0;
    has visits: list[str] = [];

    can start with Root entry {
        print(f"Health inspector starting tour; threshold = 40 C");
        visit [-->] else { disengage; }
    }

    # First check: temperature. Union trigger fires at every station.
    can check_temp with Grill | Fryer | ColdPrep entry {
        flagged = here.celsius > 40.0;
        if flagged {
            self.violations += 1;
            print(f"[VIOLATION] {here.label()} at {here.celsius} C exceeds 40 C");
        } else {
            print(f"[OK] {here.label()} at {here.celsius} C is safe");
        }
    }

    # Second check: visit log. Runs at every station regardless of
    # temperature result, because it is a separate union ability.
    can log_visit with Grill | Fryer | ColdPrep entry {
        self.visits.append(here.label());
        print(f"[LOG] visited {here.label()}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Grill(name="Char-broiler", celsius=220.0)
        ++> Fryer(name="Deep fryer", celsius=180.0)
        ++> ColdPrep(name="Salad station", celsius=4.0);

    inspector = HealthInspector();
    root spawn inspector;

    print(f"--- summary ---");
    print(f"violations: {inspector.violations}");
    print(f"stations visited: {inspector.visits}");
}
