```jac
"""Order auditor: skip invalid orders and halt the walk on fraud flags."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Audit walk starting");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud_flag {
            print(f"HALT fraud order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"SKIP invalid order amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"OK audited order amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True, fraud_flag=False)
        ++> Order(amount=0.0, valid=False, fraud_flag=False)
        ++> Order(amount=85.0, valid=True, fraud_flag=False)
        ++> Order(amount=999.0, valid=True, fraud_flag=True)
        ++> Order(amount=40.0, valid=True, fraud_flag=False);
    root spawn OrderAuditor();
}
```

```jac
"""Read the public feed off the shared root.

This is the reader half of my micro-blog. Any caller -- even anonymous
-- can walk the shared root's children because the shared root's access
level floors at CONNECT, so listing posts needs no auth at all. Only
posts whose authors armed a READ grant show real content to other users;
on a single-user CLI run everything is visible since root.shared is just
root.
"""

node Post {
    has text: str;
    has author: str;
}

edge Posted { }

walker:pub publish_post {
    has text: str;
    has author: str = "anon";

    can run with Root entry {
        fresh = root.shared +>: Posted() :+> Post(text=self.text, author=self.author);
        grant(fresh, level=AccessLevel.READ);
    }
}

walker:pub read_feed {
    can run with Root entry {
        # Traversal from the shared commons; order follows creation order.
        posts = [p for p in [root.shared ->:Posted:->][?:Post]];
        report [{"author": p.author, "text": p.text} for p in posts];
    }
}

with entry {
    root spawn publish_post(text="first!", author="ada");
    root spawn publish_post(text="second post", author="ben");
    root spawn publish_post(text="a quiet third", author="cy");

    result = root spawn read_feed();
    print(result.reports);
}
```

```jac
"""Orchard maintenance tour.

A crew walks the groves servicing two kinds of devices (pumps and sprinklers)
using one shared ability that fires for both device types via a union trigger.
Each device logs its kind, reports idle hours, resets its counter, and the
walker's running total of serviced devices is reported on disengage.
"""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;

    # Shared device contract used by the union ability.
    def kind() -> str {
        return "Pump";
    }
    def reset() -> None {
        self.idle_hours = 0;
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;

    # Shared device contract used by the union ability.
    def kind() -> str {
        return "Sprinkler";
    }
    def reset() -> None {
        self.idle_hours = 0;
    }
}

walker Crew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew entering the orchard");
        visit [-->] else { disengage; }
    }

    can traverse with Pump | Sprinkler entry {
        self.serviced += 1;
        print(f"Servicing {here.kind()} '{here.label}': "
              f"idle {here.idle_hours}h, resetting");
        here.reset();
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pump(label="Pump-A", idle_hours=12)
        ++> Sprinkler(label="Sprink-1", idle_hours=6)
        ++> Pump(label="Pump-B", idle_hours=3)
        ++> Sprinkler(label="Sprink-2", idle_hours=9)
        ++> Pump(label="Pump-C", idle_hours=15);

    crew = Crew();
    root spawn crew;
    print(f"Total devices serviced: {crew.serviced}");
}
```

