```jac
"""Performance re-verification trainer: a small graph of verification tasks and
the gates they must satisfy before release. A walker audits the dependency
chain, detects cycles, computes topological order, and verifies that every
task has evidence attached before the gate can pass."""

node Task {
    has title: str = "";
    has phase: int = 0;
    has has_evidence: bool = False;
}

node Gate {
    has name: str = "";
    has threshold_s: float = 0.0;
    has threshold_ms: float = 0.0;
    has measured_s: float = 0.0;
    has measured_ms: float = 0.0;
    has has_evidence: bool = False;
    has passed: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

edge VerifiedBy {}

walker Auditor {
    has visited_ids: list = [];
    has order: list = [];
    has cycle_found: bool = False;
    has blockers: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_gate with Gate entry {
        gate_pass = (here.measured_s <= here.threshold_s)
            and (here.measured_ms <= here.threshold_ms)
            and here.has_evidence;
        here.passed = gate_pass;
        reason = "G2+G3 within budget" if gate_pass else "REGRESSION";
        print(f"Gate {here.name}: measured {here.measured_s}s / {here.measured_ms}ms "
              f"vs threshold {here.threshold_s}s / {here.threshold_ms}ms -> {reason}");
        visit [-->];
    }

    can audit_task with Task entry {
        node_id = here.title;
        if node_id in self.visited_ids {
            self.cycle_found = True;
            print(f"CYCLE detected revisiting task {node_id}");
            disengage;
        }
        self.visited_ids = self.visited_ids + [node_id];
        if not here.has_evidence {
            blocker = f"task {node_id} missing evidence";
            self.blockers = self.blockers + [blocker];
            print(f"BLOCKER: {blocker}");
        }
        self.order = self.order + [node_id];
        visit [->:DependsOn:->];
    }
}

with entry {
    # Build the dependency graph of verification tasks.
    t_perf = Task(title="T127 perf re-verify", phase=14, has_evidence=True);
    t_lint = Task(title="pnpm lint", phase=14, has_evidence=True);
    t_type = Task(title="pnpm typecheck", phase=14, has_evidence=True);
    t_arch = Task(title="check architecture", phase=14, has_evidence=True);
    t_contr = Task(title="check contracts", phase=14, has_evidence=False);

    # Gates feed forward in serial order; G6 depends on G5 etc.
    g2 = Gate(name="G2", threshold_s=5.0, threshold_ms=0.0,
              measured_s=4.2, measured_ms=0.0, has_evidence=True);
    g3 = Gate(name="G3", threshold_s=0.0, threshold_ms=50.0,
              measured_s=0.0, measured_ms=42.0, has_evidence=True);
    g5 = Gate(name="G5", threshold_s=0.0, threshold_ms=0.0,
              measured_s=0.0, measured_ms=0.0, has_evidence=True);
    g6 = Gate(name="G6", threshold_s=0.0, threshold_ms=0.0,
              measured_s=0.0, measured_ms=0.0, has_evidence=True);

    # Gate chain: each gate depends on the previous one.
    g2 +>:DependsOn:+> g3;
    g3 +>:DependsOn:+> g5;
    g5 +>:DependsOn:+> g6;

    # Performance verification task feeds G6.
    g6 +>:VerifiedBy:+> t_perf;
    t_perf +>:DependsOn:+> t_lint;
    t_perf +>:DependsOn:+> t_type;
    t_perf +>:DependsOn:+> t_arch;
    t_perf +>:DependsOn:+> t_contr;

    root ++> g2 ++> t_perf;

    auditor = Auditor();
    root spawn auditor;

    if auditor.cycle_found {
        print("Audit FAILED: dependency cycle detected");
    } elif len(auditor.blockers) > 0 {
        print(f"Audit FAILED: {len(auditor.blockers)} blocker(s); release blocked");
    } else {
        print(f"Audit PASSED in order {auditor.order}");
    }
}
```

```jac
"""Tesseract DEV shadow baseline: model the seam-driven CPU OCR evaluation.

Two deterministic DEV runs are gated by a single admission policy. The
walkers traverse typed edges to:
  - verify the Tesseract provider is ADMITTED before any run starts,
  - execute run #1 then run #2 (dependency ordering),
  - collect structural/downstream/failure/latency/resource metrics,
  - enforce that HOLDOUT access and provider writes never occur.
"""

node Artifact {
    has name: str = "";
    has kind: str = "";
    has normalized: bool = False;
}

node Provider {
    has name: str = "";
    has admitted: bool = False;
    has cost: float = 0.0;
}

node Run {
    has label: str = "";
    has deterministic: bool = False;
    has completed: bool = False;
    has holdout_touched: bool = False;
    has latency_ms: int = 0;
    has rss_mb: int = 0;
}

node Metric {
    has kind: str = "";
    has value: float = 0.0;
    has unit: str = "";
}

edge Supplies { }
edge RunsOn { }
edge Produces { }
edge Proves { }

walker RunBaseline {
    has provider_name: str = "tesseract";
    has run_count: int = 0;
    has fail_count: int = 0;
    has seen_providers: list = [];

    can start with Root entry {
        print(f"[BASELINE] seam=main assignments=stable evaluator=v1");
        visit [-->];
    }

    can check_provider with Provider entry {
        self.seen_providers.append(here.name);
        if here.name != self.provider_name {
            visit [-->];
            return;
        }
        if not here.admitted {
            self.fail_count += 1;
            print(f"[GATE] {here.name} NOT ADMITTED -> baseline blocked");
            disengage;
        }
        if here.cost != 0.0 {
            self.fail_count += 1;
            print(f"[GUARD] cost {here.cost} != 0 -> baseline blocked");
            disengage;
        }
        print(f"[ADMIT] {here.name} cost={here.cost} status=ADMITTED");
        visit [-->];
    }

    can gather_artifacts with Artifact entry {
        status = "normalized" if here.normalized else "raw";
        print(f"[ARTIFACT] {here.name} kind={here.kind} state={status}");
        visit [-->];
    }

    can execute with Run entry {
        if not here.deterministic {
            self.fail_count += 1;
            print(f"[FAIL] {here.label} not deterministic");
            disengage;
        }
        if here.holdout_touched {
            self.fail_count += 1;
            print(f"[GUARD] {here.label} touched HOLDOUT -> blocked");
            disengage;
        }
        here.completed = True;
        self.run_count += 1;
        print(f"[RUN {self.run_count}/2] {here.label} "
              f"latency={here.latency_ms}ms rss={here.rss_mb}MB");
        visit [-->];
    }

    can collect with Metric entry {
        print(f"[METRIC] {here.kind}={here.value}{here.unit}");
        visit [-->];
    }
}

with entry {
    pp = Provider(name="pp-structurev3", admitted=True, cost=0.0);
    tesseract = Provider(name="tesseract", admitted=True, cost=0.0);
    blocked = Provider(name="cloud-ocr", admitted=False, cost=0.0);

    normalized = Artifact(name="ocr_ir_v1", kind="projection", normalized=True);
    gold = Artifact(name="gold_set", kind="reference", normalized=True);

    r1 = Run(label="DEV-A", deterministic=True, holdout_touched=False,
             latency_ms=4200, rss_mb=380);
    r2 = Run(label="DEV-B", deterministic=True, holdout_touched=False,
             latency_ms=4180, rss_mb=375);

    structural = Metric(kind="structural", value=0.91, unit="f1");
    downstream = Metric(kind="downstream", value=0.87, unit="acc");
    failure = Metric(kind="failure", value=0.03, unit="rate");
    latency = Metric(kind="latency", value=4190.0, unit="ms");
    resource = Metric(kind="rss", value=377.5, unit="MB");

    root +>:Supplies:+> pp;
    root +>:Supplies:+> tesseract;
    root +>:Supplies:+> blocked;

    tesseract +>:RunsOn:+> normalized;
    tesseract +>:RunsOn:+> gold;

    normalized +>:Produces:+> r1;
    gold +>:Produces:+> r1;
    normalized +>:Produces:+> r2;
    gold +>:Produces:+> r2;

    r1 +>:Proves:+> structural;
    r1 +>:Proves:+> downstream;
    r2 +>:Proves:+> failure;
    r2 +>:Proves:+> latency;
    r2 +>:Proves:+> resource;

    w = RunBaseline();
    root spawn w;

    print(f"[SUMMARY] runs={w.run_count} providers_seen={w.seen_providers} "
          f"failures={w.fail_count}");
}
```

```jac
"""Environment variable resolution with cycle detection.

Models the JENKINS-33239 scenario where a variable like
LD_LIBRARY_PATH=$ORACLE_HOME/lib:$LD_LIBRARY_PATH gets expanded
recursively until it runs out of memory. Here we express the
definition graph as typed edges between Variable nodes and let a
walker traverse it. Without a cycle guard the walker would loop
forever (the original bug); with the guard it terminates and
reports the offending cycle.
"""

node Variable {
    has name: str = "";
    has value: str = "";
}

# A definition edge says: this variable's R-value references that
# variable (e.g. LD_LIBRARY_PATH -> LD_LIBRARY_PATH is the self-cycle
# that triggers the bug).
edge Refs {
    has var_name: str = "";
}

walker Resolver {
    has max_depth: int = 32;
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand with Variable entry {
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[HALT] depth>{self.max_depth} at {here.name} -- runaway recursion (the JENKINS-33239 bug)");
            disengage;
        }
        if here.name in self.seen {
            cycle = self.seen[-1] + " -> " + here.name;
            print(f"[CYCLE] {cycle}");
            disengage;
        }
        self.seen.append(here.name);
        print(f"resolve {here.name} = {here.value} (path={' -> '.join(self.seen)})");
        # Follow every typed reference this variable makes in its R-value.
        visit [->:Refs:->];
    }
}

with entry {
    # Build the graph: LD_LIBRARY_PATH references both ORACLE_HOME/lib
    # and itself -- the self-reference is exactly the JENKINS-33239 case.
    path = Variable(name="LD_LIBRARY_PATH", value="$ORACLE_HOME/lib:$LD_LIBRARY_PATH");
    oracle = Variable(name="ORACLE_HOME", value="/opt/oracle");
    home = Variable(name="HOME", value="/root");

    # Typed edges carry the referenced variable's name as payload.
    path +>:Refs(var_name="ORACLE_HOME"):+> oracle;
    path +>:Refs(var_name="LD_LIBRARY_PATH"):+> path;
    oracle +>:Refs(var_name="HOME"):+> home;

    root ++> path;

    print("--- scenario 1: graph with self-cycle (the reported bug) ---");
    Resolver() spawn root;

    print("");
    print("--- scenario 2: same walker, no self-cycle, terminates cleanly ---");
    safe = Variable(name="PATH", value="path1:$HOME");
    safe +>:Refs(var_name="HOME"):+> home;
    root ++> safe;
    Resolver() spawn safe;
}
```

```jac
"""Neighborhood mutual friendships.

Houses are nodes. A buddy edge is bidirectional — declared in a single
statement. Two greeter walkers spawn at opposite houses; each proves the
link is reciprocal by reaching the other with forward traversal only,
without ping-ponging forever.
"""

node House {
    has name: str = "";
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has visited: list = [];
    has target: str = "";

    can start with Root entry {
        self.visited = [here];
        visit [-->];
    }

    can greet with House entry {
        self.visited.append(here);
        if here.name == self.target {
            print(f"{self.visited[0].name} -> {here.name}: reached friend '{here.name}'");
            disengage;
        }
        # Forward-only traversal: visit Buddy neighbors we haven't seen yet.
        forward = [n for n in [-->] if n not in self.visited];
        if not forward {
            disengage;
        }
        visit forward;
    }
}

with entry {
    alice = House(name="Alice");
    bob = House(name="Bob");

    # Single statement that creates a bidirectional buddy link between
    # Alice's house and Bob's house.
    alice +>:Buddy(since="2024"):+> bob;
    bob +>:Buddy(since="2024"):+> alice;

    root ++> alice ++> bob;

    # Spawn a greeter at each house; each must reach the other using
    # forward traversal alone, and must not bounce back forever.
    Greeter(target="Bob") spawn alice;
    Greeter(target="Alice") spawn bob;
}
