```jac
"""Restaurant kitchen line health-inspection walker.

Two inspectors tour the same line: a ``TempAuditor`` that flags any
station whose temperature exceeds 40 C as a violation, and a
``VisitLogger`` that records every station visit. Both walkers run
across every station in the kitchen.
"""

node Station {
    has title: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker TempAuditor {
    has violations: int = 0;
    has checked: int = 0;

    can start with Root entry {
        print("TempAuditor: beginning kitchen inspection");
        visit [-->];
    }

    can audit with Station entry {
        self.checked += 1;
        if here.is_violation() {
            self.violations += 1;
