        print(f"{here.location}: {here.celsius} C");
        self.readings.append(f"{here.location}={here.celsius} C");
        if self.count == 0 {
            self.min_celsius = here.celsius;
            self.max_celsius = here.celsius;
        } else {
            next_min = here.celsius if here.celsius < self.min_celsius else self.min_celsius;
            self.min_celsius = next_min;
            next_max = here.celsius if here.celsius > self.max_celsius else self.max_celsius;
            self.max_celsius = next_max;
        }
        self.count += 1;
        visit [-->] else {
            print(f"Readings: {self.readings}");
            print(f"Min: {self.min_celsius} C, Max: {self.max_celsius} C");
            disengage;
        };
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Uplands", celsius=26.3);
    root spawn WeatherSweep();
}
