```jac
"""X.509 bounded certification path construction and validation demo.

Models the essential entities from the x509_path stdlib module:
certificates (leaf, intermediates, trust anchors) are nodes; the
``IssuedBy`` typed edge models the issuer-subject chain that the
construct/validate walker traverses. The walker walks candidate paths
from a leaf back toward a trust anchor, enforcing BasicConstraints
CA/pathLen, rejecting cycles and duplicates, and producing a structured
result without any network I/O. The validation instant is an explicit
walker ``has`` field rather than wall-clock state.
"""

node Cert {
    has label: str = "";
    has subject: str = "";
    has issuer: str = "";
    has is_ca: bool = False;
    has pathlen: int = -1;
    has not_before: int = 0;
    has not_after: int = 0;
    has trust_anchor: bool = False;
}

edge IssuedBy {
    has depth: int = 0;
    has ok: bool = True;
}

walker PathBuilder {
    has validation_time: int = 0;
    has max_depth: int = 4;
    has verdict: str = "indeterminate";
    has length: int = 0;
    has reason: str = "";
    has found_anchor: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can try_build with Cert entry {
        if here.trust_anchor {
            self.found_anchor = True;
            self.verdict = "valid";
            self.reason = "trusted anchor reached";
            disengage;
        }
        non_ca_intermediate = (not here.is_ca) and (self.length > 0);
        if non_ca_intermediate {
            self.verdict = "invalid";
            self.reason = "non-CA cert used as intermediate";
            disengage;
        }
        if self.length > self.max_depth {
            self.verdict = "invalid";
            self.reason = "path too long";
            disengage;
        }
        expired = (self.validation_time < here.not_before)
            or (self.validation_time > here.not_after);
        if expired {
            self.verdict = "invalid";
            self.reason = "expired or not yet valid";
            disengage;
        }
        self.length += 1;
        visit [->:IssuedBy:->];
    }
}

walker PathAuditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Cert entry {
        candidates = [->:IssuedBy:->];
        line = f"{here.label}: candidates={len(candidates)}";
        self.report_lines.append(line);
        visit [->:IssuedBy:->];
    }
}

with entry {
    leaf = Cert(
        label="leaf.example.com",
        subject="CN=leaf.example.com",
        issuer="CN=intermediate-A",
        is_ca=False,
        not_before=0,
        not_after=1000
    );
    intermediate = Cert(
        label="intermediate-A",
        subject="CN=intermediate-A",
        issuer="CN=root-CA",
        is_ca=True,
        pathlen=1,
        not_before=0,
        not_after=2000
    );
    trust_root = Cert(
        label="root-CA",
        subject="CN=root-CA",
        issuer="CN=root-CA",
        is_ca=True,
        pathlen=2,
        not_before=0,
        not_after=3000,
        trust_anchor=True
    );
    foreign = Cert(
        label="untrusted-root",
        subject="CN=untrusted-root",
        issuer="CN=untrusted-root",
        is_ca=True,
        not_before=0,
        not_after=3000,
        trust_anchor=False
    );

    leaf +>:IssuedBy(depth=1, ok=True):+> intermediate;
    intermediate +>:IssuedBy(depth=2, ok=True):+> trust_root;

    builder = PathBuilder(validation_time=500, max_depth=3);
    leaf spawn builder;
    print(f"happy-path verdict={builder.verdict} length={builder.length} reason={builder.reason}");

    bad_builder = PathBuilder(validation_time=5000, max_depth=3);
    leaf spawn bad_builder;
    print(f"expired verdict={bad_builder.verdict} length={bad_builder.length} reason={bad_builder.reason}");

    auditor = PathAuditor();
    leaf spawn auditor;
    for line in auditor.report_lines {
        print(f"audit {line}");
    }

    print("revocation-not-checked: V1 does not fetch CRL/OCSP/AIA");
}
