```jac
"""Lakehouse pipeline decoupling demo.

Models the tension described in Lakehouse_Plumber issue #212: a single
``pipeline:`` value on every flowgroup collapses the generated output into
one flat folder and one bundle resource file, destroying the source-side
medallion organization. We model flowgroups, their layer membership, and
the pipeline grouping as a graph, then walk it with a walker that exposes
the original-code pain (a fan-in at Gold without an execution boundary).
"""

node FlowGroup {
    has title: str = "";
    has layer: str = "";
    has pipeline: str = "";
}

node Pipeline {
    has pipeline_name: str = "";
    has is_dlt_boundary: bool = True;
}

node OutputTable {
    has table_name: str = "";
}

edge LivesIn {
    has folder: str = "";
}

edge Feeds {
    has cardinality: str = "";
}

edge BundledAs {
    has resource_file: str = "";
}

walker Plumber {
    has visited: list[str] = [];

    can start with Root entry {
        print("Plumber walking the repo -> generated layout");
        visit [-->];
    }

    can inspect_flowgroup with FlowGroup entry {
        layer_folder = f"pipelines/{here.layer}/{here.title}.yaml";
        generated_file = f"generated/dev/{here.pipeline}/{here.title}.py";
        bundle_file = f"resources/lhp/{here.pipeline}.pipeline.yml";
        print(
            f"[FG] {here.title}  layer={here.layer}  pipeline={here.pipeline}\n"
            f"     source : {layer_folder}\n"
            f"     gen    : {generated_file}\n"
            f"     bundle : {bundle_file}"
        );
        self.visited.append(here.title);
        visit [-->];
    }

    can inspect_pipeline with Pipeline entry {
        n_groups = 0;
        for fg in [-->] {
            if isinstance(fg, FlowGroup) {
                n_groups = n_groups + 1;
            }
        }
        kind = "DLT" if here.is_dlt_boundary else "logical";
        print(f"[PIPELINE] {here.pipeline_name}  ({kind}, {n_groups} flowgroups)");
        visit [-->];
    }

    can inspect_output with OutputTable entry {
        print(f"[TABLE] {here.table_name}");
    }
}

walker CascadeInvalidator {
    can start with Root entry {
        print("\nCascadeInvalidator: invalidating downstream of a slow Bronze flow");
        visit [-->];
    }

    can fanin with OutputTable entry {
        print(f"  fan-in surface : {here.table_name}");
        visit [-->];
    }
}

with entry {
    bronze_a = FlowGroup(title="parts_bronze_a", layer="01_bronze", pipeline="all");
    bronze_b = FlowGroup(title="parts_bronze_b", layer="01_bronze", pipeline="all");
    silver_a = FlowGroup(title="parts_silver_a", layer="02_silver", pipeline="all");
    silver_b = FlowGroup(title="parts_silver_b", layer="02_silver", pipeline="all");
    gold_join = FlowGroup(title="parts_gold", layer="03_gold", pipeline="all");

    end_to_end = Pipeline(pipeline_name="all", is_dlt_boundary=True);

    table_silver_a = OutputTable(table_name="silver.a_clean");
    table_silver_b = OutputTable(table_name="silver.b_clean");
    table_gold = OutputTable(table_name="gold.ab_join");

    root ++> bronze_a ++> silver_a;
    root ++> bronze_b ++> silver_b;
    root ++> silver_a ++> gold_join;
    root ++> silver_b ++> gold_join;

    bronze_a +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    bronze_b +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    silver_a +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    silver_b +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    gold_join +>:LivesIn(folder="pipelines/03_GOLD"):+> end_to_end;

    bronze_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    bronze_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    gold_join +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;

    silver_a +>:Feeds(cardinality="1:1"):+> table_silver_a;
    silver_b +>:Feeds(cardinality="1:1"):+> table_silver_b;
    table_silver_a +>:Feeds(cardinality="N:1"):+> table_gold;
    table_silver_b +>:Feeds(cardinality="N:1"):+> table_gold;

    plumber = Plumber();
    root spawn plumber;

    print("\n--- flat-folder pain (every FG -> generated/<pipeline>/<title>.py) ---");
    print("Notice: bronze/silver/gold layer info is lost at the generated path.");

    invalidator = CascadeInvalidator();
    root spawn invalidator;
}
