"""Tiny dungeon crawler: rooms chained as nodes, hunter walker counts visited rooms and stops at the treasure vault."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        verdict = "VAULT FOUND!" if here.has_treasure else "empty";
        print(f"[{self.rooms_checked}] {here.name} -> {verdict}");

        if here.has_treasure {
