```jac
"""Reports visibility: published reports are world-readable; unpublished drafts rely on per-instance grants.

The archetype hook returns a READ level when the report is published and
None otherwise, so drafts stay closable but owners can still share them
selectively. The publish walker flips the flag and drops the now-redundant
grant edge.
"""

node Report {
    has title: str = "";
    has published: bool = False;
    has owner: str = "";

    # Archetype hook: returns READ level when published, None otherwise.
    def visibility() -> str | None {
        return "READ" if self.published else None;
    }
}

edge Grant {
    has level: str = "READ";
    has grantee: str = "";
}

walker Publisher {
    can start with Root entry {
        visit [-->];
    }

    can publish with Report entry {
        if not here.published {
            here.published = True;
        }
        # Drop the now-redundant grant edges from this report.
        targets = [here->:Grant:->];
        for g in targets {
            here del ->:Grant:-> g;
        }
        label = "PUBLISHED" if here.published else "DRAFT";
        print(f"[{label}] {here.title} (owner={here.owner})");
        visit [-->];
    }
}

with entry {
    # Two reports under root: one unpublished, one already public.
    draft = Report(title="Q4 Draft", published=False, owner="alice");
    public = Report(title="Annual Review", published=True, owner="bob");
    root ++> draft ++> public;

    # Alice shares the draft selectively with bob before publishing.
    draft +>:Grant(level="READ", grantee="bob"):+> public;

    # Visibility before publishing.
    print(f"draft visibility: {draft.visibility()}");
    print(f"public visibility: {public.visibility()}");

    # Walk the chain and publish.
    root spawn Publisher();

    # Visibility after publishing.
    print(f"draft visibility after: {draft.visibility()}");
    print(f"public visibility after: {public.visibility()}");
}
