```jac
"""No-publish rehearsal oracle: audit reachable workflow authority, compare external public surfaces, and prove predecessor failure blocks publication."""

node ReachableNode {
    def is_blocking() -> bool {
        return False;
    }
}

node WorkflowNode(ReachableNode) {
    has name: str = "";
    has classification: str = "read_only";
    has eligible: bool = True;

    override def is_blocking() -> bool {
        return self.classification == "public_mutation_authorized"
            or self.classification == "not_proven";
    }
}

node PublisherSecret(ReachableNode) {
    has secret_name: str = "";
    has inherited: bool = False;

    override def is_blocking() -> bool {
        return True;
    }
}

node PublicSurface {
    has channel: str = "";
    has before_hash: str = "";
    has after_hash: str = "";
    has observer_status: str = "observed";
}

node RehearsalCandidate {
    has digest: str = "";
    has publish_authorized: bool = False;
    has published_channels: list[str] = [];
    has release_cut: bool = False;
    has predecessor_failed: bool = False;
}

edge Calls { }

edge Observes {
    has phase: str = "baseline";
}

walker AuthorityAuditor {
    has preflight_clear: bool = True;
    has nodes_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print(f"=== Authority preflight ({here.digest}) ===");
        if here.publish_authorized {
            print("FAIL: publish_authorized must be false");
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { disengage; };
    }

    can inspect with WorkflowNode | PublisherSecret entry {
        self.nodes_seen += 1;
        tag = "BLOCK" if here.is_blocking() else "OK";
        print(f"[{tag}] reachable {here}");
        if here.is_blocking() {
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { visit [-->] else { disengage; }; };
    }
}

walker PublicStateGuard {
    has surfaces_stable: bool = True;
    has surfaces_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print("=== Public-state before/after comparison ===");
        visit [->:Observes:->] else { disengage; };
    }

    can compare with PublicSurface entry {
        self.surfaces_checked += 1;
        if here.observer_status == "not_applicable" {
            print(f"SKIP: {here.channel} (topology deferred)");
        } elif here.before_hash != here.after_hash {
            print(f"DRIFT: {here.channel} changed");
            self.surfaces_stable = False;
        } else {
            print(f"STABLE: {here.channel} unchanged ({here.before_hash})");
        }
        visit [->:Observes:->] else { disengage; };
    }
}

walker FailureProof {
    has failure_injected: bool = False;
    has no_publish_dispatch: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        self.failure_injected = here.predecessor_failed;
        print("=== Deliberate predecessor-failure proof ===");
        visit [->:Calls:->] else { disengage; };
    }

    can prove with WorkflowNode entry {
        if here.name == "sbom" and self.failure_injected {
            print("Injected SBOM checksum mismatch — archive ineligible");
            here.eligible = False;
        }
        if here.name == "publish" {
            if here.eligible {
                print("FAIL: publish job became eligible");
                self.no_publish_dispatch = False;
            } else {
                print("PASS: no downstream publish dispatch");
            }
        }
        visit [->:Calls:->] else { disengage; };
    }
}

with entry {
    rehearsal = RehearsalCandidate(
        digest="sha256:deadbeef",
        publish_authorized=False,
        published_channels=[],
        release_cut=False,
        predecessor_failed=True
    );

    lint = WorkflowNode(name="lint", classification="read_only");
    build = WorkflowNode(name="build", classification="artifact_local_write");
    sbom = WorkflowNode(name="sbom", classification="candidate_evidence_write");
    publish = WorkflowNode(
        name="publish",
        classification="public_mutation_unreachable",
        eligible=False
    );

    gh_tags = PublicSurface(
        channel="github_tags", before_hash="v1.0.0", after_hash="v1.0.0"
    );
    crates = PublicSurface(
        channel="crates.io", before_hash="0.42.0", after_hash="0.42.0"
    );
    vsix = PublicSurface(
        channel="open_vsx", before_hash="2.1.0", after_hash="2.1.0"
    );
    brew = PublicSurface(
        channel="homebrew",
        before_hash="",
        after_hash="",
        observer_status="not_applicable"
    );

    root ++> rehearsal;
    rehearsal +>:Calls:+> lint;
    lint +>:Calls:+> build;
    build +>:Calls:+> sbom;
    sbom +>:Calls:+> publish;

    rehearsal +>:Observes(phase="before"):+> gh_tags;
    gh_tags +>:Observes(phase="after"):+> crates;
    crates +>:Observes(phase="after"):+> vsix;
    vsix +>:Observes(phase="after"):+> brew;

    auditor = AuthorityAuditor();
    root spawn auditor;
    guard = PublicStateGuard();
    root spawn guard;
    proof = FailureProof();
    root spawn proof;

    oracle_green = (
        auditor.preflight_clear
        and guard.surfaces_stable
        and proof.no_publish_dispatch
    );
    label = "GREEN" if oracle_green else "RED";
    print(f"=== No-publish oracle verdict: {label} ===");
    print(
        f"authority_nodes={auditor.nodes_seen} "
        f"surfaces={guard.surfaces_checked}"
    );
}
```

```jac
"""Blast-radius review over a connected-type architecture graph.

Models the essential scenario from ggcdevs/pente3D.ai issue #25:
given a type X whose exported contract changed, find the downstream
modules Y/Z that reference it, classify them as pure or glue, and
report which consumers were left untested by the changeset.

The hand-rolled machinery the issue complains about (recursive parent
walks, manual cascade invalidation, per-consumer query loops) is
replaced by a walker over typed edges.
"""

node Module {
    has name: str = "";
    has kind: str = "pure";
    # Pure modules are covered by co-located Y.test.ts; glue modules
    # (render, net, ui) are covered only by Playwright e2e tests.
    has in_changeset: bool = False;
    has tests_touched: bool = False;
}

node Type {
    has name: str = "";
    has contract: str = "";
    # Snapshot of the type's exported signature/fields/methods/exports
    # BEFORE the commit. Diffed against post-commit to decide whether
    # the contract actually changed (the staleness filter from §Design).
    has contract_changed: bool = False;
}

edge References {
    has relation: str = "uses";
    # Creates / param / returns / field / extends / uses.
}

walker BlastRadius {
    has origin: str = "";
    has visited: list[str] = [];
    has pure_uncovered: list[str] = [];
    has glue_uncovered: list[str] = [];

    can start with Type entry {
        # Seed: remember the type whose contract changed.
        self.origin = here.name;
        self.visited = self.visited + [here.name];
        visit [->:References:->];
    }

    can audit with Module entry {
        # The change is "blasting" a module if neither the module nor
        # its tests appear in the changeset. This is the test-delta
        # cross-reference the issue describes.
        covered = here.in_changeset or here.tests_touched;
        if not covered {
            if here.kind == "pure" {
                self.pure_uncovered = self.pure_uncovered + [here.name];
            } else {
                self.glue_uncovered = self.glue_uncovered + [here.name];
            }
        }
        visit [-->];
    }

    can summarize with Root entry {
        # The single exit report: a question the agent must answer,
        # not an assertion the tool can't back up.
        print(
            f"Type {self.origin}'s contract changed; "
            f"consumers with no test delta in this change:"
        );
        has_pure = len(self.pure_uncovered) > 0;
        has_glue = len(self.glue_uncovered) > 0;
        pure_label = "(pure)" if has_pure else "(none)";
        glue_label = "(glue)" if has_glue else "(none)";
        pure_list = ", ".join(self.pure_uncovered) if has_pure else "—";
        glue_list = ", ".join(self.glue_uncovered) if has_glue else "—";
        print(f"  pure: {pure_list} {pure_label}");
        print(f"  glue: {glue_list} {glue_label}");
        if has_pure {
            print(
                "  Confirm each pure consumer is unaffected or covered "
                "by a co-located Y.test.ts delta."
            );
        }
        if has_glue {
            print(
                "  Glue consumers are Playwright-verified, not unit-"
                "tested: confirm an e2e still covers this path."
            );
        }
        disengage;
    }
}

with entry {
    # Architecture: a single type whose contract changed, with
    # downstream pure and glue consumers. Some consumers were also
    # touched in the changeset (so they are NOT flagged).
    scene_sync = Type(name="SceneSync", contract="engine:Scene", contract_changed=True);

    sync_engine = Module(name="SyncEngine", kind="pure", in_changeset=True, tests_touched=True);
    scene_view = Module(name="SceneView", kind="pure");
    render_loop = Module(name="RenderLoop", kind="glue");
    net_io = Module(name="NetIO", kind="glue", in_changeset=True, tests_touched=False);
    ui_panel = Module(name="UIPanel", kind="glue");

    scene_sync +>:References(relation="creates"):+> sync_engine;
    scene_sync +>:References(relation="field"):+> scene_view;
    scene_sync +>:References(relation="param"):+> render_loop;
    scene_sync +>:References(relation="returns"):+> net_io;
    scene_sync +>:References(relation="uses"):+> ui_panel;
    root ++> scene_sync;

    b = BlastRadius();
    scene_sync spawn b;
    root spawn b;
}
```

```jac
"""Agent parent-chain depth with cycle guards.

Models cadis agent_depth: walk ParentOf edges upward, count ancestors,
and halt safely when persisted parent references form a cycle or exceed
a depth cap — matching recover_agent_records cycle detection needs.
"""

node Agent {
    has agent_id: str = "";
    has title: str = "";
    has available: bool = True;
}

edge ParentOf { }

walker AgentDepthWalker {
    has depth: int = 0;
    has visited: list[str] = [];
    has max_depth: int = 100;
    has cycle_detected: bool = False;
    has at_origin: bool = True;

    def seen(agent_id: str) -> bool {
        for vid in self.visited {
            if vid == agent_id {
                return True;
            }
        }
        return False;
    }

    can measure with Agent entry {
        if self.seen(here.agent_id) {
            print(
                f"WARNING: parent-chain cycle detected at agent {here.agent_id}"
            );
            self.cycle_detected = True;
            disengage;
        }
        self.visited.append(here.agent_id);
        if self.at_origin {
            self.at_origin = False;
        } else {
            self.depth += 1;
            if self.depth >= self.max_depth {
                print(
                    f"WARNING: agent_depth capped at {self.max_depth} "
                    f"near agent {here.agent_id}"
                );
                disengage;
            }
        }
        visit [->:ParentOf:->] else { disengage; }
    }
}

walker StateRecoverer {
    has recovered: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        print("recover_agent_records: scanning persisted agents");
        visit [-->];
    }

    can recover with Agent entry {
        probe = AgentDepthWalker(max_depth=100);
        here spawn probe;
        if probe.cycle_detected {
            self.cycle_count += 1;
            print(
                f"WARNING: recover rejected cyclic chain rooted at "
                f"{here.agent_id}"
            );
        } else {
            self.recovered += 1;
            print(
                f"OK: agent {here.agent_id} parent depth = {probe.depth}"
            );
        }
    }
}

with entry {
    alpha = Agent(agent_id="alpha", title="Root Agent");
    beta = Agent(agent_id="beta", title="Mid Agent");
    gamma = Agent(agent_id="gamma", title="Leaf Agent");
    gamma +>:ParentOf:+> beta;
    beta +>:ParentOf:+> alpha;

    agent_a = Agent(agent_id="agent_a", title="Cyclic A");
    agent_b = Agent(agent_id="agent_b", title="Cyclic B");
    agent_a +>:ParentOf:+> agent_b;
    agent_b +>:ParentOf:+> agent_a;

    root ++> gamma;
    root ++> agent_a;

    print("--- agent_depth on healthy parent chain ---");
    healthy = AgentDepthWalker(max_depth=100);
    gamma spawn healthy;
    print(f"agent_depth(gamma) = {healthy.depth}");

    print("--- agent_depth on cyclic chain (must not hang) ---");
    cyclic = AgentDepthWalker(max_depth=100);
    agent_a spawn cyclic;
    halted = "yes" if cyclic.cycle_detected else "no";
    print(
        f"agent_depth(agent_a) depth={cyclic.depth}, "
        f"cycle_halted={halted}"
    );

    print("--- recover_agent_records sweep ---");
    root spawn StateRecoverer();
}
