```jac
"""Bug tracker: file tickets from a project and capture each fresh ticket."""

node Ticket {
    has title: str = "";
    has priority: int = 0;
}

node Project {
    has project_name: str = "";

    def file_ticket(title: str, priority: int) -> Ticket {
        fresh = self +>:Filed:+> Ticket(title=title, priority=priority);
        status = "FILED" if fresh else "MISS";
        print(f"[{status}] project={self.project_name} title={fresh.title} priority={fresh.priority}");
        return fresh;
    }
}

edge Filed { has filed_at: str = ""; }

walker Triager {
    has triager_name: str = "anon";

    can start with Root entry {
        print(f"Triager {self.triager_name} working the queue");
        visit [-->];
    }

    can triage with Project entry {
        visit [-->];
    }

    can log with Ticket entry {
        print(f"  seen ticket: {here.title} (p={here.priority})");
        visit [-->];
    }
}

with entry {
    webapp_node = Project(project_name="WebApp");
    mobile_node = Project(project_name="Mobile");
    root ++> webapp_node ++> mobile_node;
    webapp_node.file_ticket("Login broken", 1);
    webapp_node.file_ticket("Checkout 500", 2);
    root spawn Triager(triager_name="Alex");
}
