```jac
"""Mutual friendships between houses with bidirectional buddy edges.

Models houses as graph nodes and connects pairs with buddy edges that
point both ways (created in a single statement). Two greeter walkers are
spawned, one per end of a buddy link, and each must reach the other
using only forward traversal. An explicit guard set prevents the
walkers from oscillating back and forth forever.
"""

node House {
    has name: str = "";
    has visited: set[str] = set();
}

edge Buddy {
    has since: int = 0;
}

walker Greeter {
    has house_name: str = "";
    has target: str = "";
    has reached: bool = False;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can travel with House entry {
        # Mark this house as seen so we never bounce back.
        here.visited.add(self.house_name);
        self.log.append(f"greeter from {self.house_name} at {here.name}");

        if here.name == self.target {
            self.reached = True;
            print(f"[{self.house_name}] reached buddy {self.target} -> {self.log}");
            disengage;
        }

        # Only walk buddy edges; skip houses already visited on this route.
        buddy = [here ->:Buddy:->];
        if buddy and buddy[0].name not in here.visited {
            visit buddy;
        } else {
            print(f"[{self.house_name}] no fresh buddy edge from {here.name}");
            disengage;
        }
    }
}

with entry {
    # Two houses connected by a buddy edge that points BOTH ways
    # in a single statement.
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since=2021):+> bob;
    bob +>:Buddy(since=2021):+> alice;
    root ++> alice ++> bob;

    # Spawn one greeter at each end of the buddy link.
    g_alice = Greeter(house_name="Alice", target="Bob");
    g_bob = Greeter(house_name="Bob", target="Alice");

    alice spawn g_alice;
    bob spawn g_bob;
}
