"""Restaurant kitchen line health inspection.

Two walkers sweep the same line of stations independently: one flags any
station above 40 C as a violation, the other logs every station visit.
Spawning them in sequence on root exercises both checks at every station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker TempAuditor {
    has threshold: float = 40.0;
    has violations: int = 0;

    can start with Root entry {
        print(f"TempAuditor sweeping (threshold {self.threshold} C)");
        visit [-->];
    }

    can check with Station entry {
        if here.celsius > self.threshold {
            self.violations += 1;
            print(f"  [VIOLATION] {here.name} at {here.celsius} C (> {self.threshold} C)");
        } else {
            print(f"  [ok] {here.name} at {here.celsius} C");
        }
        visit [-->];
    }
}

walker VisitLogger {
    has log: list[str] = [];

    can start with Root entry {
        print("VisitLogger tracking every station pass");
        visit [-->];
    }

    can record with Station entry {
        self.log.append(here.name);
        print(f"  logged visit to {here.name}");
        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", celsius=185.0);
    fryer = Station(name="Fryer", celsius=165.0);
    cold_prep = Station(name="Cold Prep", celsius=4.0);
    pantry = Station(name="Pantry", celsius=22.0);
    root ++> grill ++> fryer ++> cold_prep ++> pantry;

    auditor = TempAuditor(threshold=40.0);
    root spawn auditor;
    print(f"TempAuditor total violations: {auditor.violations}");

    print("---");

    logger = VisitLogger();
    root spawn logger;
    print(f"VisitLogger visited stations in order: {logger.log}");
}
