```jac
"""Daily student attendance: register unit, calendar, and mark traversal.

Models the essential graph machinery from sis-v2 wayfinder ticket #111:
class register units, attendance marks keyed on (student, date), and a
calendar that voids closures. A walker walks the day's register,
applies the closure rule, and computes a per-class summary while
honouring the locked decisions (manual entry, late counts as present,
edit window, calendar is load-bearing).
"""

node Campus {
    has name: str = "";
}

node StandardLevel {
    has name: str = "";
}

node AcademicYear {
    has label: str = "";
}

edge BelongsTo {}

node Register {
    has level_name: str = "";
    has campus_name: str = "";
    has year_label: str = "";
    # Whether the class unit has any marks yet — used by the closure
    # confirmation rule.
    has has_marks: bool = False;
}

edge Enrolled {}

node Student {
    has name: str = "";
}

node AttendanceMark {
    has status: str = "";
    has marked_by: str = "";
    # Status as a judgement: "present" / "absent" / "late".
    has counts_as_present: bool = True;
    has date: str = "";
}

edge MarkedOn {
    has date: str = "";
}

node CalendarDay {
    has date: str = "";
    has is_school_day: bool = True;
    # Closed days (hartal/flood/unrest) void the date entirely.
    has is_closed: bool = False;
}

edge Calendar {}

walker AttendanceAuditor {
    has target_date: str = "";
    has present_total: int = 0;
    has absent_total: int = 0;
    has unmarked_school_days: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_register with Register entry {
        if here.has_marks {
            print(f"register {here.level_name}/{here.campus_name}/{here.year_label}: scanning marks");
        } else {
            print(f"register {here.level_name}/{here.campus_name}/{here.year_label}: no marks yet");
        }
        visit [-->];
    }

    can audit_student with Student entry {
        visit [-->];
    }

    can tally_mark with AttendanceMark entry {
        # Locked #111: late counts as present for the percentage.
        if here.counts_as_present {
            self.present_total += 1;
        } else {
            self.absent_total += 1;
        }
        # No visit: marks are leaves on the (student, date) edge.
    }

    can audit_calendar with CalendarDay entry {
        # Closed days void the date entirely — they are excluded from the
        # denominator. Unmarked school days are surfaced for chase.
        if here.is_closed {
            print(f"calendar {here.date}: CLOSED (voided, not in figure)");
        } elif not here.is_school_day {
            print(f"calendar {here.date}: non-school day");
        } else {
            self.unmarked_school_days.append(here.date);
            print(f"calendar {here.date}: unmarked school day (chase)");
        }
        visit [-->];
    }
}

with entry {
    # Campus + level topology.
    dhaka = Campus(name="Dhaka");
    chittagong = Campus(name="Chittagong");
    root ++> dhaka ++> chittagong;

    primary = StandardLevel(name="Grade 3");
    root ++> primary;

    # Academic year envelope.
    year = AcademicYear(label="2026");
    root ++> year;

    # Register units = (standardLevel, academicYear, campus). No section,
    # per ticket #112.
