```jac
"""Flight network: ticket prices on FlightLeg edges; Scout gathers fares to normalize each leg against the peak."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has label: str = "";

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }
}

walker Scout {
    can start with Root entry {
        visit [-->];
    }

    can scan with Airport entry {
        for leg in [edge here ->:FlightLeg:->] {
            report leg.price;
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    sfo = Airport(code="SFO");
    root ++> jfk;

    leg_jfk_lax = FlightLeg(price=450.0, label="JFK-LAX");
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_sfo = FlightLeg(price=320.0, label="LAX-SFO");
    lax +>:leg_lax_sfo:+> sfo;

    leg_jfk_sfo = FlightLeg(price=380.0, label="JFK-SFO");
    jfk +>:leg_jfk_sfo:+> sfo;

    scout = Scout();
    root spawn scout;

    max_fare = 0.0;
    for fare in scout.reports {
