"""Rollup audit hardening demo.

Models the tour-key-missing drift scenario from issue #298: a rollup pipeline
walks shows -> tours via a typed edge, and when the calendar snapshot has no
tour mapping for a given show date the audit walker records the drift instead
of silently skipping it.
"""

node Show {
    has title: str = "";
    has show_date: str = "";
}

node Tour {
    has tour_key: str = "";
    has season_label: str = "";
}

node RollupAudit {
    has show_date: str = "";
    has tour_key: str = "";
    has tour_key_missing: bool = False;
    has severity: str = "info";
    has note: str = "";
}

edge ScheduledOn {
    has recorded_at: str = "";
}

walker RollupAuditor {
    has tour_lookup: dict = {};
    has missing_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Show entry {
        mapped_key = self.tour_lookup.get(here.show_date);
        if mapped_key is None {
            self.missing_count += 1;
            audit = RollupAudit(
                show_date=here.show_date,
                tour_key="",
                tour_key_missing=True,
                severity="error",
                note=f"tourKey missing for showDate={here.show_date}"
            );
