```javascript
'use strict';

/**
 * xsd-parser.js
 *
 * Parses an XSD file into a raw, normalised JavaScript object tree using
 * fast-xml-parser.  All xs: / xsd: namespace prefixes are stripped so the
 * rest of the pipeline works with plain tag names.
 */

const fs   = require('fs');
const path = require('path');
const { XMLParser } = require('fast-xml-parser');

// ─── parser configuration ────────────────────────────────────────────────────

const PARSER_OPTIONS = {
  ignoreAttributes   : false,   // we need @_name, @_type, @_use, etc.
  attributeNamePrefix: '@_',    // all attributes are prefixed @_ in the JS obj
  isArray: (tagName) => {
    // These XSD constructs always come back as arrays, even when there is
    // only one occurrence, so downstream code can always iterate safely.
    const alwaysArray = new Set([
      'element', 'attribute', 'complexType', 'simpleType',
      'sequence', 'choice', 'all', 'group', 'attributeGroup',
      'enumeration', 'extension', 'restriction',
      'complexContent', 'simpleContent',   // ← must be arrays so _dig works
      'annotation', 'documentation',
      'import', 'include',
    ]);
    return alwaysArray.has(stripNs(tagName));
  },
  parseAttributeValue: false,   // keep all attribute values as strings
  trimValues         : true,
  processEntities    : false,
};

// ─── helpers ─────────────────────────────────────────────────────────────────

/**
 * Strip an XML namespace prefix ("xs:string" → "string").
 * Works for both tag names and type references.
 */
function stripNs(name) {
  if (!name || typeof name !== 'string') return name;
  const idx = name.indexOf(':');
  return idx === -1 ? name : name.slice(idx + 1);
}

/**
 * Recursively walk every key in an object and strip namespace prefixes from
 * both key names and string values that look like QNames.
 */
function deepStripNs(node) {
  if (Array.isArray(node)) return node.map(deepStripNs);
  if (node && typeof node === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(node)) {
      const cleanKey = k.startsWith('@_') ? '@_' + stripNs(k.slice(2)) : stripNs(k);
      // For attribute values that reference types, strip their ns prefix too
      const cleanVal =
        typeof v === 'string' ? stripNs(v) : deepStripNs(v);
      out[cleanKey] = cleanVal;
    }
    return out;
  }
  return node;
}

// ─── public API ──────────────────────────────────────────────────────────────

/**
 * Parse an XSD file.
 *
 * @param {string} filePath  Absolute or relative path to the .xsd file.
 * @returns {object}         Normalised JS object (namespace-stripped).
 */
function parseXSD(filePath) {
  const absPath = path.resolve(filePath);
  if (!fs.existsSync(absPath)) {
    throw new Error(`XSD file not found: ${absPath}`);
  }

  const xml    = fs.readFileSync(absPath, 'utf8');
  const parser = new XMLParser(PARSER_OPTIONS);
  const raw    = parser.parse(xml);

  // The top-level key is always "schema" (after ns stripping)
  const nsKey  = Object.keys(raw).find(k => stripNs(k) === 'schema');
  if (!nsKey) throw new Error('No <xs:schema> root element found');

  return deepStripNs(raw[nsKey]);
}

module.exports = { parseXSD, stripNs };
