Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""XSD schema graph: parse a schema into typed nodes and walk it with a
resolver walker that strips namespace prefixes, builds a type-name index,
and detects cycles in the type-reference graph.

The hand-rolled JS code uses id-keyed maps, manual recursion through an
untyped object tree, and ad-hoc cycle checks. Here we lift those concerns
into native Jac archetypes: Schema as the root container, TypeDef nodes
for named complexType/simpleType definitions, Group nodes for xs:group /
xs:attributeGroup, and Element nodes that *reference* types by a typed
edge. A Resolver walker traverses the reference edges to build a name
index and reports any cycles it finds along the way.
"""

# A common base so TypeDef and Group share a `declared_name` field the
# walker can read from a union trigger without per-type branching.
node NamedDecl {
    has declared_name: str = "";
}

node Schema {
    has schema_name: str = "";
    has target_namespace: str = "";
}

node TypeDef(NamedDecl) {
    has kind: str = "";         # "complexType" or "simpleType"
    has derived_from: str = ""; # base type name, possibly empty
}

node Group(NamedDecl) {
    has group_kind: str = "";   # "group" or "attributeGroup"
}

node Element {
    has element_name: str = "";
    has type_ref: str = "";     # QName reference, possibly empty
}

# ── typed edges ──────────────────────────────────────────────────────────────
# An element references a named type (or group) via these edges.
edge ElementTypeRef { has ref_kind: str = "type"; }    # element -> TypeDef
edge ElementGroupRef { has ref_kind: str = "group"; }  # element -> Group
# A type extends/restricts another type via inheritance.
edge TypeDerivation { has base_kind: str = "extension"; }

# ── helpers ──────────────────────────────────────────────────────────────────

# Strip an XML namespace prefix: "xs:string" -> "string".
def strip_ns(name: str) -> str {
    if not name {
        return name;
    }
    idx = name.find(":");
    return name if idx == -1 else name[idx + 1:];
}

# A small compat façade: takes a schema node and strips ns prefixes
# from its string fields, mirroring deepStripNs from the source module.
def deep_strip_ns_on(schema: Schema) -> None {
    schema.schema_name = strip_ns(schema.schema_name);
    schema.target_namespace = strip_ns(schema.target_namespace);
}

# ── walkers ──────────────────────────────────────────────────────────────────

walker Resolver {
    has visited_names: list[str] = [];
    has index: dict[str, str] = {};   # name -> kind label
    has cycle_found: list[str] = [];

    can start with Root entry {
        # From the schema root, fan out to every direct child node.
        visit [-->];
    }

    can index_schema with Schema entry {
        deep_strip_ns_on(here);
        print(f"[schema] {here.schema_name} ns={here.target_namespace}");
        visit [-->];
    }

    # Union trigger: one ability serves TypeDef and Group alike, since
    # both inherit `declared_name` from NamedDecl and register themselves
    # in the name index under the same rule.
    can register with TypeDef | Group entry {
        clean_name = strip_ns(here.declared_name);
        here.declared_name = clean_name;
        kind_label = "type" if isinstance(here, TypeDef) else "group";
        self.index[clean_name] = kind_label;
        print(f"  + index[{clean_name}] = {kind_label}");
        # Walk any outgoing references / derivations.
        visit [->:ElementTypeRef:->];
        visit [->:ElementGroupRef:->];
        visit [->:TypeDerivation:->];
    }

    # Elements only contribute a reference; the actual cycle detection
    # happens when we follow those references back into named types.
    can follow_element with Element entry {
        clean_ref = strip_ns(here.type_ref);
        here.type_ref = clean_ref;
        if clean_ref and clean_ref in self.index {
            print(f"  -> element {here.element_name} refs {clean_ref} (resolved)");
        } elif clean_ref {
            print(f"  -> element {here.element_name} refs {clean_ref} (UNRESOLVED)");
        }
        visit [->:ElementTypeRef:->];
        visit [->:ElementGroupRef:->];
    }

    # Two-phase cycle probe: when we re-enter a type we've already seen
    # via a derivation chain, record the cycle rather than recurse forever.
    can detect_cycle with TypeDef | Group entry {
        here_name = strip_ns(here.declared_name);
        if here_name in self.visited_names {
            cycle_label = f"{here_name} already visited";
            self.cycle_found.append(cycle_label);
            print(f"  ! cycle detected: {cycle_label}");
            disengage;
        }
        self.visited_names.append(here_name);
        visit [->:TypeDerivation:->];
    }
}

# ── demo wiring ──────────────────────────────────────────────────────────────
with entry {
    schema = Schema(schema_name="xs:orderSchema", target_namespace="xs:urn:example");

    # Named complexType: PartInfo, with an extension base PartBase.
    part_info = TypeDef(declared_name="xs:PartInfo", kind="complexType", derived_from="xs:PartBase");
    part_base = TypeDef(declared_name="xs:PartBase", kind="complexType");

    # SimpleType with an enumeration (enumeration is just a kind tag here).
    code_type = TypeDef(declared_name="xs:CodeType", kind="simpleType");

    # A reusable attribute group.
    id_group = Group(declared_name="xs:CommonIdAttrs", group_kind="attributeGroup");

    # Elements that reference those types.
    part_el = Element(element_name="xs:part", type_ref="xs:PartInfo");
    code_el = Element(element_name="xs:code", type_ref="xs:CodeType");

    # Wire it all up.
    schema ++> part_info;
    schema ++> part_base;
    schema ++> code_type;
    schema ++> id_group;
    schema ++> part_el;
    schema ++> code_el;

    # Typed references: element -> type, element -> group, type -> base.
    part_el +>:ElementTypeRef:+> part_info;
    code_el +>:ElementTypeRef:+> code_type;
    part_info +>:TypeDerivation(base_kind="extension"):+> part_base;
    # Intentional cycle: PartBase derives from PartInfo to demo detection.
    part_base +>:TypeDerivation(base_kind="restriction"):+> part_info;

    resolver = Resolver();
    print("=== Resolver walk ===");
    resolver spawn schema;

    print("\n=== Summary ===");
    print(f"indexed {len(resolver.index)} names");
    print(f"cycles detected: {len(resolver.cycle_found)}");
}
```

```jac
"""CAM recompute cascade model.

Models the FreeCAD CAM workbench pain point: opening a Job task panel,
selecting the General tab, or editing any data-panel parameter kicks
off a Document.recompute() that recursively walks the dependency graph
of CAM operations and re-executes every Operation downstream, even when
no upstream value actually changed.

The dependency graph (Job -> ToolControllers -> Operations -> Dressups)
is lifted into typed edges and a walker that performs the cascade.
A second walker models the proposed "expensive recompute warning" with
a configurable budget, mirroring the issue's suggestion of a 1-second
threshold.
"""

# ---------- entities ----------

node Document {
    has name: str = "";
    has global_recompute: bool = True;
}

node Job {
    has label: str = "";
    has dirty: bool = False;
}

node ToolController {
    has label: str = "";
    has dirty: bool = False;
}

node Operation {
    has label: str = "";
    has dirty: bool = False;
    has last_exec_ms: int = 0;
}

node Dressup {
    has label: str = "";
    has dirty: bool = False;
}

# ---------- relationships (typed edges carry meaning) ----------

edge Owns { }

# ---------- walker: cascade recompute (the complaint) ----------

walker RecomputeCascade {
    has visited: list = [];
    has recomputed_count: int = 0;
    has skipped_count: int = 0;

    can begin with Root entry {
        print("=== Cascade recompute over CAM dependency graph ===");
        visit [-->];
    }

    can visit_doc with Document entry {
        if not here.global_recompute {
            print(f"[skip-doc] {here.name}: document-level recompute disabled");
            disengage;
        }
        print(f"[doc] {here.name}: starting recompute");
        visit [->:Owns:->];
    }

    can visit_job with Job entry {
        self.visited.append(here.label);
        if here.dirty {
            print(f"[recompute] Job '{here.label}' (dirty)");
            self.recomputed_count += 1;
            here.dirty = False;
        } else {
            print(f"[skip] Job '{here.label}' (clean)");
            self.skipped_count += 1;
        }
        visit [->:Owns:->];
    }

    can visit_tool with ToolController entry {
        if here.dirty {
            print(f"[recompute] ToolController '{here.label}' (dirty)");
            self.recomputed_count += 1;
            here.dirty = False;
        } else {
            print(f"[skip] ToolController '{here.label}' (clean)");
            self.skipped_count += 1;
        }
        visit [->:Owns:->];
    }

    can visit_op with Operation entry {
        # The expensive operation that prompted the issue. We still
        # simulate work even when 'dirty' is False if last_exec_ms>0,
        # because in the original bug the recompute fires regardless.
        if here.dirty or self.visited.__len__() == 1 {
            print(f"[recompute] Operation '{here.label}' "
                  f"(last took {here.last_exec_ms} ms)");
            self.recomputed_count += 1;
            here.dirty = False;
        } else {
            print(f"[skip] Operation '{here.label}' (clean, "
                  f"{here.last_exec_ms} ms saved)");
            self.skipped_count += 1;
        }
        visit [->:Owns:->];
    }

    can visit_dressup with Dressup entry {
        if here.dirty {
            print(f"[recompute] Dressup '{here.label}' (dirty)");
            self.recomputed_count += 1;
            here.dirty = False;
        } else {
            print(f"[skip] Dressup '{here.label}' (clean)");
            self.skipped_count += 1;
        }
        visit [->:Owns:->];
    }
}

# ---------- walker: budget-guarded recompute (the proposal) ----------

walker BudgetedRecompute {
    has budget_ms: int = 1000;
    has elapsed_ms: int = 0;
    has expensive_ops: list = [];
    has cancelled: bool = False;

    can begin with Root entry {
        print(f"=== Budgeted recompute, budget = {self.budget_ms} ms ===");
        visit [-->];
    }

    can visit_doc with Document entry {
        if not here.global_recompute {
            print("[skip-doc] recompute globally disabled");
            disengage;
        }
        visit [->:Owns:->];
    }

    can visit_job with Job entry {
        # Jobs are cheap; never counted toward the budget.
        print(f"[job] {here.label}");
        visit [->:Owns:->];
    }

    can visit_tool with ToolController entry {
        print(f"[tool] {here.label}");
        visit [->:Owns:->];
    }

    can visit_op with Operation entry {
        projected = self.elapsed_ms + here.last_exec_ms;
        if projected > self.budget_ms and not self.cancelled {
            self.cancelled = True;
            self.expensive_ops.append(here.label);
            print(f"[CANCEL] '{here.label}' would push elapsed to "
                  f"{projected} ms (> budget {self.budget_ms}); "
                  f"stopping cascade");
            disengage;
        }
        self.elapsed_ms = projected;
        print(f"[run] '{here.label}' took {here.last_exec_ms} ms "
              f"(cumulative {self.elapsed_ms} ms)");
        visit [->:Owns:->];
    }

    can visit_dressup with Dressup entry {
        print(f"[dressup] {here.label}");
        visit [->:Owns:->];
    }
}

# ---------- demo wiring ----------

with entry {
    doc = Document(name="CAMProject");
    job = Job(label="Job-A");
    tc1 = ToolController(label="TC-1");
    tc2 = ToolController(label="TC-2");
    op_profile = Operation(label="Profile", last_exec_ms=400);
    op_pocket = Operation(label="Pocket", last_exec_ms=2500);
    op_drill = Operation(label="Drill", last_exec_ms=800);
    dressup_lead = Dressup(label="LeadInOut");

    # Build a Job -> ToolControllers -> Operations -> Dressup chain with
    # typed Owns edges. Only the profile operation is dirty; the rest
    # are clean, mirroring "nothing has actually changed in the data
    # panel" even though the cascade fires anyway.
    doc +>:Owns:+> job;
    job +>:Owns:+> tc1;
    job +>:Owns:+> tc2;
    tc1 +>:Owns:+> op_profile;
    tc1 +>:Owns:+> op_pocket;
    tc2 +>:Owns:+> op_drill;
    op_profile +>:Owns:+> dressup_lead;

    op_profile.dirty = True;
    op_pocket.dirty = True;

    print("--- Scenario 1: existing behavior (cascade fires regardless) ---");
    root spawn RecomputeCascade();
    print(f"  -> recomputed={RecomputeCascade().recomputed_count} "
          f"placeholders visited={len(RecomputeCascade().visited)}");

    print("\n--- Scenario 2: budget-guarded recompute (issue proposal) ---");
    root spawn BudgetedRecompute(budget_ms=1000);

    print("\n--- Scenario 3: document-level recompute disabled ---");
    doc.global_recompute = False;
    root spawn RecomputeCascade();
}
```

```jac
"""Cycle detection in a software build dependency graph.

Modules depend on each other through DependsOn edges. A detector walker
recurses by spawning itself on each dependency: every spawn instance owns
one stack frame, so a module that is mid-exploration ("visiting") seen
again from below is a genuine back edge, and the trail carried down the
spawn chain reconstructs the cycle.
"""

node Module {
    has name: str;
    has status: str = "new";  # new | visiting | done
}

edge DependsOn: Module --> Module {}

walker CycleDetector {
    has trail: list[str] = [];
    has found: str = "";

    can explore with Module entry {
        if here.status == "done" {
            skip;  # whole subtree proven acyclic
        }
        if here.status == "visiting" {
            # Back edge: everything from its first occurrence is the cycle.
            idx = self.trail.index(here.name);
            self.found = " -> ".join(self.trail[idx:] + [here.name]);
            disengage;
        }

        here.status = "visiting";
        next_trail = self.trail + [here.name];
        for dep in [->:DependsOn:->] {
            sub = dep spawn CycleDetector(trail=next_trail);
            if sub.found != "" {
                self.found = sub.found;
                disengage;
            }
        }
        here.status = "done";
    }
}

with entry {

    # Reset leftovers from any previous run of this demo.
    for stale_node in [root -->][?:Module] {
        del stale_node;
    }
    linker = Module(name="linker");
    parser = Module(name="parser");
    lexer = Module(name="lexer");
    utils = Module(name="utils");
    codegen = Module(name="codegen");

    # Acyclic core: linker -> parser -> lexer -> utils, linker -> codegen
    linker +>: DependsOn() :+> parser;
    parser +>: DependsOn() :+> lexer;
    lexer +>: DependsOn() :+> utils;
    linker +>: DependsOn() :+> codegen;
    codegen +>: DependsOn() :+> utils;
    # Introduce a real cycle: parser's build step depends on codegen,
    # which already depends on parser.
    codegen +>: DependsOn() :+> parser;
    parser +>: DependsOn() :+> codegen;

    result = linker spawn CycleDetector();
    if result.found {
        print(f"CYCLE DETECTED: {result.found}");
    } else {
        print("Dependency graph is clean -- no cycles.");
    }
}
