```jac
"""Restaurant kitchen line health inspection.

Walk the line (grill, fryer, cold prep) and run two checks at every
station: a temperature check that flags anything above 40 C as a
violation, and a visit-log check that records every station entered.
Both checks fire at every station via union triggers on the walker.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker Inspector {
    has violations: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Beginning kitchen line inspection");
        visit [-->];
    }

    # Temperature check: fires for every Station kind (union trigger).
    can check_temp with Station entry {
        flagged = here.celsius > 40.0;
        if flagged {
            self.violations += 1;
            print(f"  [VIOLATION] {here.name} at {here.celsius} C exceeds 40 C");
        } else {
            print(f"  [OK] {here.name} at {here.celsius} C");
        }
    }

    # Visit log: also fires for every Station (separate union ability).
    can record_visit with Station entry {
        self.log.append(here.name);
        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Station(name="Grill", celsius=220.0);
    fryer = Station(name="Fryer", celsius=180.0);
    cold_prep = Station(name="Cold Prep", celsius=4.0);
    prep_table = Station(name="Prep Table", celsius=22.0);
    root ++> grill ++> fryer ++> cold_prep ++> prep_table;

    inspector = Inspector();
    root spawn inspector;

    print("---");
    print(f"Total violations: {inspector.violations}");
    print(f"Visit log: {inspector.log}");
}
