```jac
"""Reconciliation, repair, and reassessment of a changed subject.

Models issue #32's core scenario natively:
  - A subject (Release) carries a binding to an environment.
  - An unresolved condition (failed evaluation) triggers reconciliation.
  - Reconciliation produces a record-only path OR routes to repair.
  - Repair re-enters Draft -> new Release -> Bind -> Reassess.
  - Reassessment is preregistered and bound to the exact subject.
"""

# ---------- Entity archetypes ----------

node Subject {
    has subject_id: str = "";
    has material_change: bool = False;
    has evidence_intact: bool = True;
}

node Draft {
    has draft_id: str = "";
    has rationale: str = "";
    has residual_uncertainty: str = "";
}

node Release {
    has release_id: str = "";
    has version: int = 0;
    has predecessor_evidence: str = "";
}

node Binding {
    has binding_id: str = "";
    has scope: str = "";
    has environment: str = "";
}

node Reassessment {
    has assessment_id: str = "";
    has preregistered: bool = True;
    has result: str = "PENDING";
    has rationale: str = "";
}

# ---------- Typed edges (relationships carry meaning) ----------

edge ProducedBy {
    has attempt: int = 0;
}

edge Binds {
    has consequence_class: str = "low";
}

edge Triggers {
    has condition: str = "";
}

edge Reenters {
    has directive: str = "";
}

# ---------- Walker: reconciles, repairs, reassesses ----------

walker ReconciliationOfficer {
    has decisions: list[str] = [];
    has outcome: dict = {};

    can begin with Root entry {
        print("Reconciliation officer: scanning unresolved conditions");
        visit [->:Triggers:->];
    }

    can inspect_subject with Subject entry {
        label = "RECONCILE_RECORD_ONLY" if (not here.material_change and here.evidence_intact)
                else "REPAIR_REQUIRED";
        print(f"[Subject {here.subject_id}] -> {label}");
        self.decisions.append(label);
        if label == "REPAIR_REQUIRED" {
            visit [-->];
        } else {
            visit [-->] else { disengage; }
        }
    }

    can route_repair with Draft entry {
        record = f"Draft {here.draft_id} rationale='{here.rationale}' "
                 f"residual='{here.residual_uncertainty}'";
        self.decisions.append(record);
        print(f"  repair lineage: {record}");
        visit [->:ProducedBy:->];
    }

    can propagate_to_release with Release entry {
        print(f"  new Release v{here.version} ({here.release_id}) "
              f"inherits predecessor evidence: '{here.predecessor_evidence}'");
        self.outcome["new_release"] = here.release_id;
        visit [->:Binds:->];
    }

    can rebind with Binding entry {
        print(f"  re-binding {here.binding_id} scope={here.scope} env={here.environment}");
        self.outcome["new_binding"] = here.binding_id;
        visit [->:Reenters:->];
    }

    can reassess with Reassessment entry {
        if not here.preregistered {
            verdict = "FAIL_NOT_PREREGISTERED";
        } elif not (self.outcome.get("new_release") and self.outcome.get("new_binding")) {
            verdict = "FAIL_MISSING_SUBJECT";
        } else {
            verdict = "PASS_BOUNDED_CLAIM";
        }
        here.result = verdict;
        self.decisions.append(f"reassessment={verdict}");
        print(f"  reassessment {here.assessment_id} -> {verdict}");
        visit [-->] else { disengage; }
    }
}

# ---------- Walker: cascade-invalidate stale evidence on material change ----------

walker EvidenceInvalidator {
    can begin with Root entry {
        visit [->:ProducedBy:->];
    }

    can invalidate with Release entry {
        if here.predecessor_evidence == "" {
            print(f"  Release {here.release_id}: no evidence to preserve (silent pass guard)");
        } else {
            print(f"  Release {here.release_id}: predecessor evidence preserved -> '{here.predecessor_evidence}'");
        }
        visit [-->] else { disengage; }
    }
}

# ---------- Demonstration wiring ----------

with entry {
    # A subject with material change requiring repair.
    changed_subject = Subject(
        subject_id="S-001",
        material_change=True,
        evidence_intact=True
    );
    root +>:Triggers(condition="failed_evaluation"):+> changed_subject;

    # Repair lineage: Draft -> Release -> Binding -> Reassessment
    repair_draft = Draft(
        draft_id="D-32",
        rationale="dependency failure resolved",
        residual_uncertainty="none"
    );
    changed_subject ++> repair_draft;

    new_release = Release(
        release_id="R-1.1",
        version=2,
        predecessor_evidence="R-1.0 failed at eval step 3"
    );
    repair_draft +>:ProducedBy(attempt=1):+> new_release;

    new_binding = Binding(
        binding_id="B-env-prod",
        scope="production",
        environment="prod-east"
    );
    new_release +>:Binds(consequence_class="high"):+> new_binding;

    preregistered_check = Reassessment(
        assessment_id="A-32",
        preregistered=True,
        result="PENDING",
        rationale="bound to release R-1.1 + binding B-env-prod"
    );
    new_binding +>:Reenters(directive="reassess_after_repair"):+> preregistered_check;

    # A second subject: no material change, record-only path.
    quiet_subject = Subject(
        subject_id="S-002",
        material_change=False,
        evidence_intact=True
    );
    root +>:Triggers(condition="interruption"):+> quiet_subject;

    print("=== Reconciliation run ===");
    officer = ReconciliationOfficer();
    root spawn officer;
    print(f"decisions: {officer.decisions}");
    print(f"outcome: {officer.outcome}");

    print("\n=== Evidence invalidation probe ===");
    inv = EvidenceInvalidator();
    root spawn inv;
}
```

