```jac
"""Accessibility audit walk across mobile screens: model screens as nodes,
wire accessibility annotations (VoiceOver labels, contrast checks, reduced-motion
honored, RTL support) as typed edges, then walk the screen graph with an auditor
walker that reports per-screen audit results."""

node Screen {
    has name: str = "";
    has wcag_aa_contrast: bool = False;
    has voiceover_labels: bool = False;
    has reduced_motion_honored: bool = False;
    has rtl_layout: bool = False;
}

edge NavigatesTo { has transition: str = "push"; }
edge Contains { }

walker AccessibilityAuditor {
    has visited: list[str] = [];
    has failures: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print("=== Accessibility Audit (WCAG AA + a11y checks) ===");
        visit [-->];
    }

    can audit with Screen entry {
        # Cycle policy: explicit guard set since walkers don't dedupe.
        already_seen = False;
        for v in self.visited {
            if v == here.name {
                already_seen = True;
                break;
            }
        }
        if already_seen {
            visit [-->] else { disengage; };
            return;
        }
        self.visited.append(here.name);

        print(f"\n[Screen] {here.name}");
        checks = [
            ("WCAG AA contrast", here.wcag_aa_contrast),
            ("VoiceOver labels", here.voiceover_labels),
            ("Reduced-motion honored", here.reduced_motion_honored),
            ("RTL layout", here.rtl_layout)
        ];
        for (label, passed) in checks {
            verdict = "PASS" if passed else "FAIL";
            print(f"  - {label}: {verdict}");
            if not passed {
                self.failures.append(f"{here.name}: {label}");
            }
        }
        visit [-->] else { disengage; };
    }
}

walker AuditReport {
    can start with Root entry {
        print("\n=== Audit Summary ===");
        print("Total screens visited: see AccessibilityAuditor.visited");
        print("Failures collected: see AccessibilityAuditor.failures");
        visit [-->] else { disengage; };
    }
}

with entry {
    # Build a small screen graph: onboarding flow + main tabs.
    welcome = Screen(
