```jac
"""Duplicate file detector: recursively scan directories, group files by content hash, and report savings."""

node Directory {
    has name: str = "";
    has path: str = "";
    has ignored: bool = False;
}

node File {
    has path: str = "";
    has content_hash: str = "";
    has size_bytes: int = 0;
}

edge Contains { }

walker DuplicateScanner {
    has files_scanned: int = 0;
    has savings_bytes: int = 0;
    has paths: list[str] = [];
    has hashes: list[str] = [];
    has sizes: list[int] = [];

    can start with Root entry {
        print("Scanning directory tree for duplicate content...");
        visit [->:Contains:->] else { disengage; };
    }

    can walk_directory with Directory entry {
        if here.ignored {
            print(f"Skipping ignored directory: {here.path}");
        } else {
            visit [->:Contains:->] else { disengage; };
        }
    }

    can hash_file with File entry {
        self.files_scanned += 1;
        self.paths.append(here.path);
        self.hashes.append(here.content_hash);
        self.sizes.append(here.size_bytes);
    }

    def finish_scan() {
        print(f"Scanning {self.files_scanned} files...");
        print("");
        group_num = 0;
        for (i, hash_a) in enumerate(self.hashes) {
            seen_before = False;
            for j in range(i) {
                if self.hashes[j] == hash_a {
                    seen_before = True;
                }
            }
            if seen_before {
                continue;
            }
            match_count = 0;
            for hash_b in self.hashes {
                if hash_a == hash_b {
                    match_count += 1;
                }
            }
            if match_count > 1 {
                group_num += 1;
                print(f"Duplicate Group #{group_num}");
                print("------------------");
                for (j, hash_b) in enumerate(self.hashes) {
                    if hash_a == hash_b {
                        print(self.paths[j]);
                    }
                }
                print("");
                extra_bytes = 0;
                keeper_size = 0;
                for (j, hash_b) in enumerate(self.hashes) {
                    if hash_a == hash_b {
                        extra_bytes += self.sizes[j];
                        if keeper_size == 0 {
                            keeper_size = self.sizes[j];
                        }
                    }
                }
                self.savings_bytes += extra_bytes - keeper_size;
            }
        }
        savings_mb = self.savings_bytes / (1024.0 * 1024.0);
        print(f"Potential storage savings: {savings_mb} MB");
        print("");
        print("Scan completed successfully.");
    }
}

with entry {
    project = Directory(name="project", path=".");
    assets = Directory(name="assets", path="assets");
    backup = Directory(name="backup", path="backup");
    data_dir = Directory(name="data", path="data");
    archive = Directory(name="archive", path="archive");
    src_dir = Directory(name="src", path="src");
    modules = Directory(name="node_modules", path="node_modules", ignored=True);

    logo_assets = File(path="assets/logo.png", content_hash="sha256:logo", size_bytes=524288);
    logo_backup = File(path="backup/logo.png", content_hash="sha256:logo", size_bytes=524288);
    users_data = File(path="data/users.json", content_hash="sha256:users", size_bytes=25165824);
    users_archive = File(path="archive/users-copy.json", content_hash="sha256:users", size_bytes=25165824);
    app_js = File(path="src/app.js", content_hash="sha256:unique", size_bytes=4096);
    hidden_logo = File(path="node_modules/cache/logo.png", content_hash="sha256:logo", size_bytes=524288);

    root +>:Contains:+> project;
    project +>:Contains:+> assets;
    project +>:Contains:+> backup;
    project +>:Contains:+> data_dir;
    project +>:Contains:+> archive;
    project +>:Contains:+> src_dir;
    project +>:Contains:+> modules;

    assets +>:Contains:+> logo_assets;
    backup +>:Contains:+> logo_backup;
    data_dir +>:Contains:+> users_archive;
    archive +>:Contains:+> users_archive;
    data_dir +>:Contains:+> users_data;
    src_dir +>:Contains:+> app_js;
    modules +>:Contains:+> hidden_logo;

    scanner = DuplicateScanner();
    root spawn scanner;
    scanner.finish_scan();
}
