```jac
"""Synthetic-world test platform: model plugins, scenarios, and fixtures as a graph.

Models the elizaOS issue's core complaint: a fragmented test foundation where
plugins, scenarios, and mock-model fixtures are not unified into one resettable
synthetic world. Walkers traverse the graph to audit coverage gaps, simulate
the two model modes (strict mock vs. real-model 3/3 stability), and surface
uncovered runtime surfaces.
"""

node Plugin {
    has name: str = "";
    has surfaces: list[str] = [];
    has in_scenario: bool = False;
    has mock_fixture_count: int = 0;
}

node Scenario {
    has name: str = "";
    has model_mode: str = "strict_mock";
    has first_pass: bool = False;
    has stable_3_of_3: bool = False;
}

node Fixture {
    has provider: str = "";
    has registered: int = 0;
    has used: int = 0;
    has unmatched: int = 0;
}

edge HasSurface {
    has kind: str = "";
}

edge CoveredBy;

edge RegisteredFor;

walker CoverageAuditor {
    has uncovered: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Plugin entry {
        report_label = "COVERED" if here.in_scenario else "UNCOVERED";
        print(f"[{report_label}] plugin {here.name} surfaces={here.surfaces}");
        if not here.in_scenario {
            self.uncovered.append(here.name);
        }
        visit [->:CoveredBy:->];
    }

    can inspect_scenario with Scenario entry {
        mode_label = "strict-mock" if here.model_mode == "strict_mock" else "real-model";
        stability_label = "3/3 stable" if here.stable_3_of_3 else "below 3/3";
        print(f"scenario {here.name} mode={mode_label} first_pass={here.first_pass} stability={stability_label}");
        visit [->:RegisteredFor:->];
    }

    can inspect_fixture with Fixture entry {
        unused_label = "unmatched" if here.unmatched > 0 else "all-used";
        print(f"fixture provider={here.provider} registered={here.registered} used={here.used} status={unused_label}");
    }
}

with entry {
    p_action = Plugin(name="action-plugin", surfaces=["action"], in_scenario=True, mock_fixture_count=4);
    p_provider = Plugin(name="provider-plugin", surfaces=["provider"], in_scenario=False);
    p_service = Plugin(name="service-plugin", surfaces=["service"], in_scenario=True, mock_fixture_count=2);
    p_route = Plugin(name="route-plugin", surfaces=["route"], in_scenario=False);
    p_evaluator = Plugin(name="evaluator-plugin", surfaces=["evaluator"], in_scenario=True);

    strict_mock = Scenario(name="boot-strict", model_mode="strict_mock", first_pass=True, stable_3_of_3=True);
    real_model = Scenario(name="boot-real", model_mode="real_model", first_pass=True, stable_3_of_3=False);

    fx_llm = Fixture(provider="mock-llm", registered=5, used=5, unmatched=0);
    fx_api = Fixture(provider="mock-api", registered=3, used=2, unmatched=1);

    root ++> p_action;
    root ++> p_provider;
    root ++> p_service;
    root ++> p_route;
    root ++> p_evaluator;

    p_action +>:CoveredBy:+> strict_mock;
    p_service +>:CoveredBy:+> strict_mock;
    p_evaluator +>:CoveredBy:+> strict_mock;
    p_provider +>:CoveredBy:+> real_model;
    p_route +>:CoveredBy:+> real_model;

    strict_mock +>:RegisteredFor:+> fx_llm;
    real_model +>:RegisteredFor:+> fx_api;

    auditor = CoverageAuditor();
    root spawn auditor;
    print(f"\nAUDIT SUMMARY: uncovered plugins = {auditor.uncovered}");
}
