Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Deep document update with materialized-path repair.

Models the scenario from issue #8 of janez89/mongoose-materialized: a
maintainer wants to dynamically update a deeply-nested document, then
recompute the materialized path of the updated node AND every
descendant. The hand-rolled machinery in the original (manual recursion
over children, queue-based traversal, repeated `findById` calls) is
replaced by a walker that traverses typed `ParentOf` edges, with an
explicit cycle guard (jac 0.36.1 walkers have no built-in
once-per-node visitation, so the guard set is domain logic and must
survive the lift).
"""

node Doc {
    has title: str = "";
    has path: str = "";
}

edge ParentOf { }

walker DeepUpdater {
    has new_parent_path: str = "";
    has guard: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can rewire with Doc entry {
        here.path = self.new_parent_path + "/" + here.title;
        print(f"repathed {here.title} -> {here.path}");
        self.guard.append(here.title);
        visit [->:ParentOf:->];
    }
}

walker CascadeRepath {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Doc entry {
        if here.title in self.seen {
            print(f"cycle guard hit at {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        print(f"visited {here.title} path={here.path}");
        visit [->:ParentOf:->];
    }
}

with entry {
    a = Doc(title="root-a");
    b = Doc(title="child-b");
    c = Doc(title="grandchild-c");
    d = Doc(title="leaf-d");

    root ++> a +>:ParentOf:+> b +>:ParentOf:+> c +>:ParentOf:+> d;

    updater = DeepUpdater(new_parent_path="/org/team");
    a spawn updater;

    print("--- cascade check ---");
    cascade = CascadeRepath();
    a spawn cascade;
}
```

```jac
"""Signal Matrix Static Dashboard V1: per-timeframe primitive signal inventory.

Models a transparent asset x timeframe matrix where primitive signals
(HTF/LTF, Breath/Fibo frame, regime context, external catalyst context,
freshness, replay-readiness, local pattern candidates) are exposed as
nodes connected via typed edges. A walker audits the matrix for reachability,
freshness, and explicit primitive conflicts without collapsing them into a
single composed advice label.
"""

node Asset {
    has symbol: str = "";
    has market: str = "";
}

node Timeframe {
    has label: str = "";
    has minutes: int = 0;
}

node PrimitiveSignal {
    has name: str = "";
    has payload: str = "";
    has stale: bool = False;
}

node RegimeContext {
    has regime: str = "";
    has confidence: float = 0.0;
}

node CatalystContext {
    has source: str = "";
    has fresh: bool = True;
}

edge HasTimeframe { }
edge SignalsOn { }
edge HasRegime { }
edge HasCatalyst { }
edge ConflictsWith { }

walker MatrixAuditor {
    has visited_assets: list[str] = [];
    has conflict_count: int = 0;
    has stale_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_asset with Asset entry {
        if here.symbol not in self.visited_assets {
            self.visited_assets.append(here.symbol);
            print(f"[ASSET] {here.symbol} market={here.market}");
        }
        visit [->:HasTimeframe:->];
    }

    can inspect_timeframe with Timeframe entry {
        print(f"  [TF] {here.label} ({here.minutes}m)");
        visit [-->];
    }

    can inspect_primitive with PrimitiveSignal entry {
        status = "STALE" if here.stale else "LIVE";
        print(f"    [SIG {status}] {here.name} :: {here.payload}");
        if here.stale {
            self.stale_count += 1;
        }
        visit [-->];
    }

    can inspect_regime with RegimeContext entry {
        print(f"    [REGIME] {here.regime} conf={here.confidence:.2f}");
        visit [-->];
    }

    can inspect_catalyst with CatalystContext entry {
        fresh_tag = "FRESH" if here.fresh else "STALE";
        print(f"    [CATALYST {fresh_tag}] {here.source}");
        visit [-->];
    }

    can inspect_conflict with PrimitiveSignal entry {
        conflicts = [->:ConflictsWith:->];
        for (idx, nbr) in enumerate(conflicts) {
            if isinstance(nbr, PrimitiveSignal) {
                self.conflict_count += 1;
                print(f"  [CONFLICT] {here.name} <-> {nbr.name}");
            }
        }
        visit [-->];
    }
}

with entry {
    btc = Asset(symbol="BTC-USD", market="crypto");
    eth = Asset(symbol="ETH-USD", market="crypto");
    root ++> btc;
    root ++> eth;

    tf_1h = Timeframe(label="1H", minutes=60);
    tf_4h = Timeframe(label="4H", minutes=240);
    tf_1d = Timeframe(label="1D", minutes=1440);

    sig_htf_up = PrimitiveSignal(name="HTF_TREND_UP", payload="ema_stack_bull", stale=False);
    sig_ltf_up = PrimitiveSignal(name="LTF_BREATH_UP", payload="higher_highs", stale=False);
    sig_fibo_retrace = PrimitiveSignal(name="FIBO_RETRACEMENT", payload="0.618 hold", stale=False);
    sig_ltf_div = PrimitiveSignal(name="LTF_DIVERGENCE", payload="rsi_bear_div", stale=True);
    sig_replay = PrimitiveSignal(name="REPLAY_READY", payload="bar_count_ok", stale=False);

    regime_bull = RegimeContext(regime="BULL", confidence=0.72);
    regime_wary = RegimeContext(regime="CAUTIOUS_BULL", confidence=0.55);

    cat_onchain = CatalystContext(source="onchain_whale_flow", fresh=True);
    cat_macro = CatalystContext(source="macro_cpi_print", fresh=False);

    btc +>:HasTimeframe:+> tf_1h;
    tf_1h +>:SignalsOn:+> sig_htf_up;
    tf_1h +>:SignalsOn:+> sig_ltf_up;
    tf_1h +>:SignalsOn:+> sig_ltf_div;
    tf_1h +>:HasRegime:+> regime_bull;
    tf_1h +>:HasCatalyst:+> cat_onchain;

    btc +>:HasTimeframe:+> tf_4h;
    tf_4h +>:SignalsOn:+> sig_fibo_retrace;
    tf_4h +>:HasRegime:+> regime_wary;
    tf_4h +>:HasCatalyst:+> cat_macro;

    btc +>:HasTimeframe:+> tf_1d;
    tf_1d +>:SignalsOn:+> sig_replay;

    sig_ltf_up +>:ConflictsWith:+> sig_ltf_div;

    root spawn MatrixAuditor();

    final_assets = ",".join([btc.symbol, eth.symbol]);
    print(f"Matrix audited: assets={final_assets} | "
          f"conflicts exposed=1 | stale primitives surfaced=1");
}
