```jac
"""Zed extension subject materialization: model the build/attestation scenario.

Picks the core entities (upstream base, candidate projection, source tree,
WASM artifact, subject manifest) and demonstrates how a walker can traverse
the subject graph, detect drift between inputs, and refuse to attest when
the bindings are inconsistent.
"""

node UpstreamBase {
    has repository: str = "";
    has branch: str = "";
    has commit: str = "";
    has tree: str = "";
}

node Candidate {
    has projection_sha256: str = "";
    has apply_script_sha256: str = "";
    has changed_files_sha256: str = "";
}

node Manifest {
    has extension_id: str = "";
    has version: str = "";
    has zed_extension_api: str = "";
    has license_sha256: str = "";
}

node Toolchain {
    has rust: str = "";
    has target: str = "";
    has cargo_lock_sha256: str = "";
}

node SourceTree {
    has tree_sha256: str = "";
    has file_manifest_sha256: str = "";
}

node Artifact {
    has wasm_path: str = "";
    has wasm_sha256: str = "";
    has size: int = 0;
}

edge BoundTo { has digest: str = ""; }
edge InvalidatedBy { has reason: str = ""; }

walker Attestor {
    has accepted: bool = True;
    has visited_nodes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with UpstreamBase | Candidate | Manifest | Toolchain | SourceTree | Artifact entry {
        label = here.repository if isinstance(here, UpstreamBase) else (
            here.projection_sha256 if isinstance(here, Candidate) else (
            here.extension_id if isinstance(here, Manifest) else (
            here.rust if isinstance(here, Toolchain) else (
            here.tree_sha256 if isinstance(here, SourceTree) else (
            here.wasm_sha256)))));
        self.visited_nodes.append(label);
        report label;
        visit [-->];
    }

    can reach_base with UpstreamBase entry {
        if here.commit == "" or here.tree == "" {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }

    can reach_candidate with Candidate entry {
        if here.projection_sha256 == "" or here.changed_files_sha256 == "" {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }

    can reach_manifest with Manifest entry {
        if here.extension_id == "" or here.license_sha256 == "" {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }

    can reach_toolchain with Toolchain entry {
        if here.cargo_lock_sha256 == "" {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }

    can reach_source with SourceTree entry {
        if here.tree_sha256 == "" or here.file_manifest_sha256 == "" {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }

    can reach_artifact with Artifact entry {
        if here.wasm_sha256 == "" or here.size <= 0 {
            self.accepted = False;
            disengage;
        }
        visit [-->];
    }
}

with entry {
    base = UpstreamBase(
        repository="tree-sitter-perl/zed-perl",
        branch="main",
        commit="abc123",
        tree="tree-deadbeef"
    );
    cand = Candidate(
        projection_sha256="proj-cafe",
        apply_script_sha256="script-babe",
        changed_files_sha256="files-face"
    );
    mani = Manifest(
        extension_id="zed.perl",
        version="0.1.0",
        zed_extension_api="0.5.0",
        license_sha256="lic-d00d"
    );
    tool = Toolchain(
        rust="1.75.0",
        target="wasm32-wasip2",
        cargo_lock_sha256="lock-cafe"
    );
    src = SourceTree(
        tree_sha256="tree-cafe",
        file_manifest_sha256="fman-babe"
    );
    art = Artifact(
        wasm_path="build/release/extension.wasm",
        wasm_sha256="wasm-cafe",
        size=204800
    );

    root ++> base +>:BoundTo(digest="base-anchor"):+> cand;
    cand +>:BoundTo(digest="cand-anchor"):+> mani;
    mani +>:BoundTo(digest="mani-anchor"):+> tool;
    tool +>:BoundTo(digest="tool-anchor"):+> src;
    src +>:BoundTo(digest="src-anchor"):+> art;

    bad_mani = Manifest(
        extension_id="",
        version="0.1.0",
        zed_extension_api="0.5.0",
        license_sha256="lic-d00d"
    );
    root +>:InvalidatedBy(reason="missing extension_id"):+> bad_mani;

    attestor = Attestor();
    root spawn attestor;

    print(f"Visited nodes: {attestor.visited_nodes}");
    print(f"Subject accepted: {attestor.accepted}");

    print("--- Subject manifest summary ---");
    print(f"upstream: {base.repository}@{base.commit} tree={base.tree}");
    print(f"candidate: projection={cand.projection_sha256} changed={cand.changed_files_sha256}");
    print(f"manifest: id={mani.extension_id} v={mani.version} api={mani.zed_extension_api}");
    print(f"toolchain: rust={tool.rust} target={tool.target}");
    print(f"source: tree={src.tree_sha256}");
    print(f"artifact: {art.wasm_path} sha={art.wasm_sha256} size={art.size}");
}
