    #   root -> compile  ->+-> link_tests  (diamond apex)
    #                         +-> link_app
    #   root -> bundle_lib (shared library, reached via both link_* paths)
    compile = Task(title="compile", minutes=10);
    link_tests = Task(title="link_tests", minutes=5);
    link_app = Task(title="link_app", minutes=5);
    bundle_lib = Task(title="bundle_lib", minutes=3);

    root ++> compile ++> link_tests;
    root ++> link_tests ++> bundle_lib;
    root ++> link_app;
    root ++> link_app ++> bundle_lib;

    auditor = Auditor();
    root spawn auditor;

    print(f"\nTotal build minutes (deduplicated): {auditor.total_minutes}");
    print(f"Tasks audited in order: {auditor.visited_titles}");
}
