```jac
"""Online store checkout: polymorphic shipping/handling per product type.

The cart holds a heterogeneous mix of products (paper book, digital book,
electronics, clothing). A single checkout walker visits each product and
dispatches on its concrete node type via union-trigger abilities, producing
an itemized receipt with subtotal, shipping, and grand total.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;

    def base_price() -> float {
        return self.price;
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;
    override def base_price() -> float {
        return self.price;
    }
}

node DigitalBook(Product) {
    has size_mb: float = 5.0;
    override def base_price() -> float {
        return self.price;
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;
    override def base_price() -> float {
        return self.price;
    }
}

node Clothing(Product) {
    has size: str = "M";
    override def base_price() -> float {
        return self.price;
    }
}

edge InCart {}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list[str] = [];

    def line_total(cost: float, ship: float) -> float {
        return cost + ship;
    }

    can start with Root entry {
        visit [-->];
    }

    can finish with Root exit {
        total = self.subtotal + self.shipping;
        print("----- Receipt -----");
        for ln in self.lines {
            print(ln);
        }
        print(f"Subtotal: ${self.subtotal:.2f}");
        print(f"Shipping: ${self.shipping:.2f}");
        print(f"Total:    ${total:.2f}");
    }

    # Paper books: weight-based shipping, fragile handling fee.
    can charge_paper with PaperBook entry {
        handling = 0.99;
        ship = 2.50 + 0.75 * here.weight_lb;
        line = self.line_total(here.price, ship + handling);
        self.lines.append(f"PaperBook  {here.name:<14} ${here.price:6.2f} + ship ${ship:5.2f} + handling ${handling:.2f} = ${line:.2f}");
        self.subtotal += here.price;
        self.shipping += ship + handling;
    }

    # Digital books: no shipping, no handling — pure download.
    can charge_digital with DigitalBook entry {
        ship = 0.0;
        handling = 0.0;
        line = self.line_total(here.price, ship);
        self.lines.append(f"DigitalBook {here.name:<14} ${here.price:6.2f} + ship $ 0.00 = ${line:.2f}");
        self.subtotal += here.price;
        self.shipping += ship;
    }

    # Electronics: flat-rate insured shipping + warranty surcharge.
    can charge_electronics with Electronics entry {
        ship = 9.99;
        handling = 1.50 + 0.25 * float(here.warranty_months);
        line = self.line_total(here.price, ship + handling);
        self.lines.append(f"Electronics {here.name:<14} ${here.price:6.2f} + ship ${ship:5.2f} + handling ${handling:.2f} = ${line:.2f}");
        self.subtotal += here.price;
        self.shipping += ship + handling;
    }

    # Clothing: free shipping over $50, otherwise flat $4.99.
    can charge_clothing with Clothing entry {
        ship = 0.0 if here.price >= 50.0 else 4.99;
        handling = 0.0;
        line = self.line_total(here.price, ship);
        self.lines.append(f"Clothing    {here.name:<14} ${here.price:6.2f} + ship ${ship:5.2f} = ${line:.2f}");
        self.subtotal += here.price;
        self.shipping += ship;
    }
}

with entry {
    cart = root;

    cart ++> PaperBook(name="Dune", price=12.99, weight_lb=1.2);
    cart ++> DigitalBook(name="Neuromancer", price=8.50, size_mb=4.2);
    cart ++> Electronics(name="Headphones", price=89.00, warranty_months=24);
    cart ++> Clothing(name="Hoodie", price=45.00, size="L");
    cart ++> Clothing(name="Jacket", price=120.00, size="XL");

    root spawn Checkout();
}
```

