```jac
"""ECS lock-order tracker: held_others snapshot before enabled check vs fast path.

Models PERF-D1: in debug builds the tracker heap-allocates a held-locks
snapshot on every nested acquire before the relaxed ENABLED load proves
order checking is off. The fixed path hoists emptiness and enabled tests
above the collect so the disabled default stays one relaxed load.
"""

edge Holds { }

node LockKind {
    has type_name: str = "";
}

node ThreadTracker {
    has order_check_enabled: bool = False;
    has held_kind_count: int = 0;
    has snapshot_allocs: int = 0;
    has relaxed_loads: int = 0;

    def naive_acquire(held_len: int, type_name: str) {
        if held_len > 0 {
            self.snapshot_allocs += 1;
        }
        self.relaxed_loads += 1;
        if held_len == 0 {
            return;
        }
        if not self.order_check_enabled {
            return;
        }
    }

    def fast_acquire(held_len: int, type_name: str) {
        self.relaxed_loads += 1;
        if held_len == 0 {
            return;
        }
        if not self.order_check_enabled {
            return;
        }
        self.snapshot_allocs += 1;
    }
}

node NestingSite {
    has label: str = "";
    has burst_count: int = 0;
}

walker LockOrderProbe {
    has tracker_ref: ThreadTracker;
    has naive_path: bool = True;
    has held_len: int = 0;
    has site_label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can arm with ThreadTracker entry {
        self.tracker_ref = here;
        self.held_len = here.held_kind_count;
        visit [-->];
    }

    can replay_burst with NestingSite entry {
        self.site_label = here.label;
        i = 0;
        while i < here.burst_count {
            if self.naive_path {
                self.tracker_ref.naive_acquire(self.held_len, "QueryMut");
            } else {
                self.tracker_ref.fast_acquire(self.held_len, "QueryMut");
            }
            i += 1;
        }
        path_tag = "NAIVE" if self.naive_path else "FAST";
        print(
            f"[{path_tag}] {self.site_label}: held={self.held_len} "
            f"bursts={here.burst_count} snapshot_allocs="
            f"{self.tracker_ref.snapshot_allocs} relaxed_loads="
            f"{self.tracker_ref.relaxed_loads}"
        );
        visit [-->] else { disengage; };
    }
}

with entry {
    tracker = ThreadTracker(order_check_enabled=False, held_kind_count=5);
    site = NestingSite(label="static_mesh_draws", burst_count=24);
    root ++> tracker ++> site;
    tracker +>:Holds:+> LockKind(type_name="MeshRegistry");
    tracker +>:Holds:+> LockKind(type_name="MaterialTable");
    tracker +>:Holds:+> LockKind(type_name="Transform");
    tracker +>:Holds:+> LockKind(type_name="Visibility");
    tracker +>:Holds:+> LockKind(type_name="DrawBatch");
    print("BYRO_LOCK_ORDER_CHECK unset (enabled=False), 5 locks already held");
    root spawn LockOrderProbe(tracker_ref=tracker, naive_path=True);
    tracker.snapshot_allocs = 0;
    tracker.relaxed_loads = 0;
    root spawn LockOrderProbe(tracker_ref=tracker, naive_path=False);
}
