"""Tiny dungeon crawler: chain of room nodes ending in a treasure vault.

A Hunter walker traverses the chain room by room, counting how many
rooms it has seen. The moment it steps into the treasure room, the
walker disengages so that no rooms past the vault are ever visited.
"""

node Room {
    has name: str = "";
    has treasure: bool = False;
}

walker Hunter {
    has seen: int = 0;
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can prowl with Room entry {
        self.seen += 1;
        if here.treasure {
            self.found = True;
            print(f"Found treasure in '{here.name}' after {self.seen} rooms!");
            disengage;
        }
        print(f"Searched '{here.name}' ({self.seen} so far)");
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Foyer")
        ++> Room(name="Hallway")
        ++> Room(name="Vault", treasure=True)
        ++> Room(name="Secret Chamber")
        ++> Room(name="Dragon's Lair");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter saw {hunter.seen} rooms, found treasure: {hunter.found}");
}
