```jac
"""Fighter advancements view: model N+1 query issue with explicit pre-fetch walker.

Scenario distilled from gyrinx-app/gyrinx issue #768. A fighter has
advancements (skill upgrades, campaign actions), and the template also
needs the fighter's content_fighter template data. Without a pre-fetch
walker that joins the relationships up front, every advancement template
render triggers a fresh query -- the classic N+1 pattern.

This demo shows two traversals:
  - AdvancementsAuditor: walks Skill / CampaignAction nodes through the
    typed ``Lists`` edge from the root, and reads the fighter's content
    payload via a single pre-loaded reference (the analog of a JOIN).
  - ContentPrefetch: a walker that issues an explicit pre-fetch when
    arriving at a Fighter, so the template can render all rows in one go.
"""

# ---- entity archetypes -----------------------------------------------------

node ContentFighter {
    has name: str = "";
    has archetype: str = "";
    has house: str = "";
}

node Fighter {
    has name: str = "";
    has content: str = "";
}

node Skill {
    has title: str = "";
    has xp_cost: int = 0;
}

node CampaignAction {
    has title: str = "";
    has description: str = "";
}

# ---- typed edges -----------------------------------------------------------

# Carries meaning: "this Fighter is built from this ContentFighter template".
# In the original code this was a ForeignKey join -- here it's a typed edge
# so the walker can traverse Fighter -> ContentFighter in one visit.
edge BuiltFrom {
    has since: str = "";
}

# Carries meaning: "these advancements belong to this fighter list".
edge Lists {
    has slot: int = 0;
}

# Plain advancement edges, typed so the walker knows what it is inspecting.
edge HasSkill {}
edge HasCampaignAction {}

# ---- walkers ---------------------------------------------------------------

walker AdvancementsAuditor {
    has prefetched_content: dict = {};

    # Entering root: kick the walk down to fighters.
    can start with Root entry {
        print("[AdvancementsAuditor] starting at root, walking to fighters");
        visit [-->];
    }

    # Pre-fetch is done ONCE here, on the fighter, exactly the join the
    # issue is asking for. Once prefetched, every subsequent template
    # access is just a dict lookup, not a query.
    can audit with Fighter entry {
        cf_name = self.prefetched_content.get(here.name, "<no content>");
        print(f"[AdvancementsAuditor] fighter={here.name} "
              f"content={cf_name}  (prefetched, no extra query)");
        visit [-->];
    }

    # One union ability covers both advancement types: every advancement
    # node shares ``title``, which is all the template needs.
    can inspect with Skill | CampaignAction entry {
        print(f"[AdvancementsAuditor]   advancement: {here.title}");
    }
}

walker ContentPrefetch {
    # Walks Fighter -> ContentFighter via the typed BuiltFrom edge.
    # This is what ``select_related('content_fighter')`` does in SQL.
    can start with Root entry {
        print("[ContentPrefetch] walking root -> fighter -> content_fighter");
        visit [-->];
    }

    can hop_to_content with Fighter entry {
        print(f"[ContentPrefetch]   at fighter {here.name}, "
              f"following BuiltFrom edge");
        visit [->:BuiltFrom:->];
    }

    can load_content with ContentFighter entry {
        print(f"[ContentPrefetch]     loaded content_fighter "
              f"({here.name} / {here.archetype})");
        visit [-->];
    }
}

# ---- demo wiring -----------------------------------------------------------

with entry {
    # Build a small content catalogue.
    cf_champion = ContentFighter(
        name="Champion",
        archetype="Leader",
        house="House Orlock",
    );
    cf_juve = ContentFighter(
        name="Juve",
        archetype="Ganger",
        house="House Goliath",
    );

    # Build fighters, each linked to its content template by a typed
    # BuiltFrom edge (the relationship the issue says should be JOINed).
    f_champion = Fighter(name="Grim", content="Champion");
    f_juve = Fighter(name="Ratchet", content="Juve");

    f_champion +>:BuiltFrom(since="pre-game"):+> cf_champion;
    f_juve +>:BuiltFrom(since="pre-game"):+> cf_juve;

    # Build advancements. Typed edges make the relationship explicit
    # instead of relying on Django's select_related() to discover it.
    skills = [
        Skill(title="Iron Will", xp_cost=6),
        Skill(title="Nerves of Steel", xp_cost=4),
    ];
    actions = [
        CampaignAction(
            title="Recover Wounds",
            description="Heal a fighter on the battlefield.",
        ),
    ];

    # Wire them onto the fighter list via the Lists edge.
    f_champion +>:Lists(slot=1):+> skills[0];
    f_champion +>:Lists(slot=2):+> skills[1];
    f_champion +>:Lists(slot=3):+> actions[0];

    # Anchor everything under root so the walkers have a starting point.
    root ++> f_champion;
    root ++> f_juve;

    # Demonstrate the fix: pre-load content_fighter payloads once, then
    # let AdvancementsAuditor walk every advancement in one pass.
    prefetched: dict = {
        f_champion.name: f"{cf_champion.name} ({cf_champion.archetype})",
        f_juve.name: f"{cf_juve.name} ({cf_juve.archetype})",
    };
    auditor = AdvancementsAuditor(prefetched_content=prefetched);
    print("=== AdvancementsAuditor (template render pass) ===");
    root spawn auditor;

    # Demonstrate the typed traversal that replaces select_related.
    print("=== ContentPrefetch (typed-edge JOIN) ===");
    root spawn ContentPrefetch();

    print("=== done ===");
}
```

```jac
"""ADWF Foundation traceability graph: walk Owner-Intent -> Requirement -> Decision
and prove every requirement is grounded in a live decision and a live intent,
mirroring the fail-closed semantics the programme demands.

Entities are node archetypes; the durable links between them are typed edges;
a walker performs the cascade verification that the issue's hand-rolled
machinery used to do with parent_id recursion and id-keyed registries.
"""

node Intent {
    has title: str = "";
    has status: str = "DRAFT";
}

node Requirement {
    has title: str = "";
    has priority: int = 0;
    has verified: bool = False;
}

node Decision {
    has title: str = "";
    has rationale: str = "";
    has adopted: bool = False;
}

edge Drives {
    has weight: int = 1;
}

edge Satisfies {
    has confidence: float = 1.0;
}

edge Invalidates {
    has reason: str = "";
}

walker TraceAuditor {
    has findings: list[str] = [];
    has visited: list[str] = [];
    has broken: bool = False;

    can start with Root entry {
        print("ADWF Foundation trace audit begins");
        visit [-->];
    }

    can audit_intent with Intent entry {
        tag = f"I[{here.title}/{here.status}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"intent '{here.title}' status={here.status}");
        if here.status != "LIVE" {
            self.broken = True;
            self.findings.append(f"  -> intent '{here.title}' is not LIVE");
        }
        visit [->:Drives:->] else { disengage; }
    }

    can audit_requirement with Requirement entry {
        tag = f"R[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        line = f"requirement '{here.title}' pri={here.priority} verified={here.verified}";
        self.findings.append(line);
        if not here.verified {
            self.broken = True;
            self.findings.append(f"  -> requirement '{here.title}' not verified");
        }
        visit [->:Satisfies:->] else { disengage; }
    }

    can audit_decision with Decision entry {
        tag = f"D[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"decision '{here.title}' adopted={here.adopted}");
        if not here.adopted {
            self.broken = True;
            self.findings.append(f"  -> decision '{here.title}' not adopted");
        }
        visit [->:Invalidates:->] else { disengage; }
    }
}

with entry {
    i_lifecycle = Intent(title="ConsumerLifecycle", status="LIVE");
    i_trace = Intent(title="DecisionTraceability", status="LIVE");
    i_stale = Intent(title="StaleDiscovery", status="DRAFT");

    r_lifecycle = Requirement(title="RecoverOrDetach", priority=1, verified=True);
    r_evidence = Requirement(title="RealConsumerEvidence", priority=2, verified=True);
    r_trace = Requirement(title="GraphAppendOnly", priority=1, verified=True);
    r_unverified = Requirement(title="AdversarialAudit", priority=0, verified=False);

    d_merge = Decision(title="AdoptFailClosed", rationale="no live evidence -> no claim", adopted=True);
    d_skip = Decision(title="SkipAdversarialGate", rationale="premature", adopted=False);
    d_invalidate = Decision(title="InvalidateStaleDiscovery", rationale="superseded by v1.8", adopted=True);

    root ++> i_lifecycle
        ++> i_trace
        ++> i_stale
        ++> r_lifecycle
        ++> r_evidence
        ++> r_trace
        ++> r_unverified
        ++> d_merge
        ++> d_skip
        ++> d_invalidate;

    i_lifecycle +>:Drives(weight=3):+> r_lifecycle;
    i_lifecycle +>:Drives(weight=2):+> r_evidence;
    i_trace +>:Drives(weight=4):+> r_trace;
    i_stale +>:Drives(weight=1):+> r_unverified;

    r_lifecycle +>:Satisfies(confidence=0.95):+> d_merge;
    r_evidence +>:Satisfies(confidence=0.80):+> d_merge;
    r_trace +>:Satisfies(confidence=0.90):+> d_merge;
    r_unverified +>:Satisfies(confidence=0.10):+> d_skip;

    d_merge +>:Invalidates(reason="dethroned by later audit policy"):+> d_skip;
    d_merge +>:Invalidates(reason="stale draft, no owner intent LIVE"):+> d_invalidate;

    auditor = TraceAuditor();
    root spawn auditor;

    print("--- trace report ---");
    for line in auditor.findings {
        print(line);
    }
    print("--- summary ---");
    verdict = "FAIL_CLOSED" if auditor.broken else "PASS";
    print(f"trace audit verdict: {verdict}");
    print(f"nodes inspected: {len(auditor.visited)}");
}
```

