"""Factory zone monitoring.

Patrol two zones that contain a mix of temperature and smoke sensors.
A single monitoring ability handles both sensor types via a union
trigger, prints each reading as nominal or an alert, and the walker
reports the final alert list when it disengages.
"""

node Zone {
    has name: str = "";
}

node Sensor {
    has label: str = "";

    def is_alert() -> bool {
        return False;
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

edge DeployedIn {
    has since: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"-- patrolling zone: {here.name} --");
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            tag = "ALERT";
            reading = f"{here.label} reading exceeds threshold";
            self.alerts.append(reading);
        } else {
            tag = "nominal";
        }
        print(f"[{tag}] {here.label}");
    }
}

with entry {
    zone_a = Zone(name="Zone A");
    zone_b = Zone(name="Zone B");

    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Boiler-1", celsius=82.5);
    zone_a ++> SmokeSensor(label="Boiler-1 smoke", ppm=18.0);
    zone_a ++> TempSensor(label="Boiler-2", celsius=70.0);

    zone_b ++> SmokeSensor(label="Bay-3 smoke", ppm=63.0);
    zone_b ++> TempSensor(label="Bay-3 temp", celsius=55.0);
    zone_b ++> SmokeSensor(label="Bay-4 smoke", ppm=12.5);

