```jac
"""Mutual friendships in a neighborhood: houses as nodes, bidirectional buddy edges, two greeters that prove the link runs both ways without bouncing forever."""

node House {
    has name: str = "";
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has start_house: str = "";
    has visited_set: list[str] = [];
    has reached: str = "";

    can start with Root entry {
        visit [-->];
    }

    can greet with House entry {
        # Cycle guard: refuse to re-enter a house already in the set.
        # Without this, the walker would bounce forever on a bidirectional edge.
        if here.name in self.visited_set {
            visit [-->] else { disengage; }
            return;
        }
        self.visited_set = self.visited_set + [here.name];
        print(f"[{self.start_house}] greeting {here.name} (visited: {self.visited_set})");
        if here.name != self.start_house {
            self.reached = here.name;
            print(f"[{self.start_house}] reached buddy {here.name} ✓");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Two houses connected by a single typed buddy edge each way:
    # one statement declares both directions of the relationship.
    h1 = House(name="Maple");
    h2 = House(name="Oak");
    h1 <+:Buddy(since="2010"):+> h2;

    # Spawn a fresh greeter at each house so we can prove the link is two-way.
    g1 = Greeter(start_house="Maple");
    h1 spawn g1;

    g2 = Greeter(start_house="Oak");
    h2 spawn g2;

    # Summarize the round trip so the bidirectional proof is unmistakable.
    print(f"Maple reached: {g1.reached}");
    print(f"Oak reached:   {g2.reached}");
}
