"""Build dependency audit: traverse a diamond-shaped dependency graph,
counting each task's build minutes exactly once even when multiple paths
converge on it."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has available: bool = True;
}

walker Auditor {
    has visited_titles: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        print("Auditing build dependency graph...");
        visit [-->];
    }

    can audit with Task entry {
        if here.title not in self.visited_titles {
            self.visited_titles.append(here.title);
            status = "OK" if here.available else "BLOCKED";
            print(f"[{status}] {here.title}: {here.minutes} min");
            self.total_minutes = self.total_minutes + here.minutes;
        }
        visit [-->];
    }
}

with entry {
    shared_lib = Task(title="shared-lib", minutes=5);
    parser = Task(title="parser", minutes=10);
    linker = Task(title="linker", minutes=8);
    codegen = Task(title="codegen", minutes=12);
    compiler = Task(title="compiler", minutes=15, available=False);

    root ++> shared_lib
        ++> parser
        ++> linker
        ++> codegen
        ++> compiler;
    shared_lib ++> parser;
    shared_lib ++> linker;
    parser ++> codegen;
    linker ++> codegen;
    codegen ++> compiler;

    auditor = Auditor();
    root spawn auditor;
    print(f"Total audited build minutes (each task counted once): {auditor.total_minutes}");
}
