```jac
"""M12 canonical IR consolidation: dependency-ordered wave gates, legacy reachability inventory, and ProcessIR compile pipeline."""

node IntegrationSpecV1 {
    has title: str = "";
    has pipeline_locked: bool = True;
    has validated: bool = False;
}

node ProcessAuthoringUnitV1 {
    has unit_id: str = "";
    has capability_gated: bool = True;
    has validated: bool = False;
}

node ProcessIR {
    has fingerprint: str = "";
    has attested: bool = False;
    has level_one: bool = False;
    has level_two: bool = False;
}

node LegacySlice {
    has issue_num: int = 0;
    has slice_name: str = "";
    has transferred: bool = False;
    has blocking_findings: int = 0;
}

edge DependsOn {
    has required: bool = True;
}

edge AuthoringRoot {
    has role: str = "root";
}

edge CompilesTo {
    has stage: str = "";
}

edge LegacyTransfer {
    has parity_oracle: bool = True;
}

walker WaveGateAuditor {
    has seen: list[int] = [];
    has wave_cleared: bool = True;
    has audit_order: list[int] = [];

    can start with Root entry {
        print("M12 wave gate: dependency-ordered slice audit");
        visit [-->];
    }

    can audit with LegacySlice entry {
        if here.issue_num in self.seen {
            print(f"[CYCLE] blocking revisit of #{here.issue_num}");
            disengage;
        }
        self.seen.append(here.issue_num);
        if here.blocking_findings > 0 {
            self.wave_cleared = False;
            verdict = "BLOCKING";
        } elif not here.transferred {
            verdict = "TRANSFER";
        } else {
            verdict = "OK";
        }
        print(f"[{verdict}] #{here.issue_num} {here.slice_name}");
        self.audit_order.append(here.issue_num);
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker CanonicalCompiler {
    has plan_fingerprint: str = "";

    can start with Root entry {
        print("Canonical compile: IntegrationSpecV1 + ProcessAuthoringUnitV1 -> ProcessIR");
        visit [->:AuthoringRoot:->] else { disengage; };
    }

    can on_spec with IntegrationSpecV1 entry {
        lock_state = "locked" if here.pipeline_locked else "VIOLATION";
        print(f"[SPEC] {here.title} pipeline {lock_state}");
        visit [->:AuthoringRoot:->];
        visit [->:CompilesTo:->] else { disengage; };
    }

    can on_unit with ProcessAuthoringUnitV1 entry {
        gate_label = "gated" if here.capability_gated else "ungated";
        print(f"[UNIT] {here.unit_id} ({gate_label})");
        visit [->:CompilesTo:->] else { disengage; };
    }

    can materialize with ProcessIR entry {
        here.level_one = True;
        here.level_two = True;
        here.attested = here.level_one and here.level_two;
        self.plan_fingerprint = here.fingerprint;
        print(f"[ProcessIR] fingerprint={here.fingerprint} attested={here.attested}");
        disengage;
    }
}

walker LegacyReachabilityInventory {
    has seen: list[str] = [];
    has reachable_untransferred: int = 0;

    can start with Root entry {
        print("Legacy reachability inventory before #160 deletion");
        visit [->:LegacyTransfer:->] else { disengage; };
    }

    can probe with LegacySlice entry {
        key = f"{here.issue_num}:{here.slice_name}";
        if key in self.seen {
            print(f"[CYCLE] legacy path revisits {key}");
            disengage;
        }
        self.seen.append(key);
        if not here.transferred {
            self.reachable_untransferred += 1;
            print(f"[LEGACY] #{here.issue_num} {here.slice_name} reachable, not transferred");
        } else {
            print(f"[RETIRED] #{here.issue_num} {here.slice_name} parity oracle only");
        }
        visit [->:LegacyTransfer:->] else { disengage; };
    }

    can confirm with ProcessIR entry {
        status = "canonical authority" if here.attested else "pending attestation";
        print(f"[TARGET] ProcessIR is {status}");
        disengage;
    }
}

with entry {
    spec = IntegrationSpecV1(title="boomi-integration", pipeline_locked=True);
    unit = ProcessAuthoringUnitV1(unit_id="T1-direct-apply", capability_gated=True);
    ir = ProcessIR(fingerprint="plan:relocatable:9f3a2c");

    root +>:AuthoringRoot(role="spec"):+> spec;
    spec +>:AuthoringRoot(role="unit"):+> unit;
    spec +>:CompilesTo(stage="fingerprint"):+> ir;
    unit +>:CompilesTo(stage="emit_process"):+> ir;

    s152 = LegacySlice(
        issue_num=152,
        slice_name="M12.13 gate automation",
        transferred=True,
        blocking_findings=0
    );
    s149 = LegacySlice(
        issue_num=149,
        slice_name="M12.12 reachability inventory",
        transferred=True,
        blocking_findings=0
    );
    s151 = LegacySlice(
        issue_num=151,
        slice_name="M12.14 flow_sequence parity",
        transferred=False,
        blocking_findings=0
    );
    s153 = LegacySlice(
        issue_num=153,
        slice_name="M12.15 ProcessIR materialization",
        transferred=True,
        blocking_findings=0
    );
    flow_legacy = LegacySlice(
        issue_num=160,
        slice_name="flow_sequence adapter",
        transferred=False,
        blocking_findings=0
    );

    root ++> s152;
    root ++> s149;
    s152 +>:DependsOn(required=True):+> s151;
    s149 +>:DependsOn(required=True):+> s151;
    s152 +>:DependsOn(required=True):+> s153;
    s149 +>:DependsOn(required=True):+> s153;
    s151 +>:DependsOn(required=True):+> s153;
    s151 +>:LegacyTransfer(parity_oracle=True):+> flow_legacy;
    flow_legacy +>:LegacyTransfer(parity_oracle=True):+> ir;

    gate = WaveGateAuditor();
    root spawn gate;
    root spawn CanonicalCompiler();
    reach = LegacyReachabilityInventory();
    root spawn reach;

    print(f"wave_cleared={gate.wave_cleared} audit_order={gate.audit_order}");
    print(f"legacy still reachable={reach.reachable_untransferred}");
}
