# Plain nodes with no payload — pure traversal markers.
node Waypoint {}

walker Hiker {
    has stops_passed: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        print("Setting off from the trailhead...");
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops_passed += 1;
        print(f"Stop {self.stops_passed} reached");

        if self.stops_passed >= self.target_stops {
            print("Trail complete — summit reached!");
            disengage;
        }

        visit [-->] else { disengage; }
    }
}

with entry {
    # A chain of anonymous waypoints from trailhead to summit.
    # Each ++> adds another plain marker; none carry data.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    root spawn Hiker(target_stops=5);
}
