"""Toll plaza G-4: collect per-vehicle fares and report total revenue."""

node Vehicle {
    has kind: str = "";
    has plates: str = "";
    has tons: float = 0.0;
}

walker Collector {
    has revenue: float = 0.0;

    can start with Root entry {
        print("Gate G-4 sweep begins");
        visit [-->] else { disengage; }
    }

    can charge with Vehicle entry {
        fare = 0.0;
        if here.kind == "car" {
            fare = 2.50;
            print(f"Car  {here.plates}: $2.50");
        } elif here.kind == "truck" {
            extra = 0.50 * here.tons;
            fare = 2.50 + extra;
            print(f"Truck {here.plates} ({here.tons}t): $2.50 + $0.50x{here.tons} = ${fare:.2f}");
        } elif here.kind == "motorcycle" {
            fare = 1.00;
            print(f"Moto {here.plates}: $1.00");
        } else {
            print(f"Unknown vehicle {here.plates} (kind={here.kind}): skipped");
        }
        self.revenue = self.revenue + fare;
        visit [-->] else { disengage; }
    }
}

