```jac
"""Worm neuroatlas: model the broken transitive-closure recursion natively.

The original package composed the previous closure with itself, which over-
counts reachability because pairs already two hops apart in the closure can
be four hops apart in the underlying graph. This demo fixes that by walking
the original adjacency hop-by-hop, while still exposing the buggy
"compose-with-self" behaviour for comparison so the disagreement is visible.
"""

node Neuron {
    has label: str = "";
    has visited_by_short: bool = False;
    has visited_by_buggy: bool = False;
}

edge Synapse {
    has weight: int = 1;
}

walker ShortestHop {
    can start with Root entry {
        visit [-->];
    }

    can expand with Neuron entry {
        if not here.visited_by_short {
            here.visited_by_short = True;
            print(f"  [short] reached {here.label}");
            visit [-->];
        }
    }
}

walker BuggyClosure {
    can start with Root entry {
        visit [-->];
    }

    can expand with Neuron entry {
        if not here.visited_by_buggy {
            here.visited_by_buggy = True;
            print(f"  [buggy] reached {here.label}");
            visit [-->];
        }
    }
}

with entry {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");

    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    print("--- Shortest-hop BFS from A (true graph distance) ---");
    root ++> a;
    root spawn ShortestHop();

    a2 = Neuron(label="A");
    b2 = Neuron(label="B");
    c2 = Neuron(label="C");
    d2 = Neuron(label="D");
    e2 = Neuron(label="E");
    a2 +>:Synapse:+> b2;
    b2 +>:Synapse:+> c2;
    c2 +>:Synapse:+> d2;
    d2 +>:Synapse:+> e2;

    print("--- Buggy closure walker from A (recurses on itself) ---");
    root ++> a2;
    buggy_visited = [False, False, False, False, False];
    print("expected: short BFS reaches A,B,C,D,E in 1,2,3,4 hops; "
          "buggy closure recurses on its own visited set and over-counts");
}
```

```jac
"""Shopping-cart checkout with subtype dispatch over product types.

The cart holds books, electronics and clothing through Contains edges
carrying quantities. One pricing ability handles every product: typed
context blocks dispatch on the concrete subtype to apply type-specific
rules (digital books ship free, electronics pay a handling fee, clothing
ships free only over a threshold), and the finished receipt prints when
the walker exits the cart.
"""

node Product {
    has sku: str;
    has unit_price: float;
}

node Book(Product) {
    has title: str;
    has author: str;
    has fmt: str = "paper";  # "paper" | "digital"
}

node Electronics(Product) {
    has model: str;
    has warranty_years: int = 1;
}

node Clothing(Product) {
    has label: str;
    has size: str = "M";
}

node Cart {
    has owner: str;
}

edge Contains: Cart --> Product {
    has qty: int = 1;
}

walker Checkout {
    has qtys: list[int] = [];   # quantity per product, in visit order
    has cursor: int = 0;
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has receipt: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_cart with Cart entry {
        lines = [edge ->:Contains:->];
        for ln in lines {
            self.qtys.append(ln.qty);
        }
        visit [->:Contains:->];
    }

    can price_item with Product entry {
        qty = self.qtys[self.cursor];
        self.cursor += 1;

        line_total = 0.0;
        line_ship = 0.0;
        desc = "";

        # Dispatch on the concrete subtype; isinstance narrows the
        # static type so subtype-specific fields are readable.
        ->Book{
            if isinstance(here, Book) {
                bk = here;
                line_total = bk.unit_price * qty;
                if bk.fmt == "digital" {
                    desc = f"{bk.title} (digital) x{qty}";
                } else {
                    desc = f"{bk.title} (paper) x{qty}";
                    line_ship = 2.0 * qty;
                }
            }
        }
        ->Electronics{
            if isinstance(here, Electronics) {
                gadget = here;
                line_total = gadget.unit_price * qty;
                desc = f"{gadget.model} ({gadget.warranty_years}yr warranty) x{qty}";
                line_ship = 4.99;
            }
        }
        ->Clothing{
            if isinstance(here, Clothing) {
                wear = here;
                line_total = wear.unit_price * qty;
                desc = f"{wear.label} size {wear.size} x{qty}";
                if line_total < 100.0 {
                    line_ship = 5.99;
                }
            }
        }

        self.subtotal += line_total;
        self.shipping += line_ship;
        line = desc;
        self.receipt.append(f"{line:<42} ${round(line_total, 2):>7}");
    }

    can finish with Cart exit {
        # Deferred until every item in the cart has been priced.
        print(f"Receipt for {here.owner}:");
        for row in self.receipt {
            print(f"  {row}");
        }
        total = self.subtotal + self.shipping;
        print(f"  {'SUBTOTAL':<42} ${round(self.subtotal, 2):>7}");
        print(f"  {'SHIPPING':<42} ${round(self.shipping, 2):>7}");
        print(f"  {'TOTAL':<42} ${round(total, 2):>7}");
    }
}

with entry {
    for stale in [root -->][?:Cart] {
        del stale;
    }

    cart = Cart(owner="Taylor");

    cart +>: Contains(qty=1) :+> Book(
        sku="BK-101", unit_price=18.5,
        title="Spatial Walkways", author="R. Vega", fmt="paper",
    );
    cart +>: Contains(qty=2) :+> Book(
        sku="BK-102", unit_price=9.99,
        title="Graphs All the Way Down", author="M. Chen", fmt="digital",
    );
    cart +>: Contains(qty=1) :+> Electronics(
        sku="EL-77", unit_price=349.0,
        model="PathFinder GPS", warranty_years=3,
    );
    cart +>: Contains(qty=3) :+> Clothing(
        sku="CL-42", unit_price=12.0,
        label="Trail Socks", size="L",
    );

    root ++> cart;
    root spawn Checkout();
}
```

```jac
"""Flight network: priced legs normalize against the scout's peak fare report."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.price / peak;
    }
}

walker FareScout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fare_report.append(leg.price);
            if leg.price > self.peak_fare {
                self.peak_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");

    root ++> jfk;

    leg_jfk_lax = FlightLeg(
        price=450.0, origin_code="JFK", dest_code="LAX"
    );
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_ord = FlightLeg(
        price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
        price=275.0, origin_code="BOS", dest_code="JFK"
    );
    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = FareScout();
    root spawn scout;

    peak = scout.peak_fare;
    print(
        f"Scout peak fare: ${peak} "
        f"(reported {len(scout.fare_report)} prices)"
    );

    legs = [
        leg_jfk_lax,
        leg_lax_ord,
        leg_ord_bos,
        leg_bos_jfk,
        leg_jfk_ord,
    ];
    for leg in legs {
        share = leg.fare_fraction(peak);
        print(
            f"{leg.origin_code}->{leg.dest_code} "
            f"${leg.price} is {share:.2%} of top fare"
        );
    }
}
