```jac
"""Bug tracker: connect-and-grab a ticket node from the project root.

Demonstrates the grouped connection form (``root ++> (t := Ticket(...));``)
which returns the freshly created node, so we can read its fields right
away instead of running a separate lookup query. A FilingClerk walker
spawned on the root walks the ticket tree and prints every filed ticket.
"""

node Ticket {
    has title: str = "";
    has priority: str = "low";

    def describe() -> str {
        return f"[{self.priority.upper()}] {self.title}";
    }
}

walker FilingClerk {
    can start with Root entry {
        print("Filing clerk opening the queue");
        visit [-->];
    }

    can file with Ticket entry {
        print(f"filed ticket: {here.describe()}");
        visit [-->];
    }
}

with entry {
    # Connect-and-grab: the parentheses around `(t := Ticket(...))` make
    # the connection expression return the new node, captured as `t`.
    root ++> (t := Ticket(title="Login button broken", priority="high"));
    print(f"captured immediately: {t.describe()}");

    # A second ticket using the same pattern for a low-priority typo.
    root ++> (t2 := Ticket(title="Typo in footer", priority="low"));
    print(f"captured immediately: {t2.describe()}");

    # Now walk the tree with a FilingClerk walker so the traversal is real.
    root spawn FilingClerk();
}
