```jac
"""Order auditor: invalid orders are skipped, fraudulent orders halt the walk.

Demonstrates two flavors of early return side by side:
  - skip-like: re-enter traversal after reporting a skipped order.
  - halt-like: bail out of the entire walk on fraud.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted_on: str = "";

    can start with Root entry {
        print("Audit begins");
        visit [-->] else { disengage; }
    }

    can review with Order entry {
        # Fraud halts the whole walk -- disengage on the spot.
        if here.fraud {
            self.halted_on = here.label;
            print(f"[HALT] fraud detected on {here.label} (${here.amount:.2f})");
            disengage;
        }

        # Invalid orders are skipped -- audit keeps going.
        if not here.valid {
            self.skipped += 1;
            print(f"[SKIP] {here.label} (${here.amount:.2f}) invalid");
            visit [-->] else { disengage; }
        } else {
            # Happy path: record the audit and keep walking.
            self.audited += 1;
            print(f"[OK]   {here.label} (${here.amount:.2f})");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(label="A-1001", amount=42.50, valid=True)
        ++> Order(label="A-1002", amount=19.99, valid=False)
        ++> Order(label="A-1003", amount=125.00, valid=True)
        ++> Order(label="A-1004", amount=7.25, valid=True)
        ++> Order(label="A-1005", amount=999.99, valid=True, fraud=True)
        ++> Order(label="A-1006", amount=55.00, valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    print(
        f"Audit summary: audited={auditor.audited} "
        f"skipped={auditor.skipped} "
        f"halted_on={auditor.halted_on}"
    );
}
