```jac
"""JSON Schema external $ref chains: modular schema files linked across files must be collected without JVM call-stack overflow."""

node SchemaFile {
    has filename: str = "";
    has schema_type: str = "";
    has fragment_name: str = "def";
}

edge ExternalRef {
    has ref_path: str = "";
    has fragment: str = "#/def";
}

walker RecursiveParser {
    has call_depth: int = 0;
    has stack_ceiling: int = 8;
    has overflowed: bool = False;

    can start with Root entry {
        print(f"Simulated JVM stack recursion (ceiling={self.stack_ceiling})");
        visit [->:ExternalRef:->] else { disengage; };
    }

    can collect_refs with SchemaFile entry {
        self.call_depth += 1;
        if self.call_depth > self.stack_ceiling {
            print(f"  StackOverflowError at {here.filename} (depth={self.call_depth})");
            self.overflowed = True;
            disengage;
        }
        print(f"  recurse depth={self.call_depth} {here.filename}");
        visit [->:ExternalRef:->] else { disengage; };
    }
}

walker RefCollector {
    has files_parsed: int = 0;
    has collected: list[str] = [];

    can start with Root entry {
        print("Iterative $ref collection via walker traversal (explicit frontier)");
        visit [->:ExternalRef:->] else { disengage; };
    }

    can parse_file with SchemaFile entry {
        self.files_parsed += 1;
        kind = "leaf" if here.schema_type == "string" else "chain";
        print(f"  [{self.files_parsed}] {here.filename} ({kind}, type={here.schema_type})");
        self.collected.append(here.filename);
        visit [->:ExternalRef:->] else { disengage; };
    }
}

with entry {
    chain_len = 15;
    files = [];
    for i in range(chain_len) {
        typ = "string" if i == chain_len - 1 else "ref";
        files.append(SchemaFile(
            filename=f"f{i}.json",
            schema_type=typ,
            fragment_name="def"
        ));
    }
    for i in range(chain_len - 1) {
        nxt = i + 1;
        files[i] +>:ExternalRef(
            ref_path=f"f{nxt}.json",
            fragment="#/def"
        ):+> files[nxt];
    }
    root +>:ExternalRef(ref_path="f0.json", fragment="#/def"):+> files[0];

    recursive = RecursiveParser(stack_ceiling=8);
    root spawn recursive;

    collector = RefCollector();
    root spawn collector;

    print(f"Recursive simulator overflowed={recursive.overflowed} at depth {recursive.call_depth}");
    print(f"Iterative collector parsed {collector.files_parsed}/{chain_len} files: "
          f"{collector.collected[-1]}");
}
