```jac
"""Delivery route eligibility checker.

Each route node carries a cargo weight in tonnes. A truck may only be
dispatched on a route whose load is between 2 and 8 tonnes (inclusive).
A walker walks the depots and prints every qualifying route.
"""

node Route {
    has label: str = "";
    has weight: float = 0.0;

    def is_dispatchable() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

node Depot {
    has name: str = "";

    def report_route(route: Route) -> None {
        verdict = "DISPATCH" if route.is_dispatchable() else "HOLD";
        print(f"[{verdict}] {route.label} ({route.weight}t) via {self.name}");
    }
}

walker Dispatcher {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Depot entry {
        print(f"--- Checking routes from {here.name} ---");
        visit [-->];
    }

    can audit with Route entry {
        origin = [<--][0];
        origin.report_route(here);
        visit [-->];
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");

    root ++> north;
    root ++> south;

    north ++> Route(label="NA-01", weight=7.5);
    north ++> Route(label="NA-02", weight=1.2);
    north ++> Route(label="NA-03", weight=8.0);

    south ++> Route(label="SA-01", weight=2.0);
    south ++> Route(label="SA-02", weight=9.3);
    south ++> Route(label="SA-03", weight=5.6);

    root spawn Dispatcher();
}
