```jac
"""Order auditor demonstrating both flavors of early return.

Invalid orders are skipped (``continue``-style, audit keeps going on later
orders), while a fraud-flagged order halts the entire walk immediately
(``break``-style, audit stops). Each order prints which action fired.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("Auditor: beginning walk");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.fraud {
            self.halted = True;
            print(f"[HALT] {here.label} flagged for fraud (${here.amount:.2f}) -- stopping the whole walk");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.label} invalid (${here.amount:.2f}) -- moving on");
            visit [-->] else { disengage; }
        } else {
            self.audited += 1;
            print(f"[OK]   {here.label} amount=${here.amount:.2f}");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(label="ORD-001", amount=120.50)
        ++> Order(label="ORD-002", amount=0.00, valid=False)
        ++> Order(label="ORD-003", amount=899.99)
        ++> Order(label="ORD-004", amount=4200.00, fraud=True)
        ++> Order(label="ORD-005", amount=55.25);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"Final: audited={auditor.audited}, halted={auditor.halted}");
}
