```jac
"""Online store checkout: typed products with kind-specific shipping rules.

One ``Checkout`` walker visits each ``Product`` and dispatches via a
union ability per concrete type, so the same routine reacts correctly
to paper books, digital books, electronics, and clothing.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;
}

node PaperBook(Product) {
    has weight_lbs: float = 0.0;

    def shipping_cost() -> float {
        # Flat $3 plus $1 per pound.
        return 3.0 + self.weight_lbs;
    }

    def kind_label() -> str {
        return "Paper book";
    }
}

node DigitalBook(Product) {
    has file_size_mb: float = 0.0;

    def shipping_cost() -> float {
        # No physical shipping for digital goods.
        return 0.0;
    }

    def kind_label() -> str {
        return "Digital book";
    }
}

node Electronics(Product) {
    has warranty_months: int = 0;

    def shipping_cost() -> float {
        # Fragile handling surcharge on top of a $7 base.
        return 7.0 + 2.5;
    }

    def kind_label() -> str {
        return "Electronics";
    }
}

node Clothing(Product) {
    has size: str = "";

    def shipping_cost() -> float {
        # Lightweight flat rate.
        return 4.0;
    }

    def kind_label() -> str {
        return f"Clothing (size {self.size})";
    }
}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list[str] = [];

    can start with Root entry {
        print("=== Checkout ===");
        visit [-->];
    }

    can bill with PaperBook | DigitalBook | Electronics | Clothing entry {
        line = here.kind_label();
        cost = here.price + here.shipping_cost();
        self.subtotal += here.price;
        self.shipping += here.shipping_cost();
        self.lines.append(f"{line}: ${here.price:.2f} + ship ${here.shipping_cost():.2f} = ${cost:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> PaperBook(name="The Pragmatic Programmer", price=29.99, weight_lbs=1.2)
        ++> DigitalBook(name="Jac by Example", price=14.99, file_size_mb=8.4)
        ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24)
        ++> Clothing(name="Crewneck Tee", price=22.50, size="M");

    cart = root spawn Checkout();

    print("\n--- Itemized receipt ---");
    for ln in cart.lines {
        print(ln);
    }
    print(f"Subtotal: ${cart.subtotal:.2f}");
    print(f"Shipping: ${cart.shipping:.2f}");
    print(f"Total:    ${cart.subtotal + cart.shipping:.2f}");
}
