```jac
"""Kitchen line health inspection: check station temperatures, flag violations, and log every station visit."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violation_count: int = 0;

    def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: station '{self.name}' logged");
    }

    def check_temperature() -> None {
        if self.temperature > 40.0 {
            self.violation_count += 1;
            print(f"  VIOLATION at '{self.name}': {self.temperature} C exceeds 40 C "
                  f"(total violations: {self.violation_count})");
        } else {
            print(f"  OK: '{self.name}' at {self.temperature} C");
        }
    }
}

# Cold prep station: stays safe below 40 C.
node ColdPrep(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: cold-prep station '{self.name}' logged");
    }
}

# Grill station: hot, but flag if it drifts above 40 C (probe misplacement).
node Grill(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: grill station '{self.name}' logged");
    }
}

# Fryer station: hot oil, flag if it drifts above 40 C.
node Fryer(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: fryer station '{self.name}' logged");
    }
}

walker Inspector {
    has station_count: int = 0;

    can start with Root entry {
        print("Inspector starting kitchen line walk...");
        visit [-->];
    }

    can check_station with ColdPrep | Grill | Fryer entry {
        self.station_count += 1;
        # Both checks run at every station.
        here.log_visit(self.station_count);
        here.check_temperature();
        visit [-->];
    }
}

with entry {
    # Build the kitchen line.
    grill = Grill(name="Grill #1", temperature=185.0);
    fryer = Fryer(name="Fryer #2", temperature=160.0);
    cold = ColdPrep(name="Salad Cold Prep", temperature=4.0);

    root ++> grill ++> fryer ++> cold;

    # Spawn the inspector on the root; the union ability fires at each station.
    root spawn Inspector();
}
