```jac
"""Build system dependency audit.

Models a build graph where tasks depend on shared libraries (diamond
dependency). A walker audits each task exactly once even though the graph
may be reached via multiple paths, and sums the build minutes of every
distinct task visited.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has available: bool = True;
}

walker Auditor {
    has audited_titles: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        already = False;
        for name in self.audited_titles {
            if name == here.title {
                already = True;
            }
        }
        if not already {
            self.audited_titles.append(here.title);
            self.total_minutes += here.minutes;
            print(f"[AUDIT] {here.title} (+{here.minutes} min)");
        } else {
            print(f"[skip ] {here.title} already audited");
        }
        visit [-->];
    }
}

with entry {
    shared_lib = Task(title="shared_lib", minutes=10);
    compiler = Task(title="compiler", minutes=20);
    linker = Task(title="linker", minutes=15);
    app_a = Task(title="app_a", minutes=30);
    app_b = Task(title="app_b", minutes=25);

    # Diamond: app_a and app_b both depend on compiler, linker, and
    # shared_lib. Traversal from root reaches the shared nodes via more
    # than one path; the walker must count each task exactly once.
    root ++> compiler
        ++> shared_lib
        ++> linker
        ++> app_a
        ++> app_b;

    root spawn Auditor();
    print("dependency graph audited");
}
```

